$Config = [PSCustomObject]@{
    LocalScript = "C:\EspritICT\audit-update.ps1"
    # v3.99: apart, klein lanceerscript - zie changelog bij New-AutoStartHooks.
    LauncherScript = "C:\EspritICT\audit-launch.ps1"
    TaskName    = "AuditWindowsUpdate"
    StateFile   = "C:\EspritICT\audit-state.json"
    CrashFile   = "C:\EspritICT\audit-sysprep-started.flag"
    LocalLogDir = "C:\EspritICT\AuditLogs"
    BatchSize   = 10
    # Moet in de pas lopen met het versienummer bovenin dit bestand.
    ToolVersion = "4.35"
    # W. Europe Standard Time = Nederland (CET/CEST, automatische DST) -
