# v4.22 (security officer punt 2): GEEN Defender-uitzondering meer. Zelfherstel: oude uitzonderingen op onze werkmappen weghalen en terugleggen.
function Remove-OudeDefenderUitzonderingen {
    param([string[]]$Paden = @('C:\Windows\Temp', 'C:\EspritICT'))
    $res = [pscustomobject]@{ Aanwezig = @(); Resterend = @(); Fout = '' }
    try {
        $nu = @((Get-MpPreference -ErrorAction Stop).ExclusionPath) | Where-Object { $_ }
        $res.Aanwezig = @($nu | Where-Object { $p = $_; @($Paden | Where-Object { $p -ieq $_ }).Count -gt 0 })
        foreach ($p in $res.Aanwezig) { try { Remove-MpPreference -ExclusionPath $p -ErrorAction Stop } catch { $res.Fout += "$p : $($_.Exception.Message); " } }
        $na = @((Get-MpPreference -ErrorAction Stop).ExclusionPath) | Where-Object { $_ }
        $res.Resterend = @($na | Where-Object { $p = $_; @($Paden | Where-Object { $p -ieq $_ }).Count -gt 0 })
    } catch { $res.Fout += $_.Exception.Message }
    return $res
}
$Script:DefenderHerstel = $null; try { $Script:DefenderHerstel = Remove-OudeDefenderUitzonderingen } catch {}

