# v4.22 (security officer punt 2): kopieren met controle (zonder Defender-uitzondering kan Defender het bestand heel even vergrendelen)
function Copy-BestandGeverifieerd {
    param([string]$Bron, [string]$Doel, [int]$MaxPogingen = 5, [int]$PauzeSec = 2)
    $res = [pscustomobject]@{ Gelukt = $false; Pogingen = 0; Fout = '' }
    for ($i = 1; $i -le $MaxPogingen; $i++) {
        $res.Pogingen = $i
        try {
            [IO.File]::Copy($Bron, $Doel, $true)
            $h1 = (Get-FileHash -LiteralPath $Bron -Algorithm SHA256 -ErrorAction Stop).Hash; $h2 = (Get-FileHash -LiteralPath $Doel -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($h1 -eq $h2) { $res.Gelukt = $true; $res.Fout = ''; return $res }
            $res.Fout = 'SHA-256 van de kopie verschilt van de bron'
        } catch { $res.Fout = $_.Exception.Message }
        if ($i -lt $MaxPogingen) { Start-Sleep -Seconds $PauzeSec }
    }
    return $res
}
# v4.22 (security officer punt 3): BitLocker hervatten MET bewijs (status moet 'On' zijn), tot 3 pogingen.
function Resume-BitLockerGeverifieerd {
    param([string]$Mount = $env:SystemDrive, [int]$MaxPogingen = 3, [int]$PauzeSec = 3)
    $res = [pscustomobject]@{ Gelukt = $false; Pogingen = 0; Status = ''; Fout = '' }
    for ($i = 1; $i -le $MaxPogingen; $i++) {
        $res.Pogingen = $i
        try { Resume-BitLocker -MountPoint $Mount -ErrorAction Stop } catch { $res.Fout = $_.Exception.Message }
        try {
            Start-Sleep -Seconds 2
            $v = Get-BitLockerVolume -MountPoint $Mount -ErrorAction Stop
            $res.Status = "$($v.ProtectionStatus)"
            if ($res.Status -eq 'On') { $res.Gelukt = $true; $res.Fout = ''; return $res }
            if (-not $res.Fout) { $res.Fout = "status na hervatten is '$($res.Status)', niet 'On'" }
        } catch { $res.Fout = $_.Exception.Message }
        if ($i -lt $MaxPogingen) { Start-Sleep -Seconds $PauzeSec }
    }
    return $res
}
# v4.22 (security officer punt 6): 'updates ondanks fouten afgerond' wordt een expliciete markering met reden, geen stil succes.
function Set-UpdatesNietAfgerond {
    param([string]$Reden)
    try {
        $oud = ''; if ($State.PSObject.Properties.Name -contains 'UpdatesNietAfgerondReden') { $oud = "$($State.UpdatesNietAfgerondReden)" }
        $State | Add-Member -NotePropertyName UpdatesNietAfgerond -NotePropertyValue $true -Force
        $State | Add-Member -NotePropertyName UpdatesNietAfgerondReden -NotePropertyValue ((@($oud, $Reden) | Where-Object { $_ }) -join ' | ') -Force
        Save-State $State
        Log "[LET OP] updates NIET afgerond, maar de pogingen zijn op: $Reden - dit toestel gaat NIET zonder bewuste vrijgave naar Sysprep." -Color Red
    } catch {}
}
function Invoke-UpdatesNietAfgerondPoort {
    param([double]$WachtMin = 0, [string]$LokaalVrijgave = 'C:\EspritICT\verificatie-vrijgave.txt')
    if ($WachtMin -le 0) { $WachtMin = 30; try { if ($WachtOpEngineerMin) { $WachtMin = [double]$WachtOpEngineerMin } } catch {} }
    $reden = "$($State.UpdatesNietAfgerondReden)"
    $serie = "$Serial" -replace '[^A-Za-z0-9_-]', ''
    $sd = $null; try { $sd = Get-StatusDirVroeg } catch {}
    $srv = ''; if ($sd -and $serie) { $srv = Join-Path $sd ("vrijgave\" + $serie + ".txt") }
    try { if ($srv -and (Test-Path -LiteralPath $srv)) { [IO.File]::Delete($srv) } } catch {}
    try { if (Test-Path -LiteralPath $LokaalVrijgave) { [IO.File]::Delete($LokaalVrijgave) } } catch {}
    Log "==================================================" -Color Red
    Log "  STOP VOOR SYSPREP - updates NIET afgerond" -Color Red
    Log "==================================================" -Color Red
    Log "  Reden : $reden" -Color Red
    Log "  Een toestel met niet-afgeronde updates gaat NIET vanzelf naar de klant. Vrijgeven is een bewuste keuze van een engineer: dashboard-knop Vrijgeven, of scripts\181-vrijgeven.ps1 op de server (serie $serie), of maak hier het bestand $LokaalVrijgave." -Color Red
    Log "  Zonder vrijgave binnen $WachtMin min stopt het script hier: het toestel blijft in Audit Mode (geen Sysprep)." -Color Red
    $Script:VerificatieStatus = 'stop'; $Script:VerificatieSinds = (Get-Date).ToString('yyyyMMddHHmmss'); $Script:LaatsteStatusTijd = $null
    try { Send-ServerStatus -Fase "STOP VOOR SYSPREP - updates niet afgerond (engineer nodig)" } catch {}
    $eind = (Get-Date).AddMinutes($WachtMin); $nood = Get-Date
    while ((Get-Date) -lt $eind) {
        Start-Sleep -Seconds 5
        try { Update-Heartbeat } catch {}
        if (($srv -and (Test-Path -LiteralPath $srv)) -or (Test-Path -LiteralPath $LokaalVrijgave)) {
            Log "  [LET OP] vrijgegeven door een engineer terwijl updates NIET afgerond zijn ($reden) - het toestel gaat door als 'klaar met voorbehoud'." -Color Yellow
            $Script:VerificatieStatus = 'afgerond'; $Script:LaatsteStatusTijd = $null
            try { Send-ServerStatus -Fase "Vrijgegeven door engineer (updates niet afgerond) - door naar Sysprep" } catch {}
            return $true
        }
        if (((Get-Date) - $nood).TotalSeconds -ge 30) { $nood = Get-Date; try { if (Test-NoodStop) { Write-Host ""; Invoke-NoodStop } } catch {} }
    }
    Log "  Geen vrijgave binnen $WachtMin min: het script stopt. Het toestel blijft in Audit Mode (geen Sysprep). Engineer: los de updates op of geef vrij en start het script opnieuw (C:\EspritICT\audit-update.ps1)." -Color Red
    try { $State | Add-Member -NotePropertyName SysprepGeblokkeerdUpdates -NotePropertyValue $true -Force; Save-State $State } catch {}
    try { Send-ServerStatus -Fase "STOP VOOR SYSPREP - updates niet afgerond (geen vrijgave)" } catch {}
    exit
}
