function Remove-OudeVangnetPublic {
    param([string]$PublicMap = 'C:\Users\Public\AuditVangnet', [string]$StartupCmd = 'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\StartUp\AuditVangnetSurvive.cmd', [string[]]$RunSleutels = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce', 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'), [string]$WaardeNaam = 'AuditWindowsUpdateSurvive')
    $res = [pscustomobject]@{ Gevonden = @(); Resterend = @(); Fout = '' }
    try {
        foreach ($k in $RunSleutels) { try { $w = (Get-ItemProperty -Path $k -Name $WaardeNaam -ErrorAction Stop).$WaardeNaam; if ($null -ne $w) { $res.Gevonden += "$k\$WaardeNaam"; Remove-ItemProperty -Path $k -Name $WaardeNaam -ErrorAction Stop } } catch {} }
        if (Test-Path -LiteralPath $StartupCmd) { $res.Gevonden += $StartupCmd; try { [IO.File]::SetAttributes($StartupCmd, [IO.FileAttributes]::Normal); [IO.File]::Delete($StartupCmd) } catch { $res.Fout += "$StartupCmd : $($_.Exception.Message); " } }
        if (Test-Path -LiteralPath $PublicMap) { $res.Gevonden += $PublicMap; try { [IO.Directory]::Delete($PublicMap, $true) } catch { $res.Fout += "$PublicMap : $($_.Exception.Message); " } }
        if (Test-Path -LiteralPath $StartupCmd) { $res.Resterend += $StartupCmd }
        if (Test-Path -LiteralPath $PublicMap) { $res.Resterend += $PublicMap }
        foreach ($k in $RunSleutels) { try { $w2 = (Get-ItemProperty -Path $k -Name $WaardeNaam -ErrorAction Stop).$WaardeNaam; if ($null -ne $w2) { $res.Resterend += "$k\$WaardeNaam" } } catch {} }
    } catch { $res.Fout += $_.Exception.Message }
    return $res
}
