function Test-DriveWritable {
    param([string]$DriveRoot)
    if (-not (Test-Path $DriveRoot)) { return $false }
    $testFile = Join-Path $DriveRoot "audit-write-test.tmp"
    try {
        [System.IO.File]::WriteAllText($testFile, "test")
        Remove-Item $testFile -Force -ErrorAction SilentlyContinue
        return $true
    } catch { return $false }
}

function Get-UsbCandidates {
    # Zoekt alle stationsletters die via USB aangesloten zijn,
    # ongeacht of Windows ze als Removable of Fixed rapporteert.
    $letters = [System.Collections.ArrayList]@()
    try {
        Get-Volume | Where-Object { $_.DriveType -eq 'Removable' -and $_.DriveLetter } |
            ForEach-Object { [void]$letters.Add($_.DriveLetter) }
    } catch {}
    try {
        Get-Disk | Where-Object { $_.BusType -eq 'USB' } | ForEach-Object {
            Get-Partition -DiskNumber $_.Number -ErrorAction SilentlyContinue |
                Where-Object { $_.DriveLetter -and ($letters -notcontains $_.DriveLetter) } |
                ForEach-Object { [void]$letters.Add($_.DriveLetter) }
        }
    } catch {}
    return $letters
}

