# NOODSTOP  (v3.8, n.a.v. 033135623657 op 13 juli): tijdens sommige
# schermen - vooral wanneer Windows ZELF een featureupdate afrondt -
# is er geen Shift+F10 beschikbaar om fix.cmd te draaien, dus geen
# interactieve manier om in te grijpen. Dit geeft een uitweg die HEEL
# GEEN toegang tot het toestel zelf nodig heeft: steek een willekeurige
# USB-stick met een bestand genaamd STOP.txt in de root erin (bv. op
# een andere pc voorbereid), en het script stopt zichzelf bij de
# eerstvolgende controle - geen cmd-scherm nodig. Wordt gecontroleerd
# bij elke scriptstart en tijdens lange wachtlussen.
# ----------------------------------------------------------------
# v4.10 (14 okt 2026): noodstop vanaf de SERVER. scripts\207-stop-laptop.ps1 zet <status>\stop\<serienummer>.txt; elke bestaande noodstop-controle ziet dat hier ook.
function Test-ServerStop {
    try {
        if (-not $Serial -or -not $State -or -not $State.RunStartedAt) { return $false }
        $nu = Get-Date
        $wacht = if ($Script:ServerStopTraag) { 120 } else { 20 }
        if ($Script:ServerStopCheckTijd -and (($nu - $Script:ServerStopCheckTijd).TotalSeconds -lt $wacht)) { return [bool]$Script:ServerStopGevonden }
        $Script:ServerStopCheckTijd = $nu
        $sd = Get-StatusDirVroeg
        if (-not $sd) { return $false }
        $sw = [Diagnostics.Stopwatch]::StartNew()
        $pad = Join-Path $sd ("stop\" + $Serial + ".txt")
        $bestaat = Test-Path -LiteralPath $pad
        $Script:ServerStopTraag = ($sw.Elapsed.TotalSeconds -gt 5)
        if (-not $bestaat) { return $false }
        $vlagUtc = (Get-Item -LiteralPath $pad).LastWriteTimeUtc
        $startUtc = ([datetimeoffset]::Parse("$($State.RunStartedAt)")).UtcDateTime
        if ($vlagUtc -le $startUtc) {
            if (-not $Script:ServerStopOudGelogd) { $Script:ServerStopOudGelogd = $true; Log "Stopbestand op de server is ouder dan deze run ($($vlagUtc.ToString('s')) <= $($startUtc.ToString('s')) UTC) - genegeerd." -Color Gray }
            return $false
        }
        $Script:ServerStopGevonden = $true
        return $true
    } catch { return $false }
}
function Test-NoodStop {
    foreach ($letter in (Get-UsbCandidates)) {
        if (Test-Path "$($letter):\STOP.txt" -ErrorAction SilentlyContinue) { return $true }
    }
    if (Test-ServerStop) { return $true }
    return $false
}
function Invoke-NoodStop {
    Log "=================================================="  -Color Red
    Log "  NOODSTOP: STOP.txt op USB of stopopdracht van de server - script stopt" -Color Red
    try { Send-ServerStatus -Fase "NOODSTOP - script gestopt" } catch {}
    Log "=================================================="  -Color Red
    try { & shutdown /a 2>&1 | Out-Null } catch {}
    try { Set-ItemProperty "HKLM:\SYSTEM\Setup" -Name "CmdLine"        -Value "" -Force } catch {}
    try { Set-ItemProperty "HKLM:\SYSTEM\Setup" -Name "SetupType"      -Value 0  -Type DWord -Force } catch {}
    try { Set-ItemProperty "HKLM:\SYSTEM\Setup" -Name "AuditInProgress" -Value 0 -Type DWord -Force } catch {}
    try { Remove-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run"     -Name $Config.TaskName -ErrorAction SilentlyContinue } catch {}
    try { Remove-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce" -Name $Config.TaskName -ErrorAction SilentlyContinue } catch {}
    try { Unregister-ScheduledTask -TaskName $Config.TaskName -Confirm:$false -ErrorAction SilentlyContinue } catch {}
    try { Remove-Item "C:\Windows\System32\Sysprep\unattend.xml" -Force -ErrorAction SilentlyContinue } catch {}
    try { Remove-Item $Config.StateFile   -Force -ErrorAction SilentlyContinue } catch {}
    try { Remove-Item $Config.LocalScript -Force -ErrorAction SilentlyContinue } catch {}

    # v(audit 27 aug 2026, "kernpatroon beweerd succes zonder verificatie" uit CLAUDE.md):
    # tot nu toe claimde dit ONVOORWAARDELIJK "herstart NIET meer automatisch", terwijl geen
    # van de opruimacties hierboven ooit teruggelezen werd - precies de fout die dit project
    # al meermaals is opgevallen bij andere commando's. Dit IS de noodstop-route (de enige
    # garantie die een technicus heeft als er iets goed mis is) - een silent-gefaalde
    # taakverwijdering zou het toestel alsnog automatisch laten doorstarten, terwijl het log
    # het tegendeel beweert. Nu een echte her-check van de twee mechanismes die een herstart
    # daadwerkelijk kunnen veroorzaken (Run/RunOnce-registry, Scheduled Task).
    $nogActief = [System.Collections.ArrayList]@()
    try {
        if (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run" -Name $Config.TaskName -ErrorAction SilentlyContinue) {
            [void]$nogActief.Add("Run-registrysleutel")
        }
    } catch {}
    try {
        if (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce" -Name $Config.TaskName -ErrorAction SilentlyContinue) {
            [void]$nogActief.Add("RunOnce-registrysleutel")
        }
    } catch {}
    try {
        if (Get-ScheduledTask -TaskName $Config.TaskName -ErrorAction SilentlyContinue) {
            [void]$nogActief.Add("Scheduled Task")
        }
    } catch {}

    if ($nogActief.Count -gt 0) {
        Log "[WAARSCHUWING] Niet alle autostart-hooks zijn weg: $($nogActief -join ', ') staat/staan nog actief." -Color Red
        Log "Het toestel kan alsnog automatisch herstarten ondanks de noodstop - controleer dit handmatig (Taakplanner/regedit) voor je weggaat." -Color Red
    } else {
        Log "Geverifieerd: Run/RunOnce/Scheduled Task zijn echt weg - toestel herstart niet meer automatisch." -Color Yellow
    }
    Log "State + scriptkopie verwijderd." -Color Yellow
    Log "Verwijder STOP.txt van de USB voor je opnieuw begint - anders stopt de volgende run meteen weer." -Color Yellow
    exit 0
}

# ----------------------------------------------------------------
# EVENTLOG-CONTROLE VOOR SYSPREP  (v3.8, n.a.v. 033135623657 op 13
# juli): Sysprep struikelde met een generieke "onherstelbare fout"
# (setupact.log: EvtIntSysprepCleanup faalde, dwRet=0x6ba - RPC-server
# niet beschikbaar). Bleek de EventLog-service te zijn: STOPPED,
# WIN32_EXIT_CODE 1077 (ERROR_SERVICE_NEVER_STARTED) - nooit gestart
# sinds de laatste boot, om onbekende reden. Handmatig `sc start
# eventlog` loste het toen op. Sysprep's eigen cleanup-fase praat via
# RPC met deze service, dus zonder EventLog draaiend faalt Sysprep
# altijd op dit punt - dit hier controleert en herstelt dat VOOR
# Sysprep start, zodat dit niet meer met de hand hoeft.
# ----------------------------------------------------------------
function Confirm-EventLogService {
    try {
        $svc = Get-Service -Name "EventLog" -ErrorAction Stop
        if ($svc.Status -eq "Running") {
            Log "EventLog-service draait (vereist voor Sysprep)" -Color Gray
            return $true
        }
        Log "EventLog-service staat op '$($svc.Status)' i.p.v. Running - dit blokkeert Sysprep (RPC). Proberen te starten..." -Color Yellow
        Start-Service -Name "EventLog" -ErrorAction Stop
        Start-Sleep 3
        $svc.Refresh()
        if ($svc.Status -eq "Running") {
            Log "EventLog-service succesvol gestart" -Color Green
            return $true
        } else {
            Log "EventLog-service start niet door (status: $($svc.Status)) - Sysprep zal waarschijnlijk falen op EvtIntSysprepCleanup" -Color Red
            return $false
        }
    } catch {
        Log "Kon EventLog-service niet controleren/starten: $_" -Color Red
        return $false
    }
}

# ----------------------------------------------------------------
# v3.70 BUGFIX (bevestigd op 5CD115BH5J, 22 juli 2026): $searcher.Search()
# is een blokkerende COM-aanroep zonder eigen wachtlus/heartbeat - het
# script bleef hier 16+ minuten muisstil hangen op "Scannen op
# updates...", Roderick moest zelf ingrijpen met Ctrl+C om verder te
# komen. De bestaande try/catch rond deze aanroepen ving alleen ECHTE
# COM-exceptions op (0x80240438 e.d.) - een complete hang gooit geen
# exception, er komt gewoon nooit antwoord, dus die bestaande vangnetten
# hielpen hier niet.
#
# Test-WuaResponsive draait een kleine, wegwerp-testzoekopdracht in een
# apart ACHTERGRONDPROCES (Start-Job - een nieuw proces, dus geen COM-
# apartment-problemen met de hoofdthread) met een harde tijdslimiet. Dit
# bevestigt alleen OF de WU Agent op dit moment reageert; de eigenlijke,
# echte zoekopdracht blijft daarna gewoon in de hoofdthread lopen zoals
# altijd (nodig, want de levende COM-update-objecten kunnen niet over de
# procesgrens heen - bv. voor de daadwerkelijke installatiestap verderop).
# Bij elke aanroepplek: "if (-not (Test-WuaResponsive)) { throw ... }"
# vlak vÃ³Ã³r de echte Search()-aanroep, BINNEN de bestaande try/catch -
# zo hergebruikt een hang gewoon het al bestaande, beproefde
# herstelpad (gecontroleerde reboot) i.p.v. een nieuw mechanisme te
# bouwen.
# ----------------------------------------------------------------
function Test-WuaResponsive {
    param([int]$TimeoutSec = 180)
    try {
        $job = Start-Job -ScriptBlock {
            $session  = New-Object -ComObject Microsoft.Update.Session
            $searcher = $session.CreateUpdateSearcher()
            $result   = $searcher.Search("IsInstalled=0")
        if ($State.WuFoutAantal) { $State.WuFoutAantal = 0; $State.WuFoutLaatste = "" }   # v3.252: scan lukte, foutteller terug op 0
            return $result.Updates.Count
        }
        $klaar = Wait-Job -Job $job -Timeout $TimeoutSec
        if (-not $klaar) {
            Log "  WU Agent-gezondheidscheck: geen reactie binnen $TimeoutSec sec" -Color Yellow
            Stop-Job -Job $job -ErrorAction SilentlyContinue
            Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
            return $false
        }
        Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
        return $true
    } catch {
        # Kon de test zelf niet uitvoeren (bv. Start-Job niet beschikbaar in
        # deze context) - niet blokkeren op deze EXTRA controle, gewoon
        # aannemen dat het goed komt en de bestaande try/catch om de
        # echte aanroep laten afhandelen wat er ook gebeurt.
        return $true
    }
}

# ----------------------------------------------------------------
# v3.77 BUGFIX (bevestigd op 5CG0174GFN, HP EliteBook 850 G6, update-only
# modus, 23 juli 2026): "winget upgrade --all" bleef muisstil hangen -
# geen enkele logregel meer na de kale overzichtslijst (20 pakketten,
# waaronder Citrix Workspace/Adobe Acrobat/LibreOffice - allemaal bekend
# om soms tOch een eigen install-venster/reboot-melding te tonen ondanks
# --silent, als winget's manifest die specifieke installer niet volledig
# stil kan krijgen). Zelfde bugpatroon als de WUA-hang (v3.70) en de
# download-vastloper (v3.74): een blokkerende externe aanroep zonder
# enige tijdslimiet. Kwam bovendien op TWEE plekken identiek voor
# (sectie 20b en sectie 21) - nu Ã©Ã©n gedeelde functie i.p.v. de logica
# straks op 2 plekken uit elkaar te laten lopen.
# Bewust Start-Process (i.p.v. Start-Job zoals Test-WuaResponsive) - dat
# is het patroon dat elders in dit script al bewezen werkt voor externe
# .exe-aanroepen (HPIA, setup.exe), en blijft in dezelfde sessie/context
# draaien i.p.v. in een aparte achtergrond-runspace. Winget is zelf een
# MSIX-pakket met eigen sessie-eigenaardigheden - Start-Job (nieuwe
# runspace) is daar minder beproefd voor, Start-Process is dat wel.
# Tijdslimiet: 20 min - ruim voldoende voor een gezonde batch van
# tientallen apps (in de praktijk meestal binnen 5-10 min klaar), maar
# geen oneindige hang meer bij Ã©Ã©n vastgelopen installatieprogramma.
# Lokaal getest (dummy snel proces + een echt vastgelopen dummy-proces,
# beide met .Kill()-verificatie) - daarbij een ECHTE bug gevonden voordat
# 'ie live ging: zonder eerst .Handle op te vragen bleef $proc.ExitCode
# achteraf altijd $null (bekende .NET-eigenaardigheid), ook bij een
# volledig geslaagde run - de exitcode-check zou dan altijd de verkeerde
# (foutmeldings-)tak kiezen. Opgelost door .Handle vast te pakken vlak na
# Start-Process, vóór de wachtlus.
# ----------------------------------------------------------------
# ----------------------------------------------------------------
# v3.82, op verzoek van Roderick ("als er iets wordt geupdate, geen
# bureaubladicoon aanmaken, gewoon zo laten zoals het is"): sommige
# winget-installers/updaters zetten tijdens een upgrade een nieuwe
# snelkoppeling op het bureaublad neer, ook als de gebruiker die niet had
# of niet wil. GECONTROLEERD (niet verzonnen): winget zelf heeft hier geen
# vlag voor - meerdere, nog altijd openstaande feature-requests op
# microsoft/winget-cli (issues #1045, #1545, #6068) bevestigen dat dit een
# bekende, tot op heden onopgeloste beperking van winget zelf is, geen
# instelbare optie. Generieke oplossing i.p.v. per-installer-uitzonderingen
# bijhouden: het bureaublad (zowel het eigen als het gedeelde/Public-
# bureaublad, want winget-pakketten kunnen op beide terechtkomen)
# fotograferen vlak vOOr de upgrade, en na afloop alleen de NIEUW
# bijgekomen snelkoppelingen (.lnk/.url) weer verwijderen - de rest van
# het bureaublad blijft ongemoeid.
# ----------------------------------------------------------------
function Get-DesktopShortcutSnapshot {
    $paden = @()
    try { $paden += [Environment]::GetFolderPath("Desktop") } catch {}
    try { $paden += [Environment]::GetFolderPath("CommonDesktopDirectory") } catch {}
    $paden = $paden | Where-Object { $_ -and (Test-Path $_) } | Select-Object -Unique

    $snapshot = @{}
    foreach ($pad in $paden) {
        $bestanden  = @(Get-ChildItem -Path $pad -Filter "*.lnk" -File -ErrorAction SilentlyContinue)
        $bestanden += @(Get-ChildItem -Path $pad -Filter "*.url" -File -ErrorAction SilentlyContinue)
        $snapshot[$pad] = @($bestanden | Select-Object -ExpandProperty Name)
    }
    return $snapshot
}

# v3.91 BUGFIX (bevestigd op 5CG0174GFN, HP EliteBook 850 G6, update-only
# modus, 24 juli 2026): het script bleef muisstil hangen ná "Nieuw
# bureaubladpictogram verwijderd... Firefox.lnk" - geen herstart (Roderick
# zat nog gewoon op het bureaubladscherm), moest handmatig met Ctrl+C
# afgebroken worden. Metrics bevestigen: "phase_start" voor "Software-
# updates (winget)" zonder ooit een "phase_end" - de run kwam hier
# definitief nooit meer uit. Op dat punt was winget zelf al klaar (de
# opruimregel loopt pas NA het winget-proces), dus geen winget-hang. De
# code na die opruimregel bevat geen enkele lus - dus geen "echte" hang in
# dit script zelf, maar een onderliggende Windows-bestandsactie (bestand
# verwijderen/oplijsten op het bureaublad) die kennelijk niet terugkwam
# (bv. een virusscanner die een net aangemaakte snelkoppeling vasthoudt).
# Deze opruimfunctie (v3.82) had, in tegenstelling tot de WUA-installatie
# (v3.84, Invoke-WithSpinner -MaxWaitSec) en winget zelf (eigen 20-min-
# timeout hieronder), GEEN eigen tijdslimiet - hing die vast, dan hing de
# hele run vast, zonder zelfherstel. Fix: dezelfde Start-Job/Wait-Job
# -Timeout aanpak als Test-WuaResponsive (v3.70, ook al bewezen op deze
# manier) - de opruiming draait nu in een apart achtergrondproces met een
# harde grens (60 sec, ruim boven de normaal geziene <1 sec), en bij een
# timeout wordt de job geforceerd gestopt en gaat de run gewoon door (dit
# is pure cosmetische opruiming, nooit kritiek genoeg om op te wachten).
# Extra: de winget-uitvoer werd voorheen pas NA deze opruimstap gelogd (in
# de aanroepende code) - kwam de opruiming niet meer terug, dan ging ook
# de al lang bekende, daadwerkelijke winget-uitvoer (welke pakketten
# geslaagd/mislukt waren) verloren, ook al had winget zelf allang succes
# gemeld. Nu logt Invoke-WingetUpgradeAllSafe die uitvoer zelf, meteen
# nadat winget klaar is en VOORDAT de (nu begrensde) opruiming aan de
# beurt is - dus zelfs bij een hernieuwde opruim-hang staat de echte
# uitkomst al veilig in het log. Lokaal getest: Start-Job/Wait-Job
# -Timeout-logica met een dummy-map (bestaande snelkoppeling blijft staan,
# nieuwe wordt verwijderd en gelogd, kunstmatig vertraagd scriptblok geeft
# na de tijdslimiet netjes de waarschuwing en gaat door) - de onderliggende
# oorzaak van de vastgelopen Windows-bestandsactie zelf blijft onbekend/
# niet met zekerheid vast te stellen zonder een virusscanner-log op het
# toestel zelf; dit vangt 'm alleen op zodat de run niet meer vastloopt.
function Remove-NewDesktopShortcuts {
    # v3.145, op verzoek van Roderick (29 juli 2026: "als hij veel softwareupdates draait
    # waar al een snelkoppeling van is, werken die snelkoppelingen daarna nog wel?"):
    # deze functie ruimde tot nu toe alleen ONGEVRAAGDE NIEUWE pictogrammen op (v3.82) -
    # er was geen enkele controle of een BESTAAND pictogram na een winget-upgrade nog wel
    # naar iets werkends wijst. Reëel risico: als winget een programma vervangt door het
    # naar een ANDERE map te installeren (bv. een versie-genummerde submap) en de
    # installer de bestaande snelkoppeling niet zelf bijwerkt, blijft die wijzen naar een
    # inmiddels verdwenen pad - een "dode" snelkoppeling, tot nu toe onopgemerkt.
    # Uitdrukkelijk NIET geautomatiseerd "gerepareerd" (op Roderick's eigen keuze, na
    # expliciet voorgelegd te hebben): er is geen betrouwbare, generieke manier om te
    # weten waar een willekeurig programma zijn nieuwe versie neerzet - dat verschilt per
    # toepassing en is niet uit winget zelf af te leiden. Alleen DETECTEREN en duidelijk
    # MELDEN (log + eindsamenvatting via $Script:ManualDriverCheckNeeded), zodat het
    # opvalt in plaats van stilzwijgend kapot te blijven. Alleen .lnk-bestanden
    # gecontroleerd (.url-bestanden wijzen naar een webadres/appdeeplink, geen lokaal
    # bestandspad om op te controleren). Zelfde Start-Job/timeout-patroon als de
    # bestaande opruimstap hierboven (v3.91-hang-fix) - nu in dezelfde job meegenomen
    # i.p.v. een aparte job erbij, geen extra doorlooptijd.
    param([hashtable]$VoorSnapshot, [int]$TimeoutSec = 60)
    $job = Start-Job -ScriptBlock {
        param($VoorSnapshot)
        $verwijderd = @()
        $mislukt    = @()
        $gebroken   = @()
        $shell = New-Object -ComObject WScript.Shell
        foreach ($pad in $VoorSnapshot.Keys) {
            if (-not (Test-Path $pad)) { continue }
            $huidige  = @(Get-ChildItem -Path $pad -Filter "*.lnk" -File -ErrorAction SilentlyContinue)
            $huidige += @(Get-ChildItem -Path $pad -Filter "*.url" -File -ErrorAction SilentlyContinue)
            foreach ($bestand in $huidige) {
                if ($VoorSnapshot[$pad] -notcontains $bestand.Name) {
                    try {
                        Remove-Item $bestand.FullName -Force -ErrorAction Stop
                        $verwijderd += $bestand.Name
                    } catch {
                        $mislukt += "$($bestand.Name) - $_"
                    }
                } elseif ($bestand.Extension -eq ".lnk") {
                    # Bestond al vóór de update - bewust niet aangeraakt, alleen
                    # controleren of het doel nog bestaat.
                    try {
                        $doel = $shell.CreateShortcut($bestand.FullName).TargetPath
                        if ($doel -and -not (Test-Path $doel)) {
                            $gebroken += "$($bestand.Name) (wijst naar: $doel)"
                        }
                    } catch {}
                }
            }
        }
        [PSCustomObject]@{ Verwijderd = $verwijderd; Mislukt = $mislukt; Gebroken = $gebroken }
    } -ArgumentList $VoorSnapshot

    if (Wait-Job $job -Timeout $TimeoutSec) {
        $resultaat = Receive-Job $job -ErrorAction SilentlyContinue
        foreach ($naam in $resultaat.Verwijderd) {
            Log "  Nieuw bureaubladpictogram verwijderd (door een installer aangemaakt, niet gevraagd): $naam" -Color Gray
        }
        foreach ($fout in $resultaat.Mislukt) {
            Log "  Kon nieuw bureaubladpictogram niet verwijderen: $fout" -Color Yellow
        }
        foreach ($kapot in $resultaat.Gebroken) {
            Log "  Bestaand bureaubladpictogram werkt mogelijk niet meer na de software-update: $kapot" -Color Yellow
            [void]$Script:ManualDriverCheckNeeded.Add("Bureaubladpictogram mogelijk kapot na software-update: $kapot")
        }
    } else {
        Log "  Bureaubladpictogrammen controleren/opruimen duurde langer dan $TimeoutSec sec - overgeslagen (niet fataal, een ongevraagd of kapot pictogram kan blijven staan)." -Color Yellow
    }
    Remove-Job $job -Force -ErrorAction SilentlyContinue
}

function Invoke-WingetUpgradeAllSafe {
    param([int]$TimeoutSec = 1200)
    $tempOut = [System.IO.Path]::GetTempFileName()
    $tempErr = [System.IO.Path]::GetTempFileName()
    $bureaubladVoor = Get-DesktopShortcutSnapshot
    try {
        $proc = Start-Process -FilePath "winget.exe" -ArgumentList @(
            "upgrade", "--all", "--silent",
            "--accept-package-agreements", "--accept-source-agreements"
        ) -PassThru -NoNewWindow -RedirectStandardOutput $tempOut -RedirectStandardError $tempErr

        # Lokaal getest, bevestigde .NET-eigenaardigheid: zonder .Handle hier vast
        # te pakken bleef $proc.ExitCode achteraf ALTIJD $null, ook bij een
        # volledig geslaagde run - de "-eq 0"-check hieronder zou dan altijd
        # naar de verkeerde (foutmeldings-)tak gaan. .Handle opvragen voordat
        # het proces stopt lost dit betrouwbaar op.
        $null = $proc.Handle
        $klaar = $proc.WaitForExit($TimeoutSec * 1000)
        if (-not $klaar) {
            # v3.120: Stop-ProcessTree i.p.v. een kale Kill() - zelfde risico als de
            # v3.119-bug (zie Stop-ProcessTree-changelog): winget kan zelf een
            # installerproces per app spawnen (bv. msiexec.exe), en een kale
            # Kill() op het winget.exe-hoofdproces laat zo'n kind gewoon actief
            # staan, met kans op eenzelfde 1618/mutex-vervolgprobleem.
            try { Stop-ProcessTree -ProcessId $proc.Id } catch {}
            return [PSCustomObject]@{ Output = @(); Exit = $null; TimedOut = $true }
        }
        $output = @(Get-Content $tempOut -ErrorAction SilentlyContinue) + @(Get-Content $tempErr -ErrorAction SilentlyContinue)
        # v3.91: uitvoer NU al loggen, VOORDAT de (finally-)opruiming
        # hieronder aan de beurt is - zie changelog bij Remove-
        # NewDesktopShortcuts. Zo blijft de daadwerkelijke winget-uitkomst
        # zichtbaar in het log, ook als die opruimstap zelf vastloopt.
        Log "  winget upgrade --all uitvoer:" -Color Gray
        foreach ($regel in $output) { Log "    $regel" -Color Gray }
        return [PSCustomObject]@{ Output = $output; Exit = $proc.ExitCode; TimedOut = $false }
    } finally {
        # v3.82: ongeacht of de upgrade slaagde, vastliep of een fout gaf -
        # eventuele nieuwe bureaubladpictogrammen altijd opruimen.
        try { Remove-NewDesktopShortcuts -VoorSnapshot $bureaubladVoor } catch {}
        Remove-Item $tempOut, $tempErr -Force -ErrorAction SilentlyContinue
    }
}

# ----------------------------------------------------------------
# v3.78 BUGFIX (bevestigd op 5CG0174GFN, HP EliteBook 850 G6, update-only
# modus, 23 juli 2026): direct na een (onverwachte, door een winget-
# installer zelf getriggerde) herstart meldde "Get-Command winget" niets
# - "winget niet beschikbaar - software-updates overgeslagen" - terwijl
# winget een half uur eerder in dezelfde run gewoon werkte. Bevestigd
# patroon (community-bronnen over winget): de "App Execution Alias" waar
# Get-Command op vertrouwt is vlak na een verse opstart/sessiestart niet
# altijd meteen actief. Drie plekken in dit script deden exact dezelfde,
# ogenblikkelijke "Get-Command winget"-check (Software-updates-fase,
# OEM-winget-fallback voor onherkende fabrikanten, Dell Command Update-
# installatie via winget) - nu Ã©Ã©n gedeelde functie met een korte
# herkansing i.p.v. de check op 3 plekken los te laten uiteenlopen.
# ----------------------------------------------------------------
function Invoke-WingetInstallSafe {
    # v3.136, op verzoek van Roderick (29 juli 2026): per-klant software
    # installeren (bv. AutoCAD/Office) via "winget install" - zelfde bewezen
    # Start-Process+.Handle+WaitForExit+Stop-ProcessTree-patroon als
    # Invoke-WingetUpgradeAllSafe hierboven. BEWUST GEEN
    # Remove-NewDesktopShortcuts hier: bij een upgrade is een nieuw
    # bureaubladpictogram een ongevraagd bijeffect (v3.82), bij een
    # expliciete installatie op klantverzoek is een pictogram juist
    # verwacht/gewenst. Langere default-tijdslimiet (30 min) dan de
    # upgrade-route (20 min): een eerste, volledige installatie (Office/
    # AutoCAD: honderden MB tot een paar GB) duurt doorgaans langer dan het
    # bijwerken van iets dat al grotendeels aanwezig is. $WingetExe is
    # injecteerbaar (default "winget.exe", ongewijzigd voor normaal
    # gebruik) zodat dit lokaal tegen een neppe stand-in te testen is
    # zonder echt software te installeren - zie de changelog hierboven voor
    # het testverslag.
    param(
        [Parameter(Mandatory)][string]$PackageId,
        [int]$TimeoutSec = 1800,
        [string]$WingetExe = "winget.exe",
        # v3.212 (24 augustus 2026, 49D6PQ2 LIVE gevonden): optionele -Scope-parameter,
        # standaard leeg (GEEN gedragswijziging voor bestaande aanroepen zoals de per-
        # klant software-installaties). ECHT uitgezocht (webresearch, na een
        # winget-installatie die faalde met STATUS_DLL_NOT_FOUND onder SYSTEM): een
        # bekende, gedocumenteerde aanbeveling is "als je onder SYSTEM draait, gebruik
        # expliciet --scope machine" (AppX/Store-installatiepad onder SYSTEM is
        # onbetrouwbaar zonder die expliciete scope). Alleen de nieuwe Dell-Command-
        # Update-afhankelijkheidsinstallatie (.NET Desktop Runtime) geeft dit vooralsnog
        # expliciet mee - NOG NIET live bevestigd of dit de STATUS_DLL_NOT_FOUND-fout
        # daadwerkelijk oplost.
        [string]$Scope = "",
        # v3.218 (25 augustus 2026 avond, vervolg op v3.210-212's onderzoek: winget is
        # OFFICIEEL niet ondersteund onder NT AUTHORITY\SYSTEM in Windows PowerShell 5.1 -
        # zie [[project_winget_install_system_context_s4u_plan]], --scope machine alleen was
        # een laag-risico mitigatie, geen echte oplossing). DE ECHTE OPLOSSING: winget laten
        # draaien als de daadwerkelijk interactief aangemelde gebruiker (defaultuser0/
        # Beheerder tijdens Audit Mode) i.p.v. als SYSTEM, via een eenmalige S4U-Taakplanner-
        # taak - officiële Microsoft-techniek, GEEN wachtwoord nodig (de gebruiker is al
        # aangemeld, S4U hergebruikt die bestaande aanmelding). Standaard UIT (GEEN
        # gedragswijziging voor bestaande aanroepen) - alleen de Dell Command Update-tak en de
        # bijbehorende .NET Desktop Runtime-afhankelijkheid geven dit nu expliciet mee.
        # Hergebruikt Get-InteractiveUserSid (gedeeld met Invoke-LiveScriptInteractiveSpawn,
        # CLAUDE.md-regel 4). LET OP, ander logontype dan live.ps1's Interactive-aanpak
        # hiernaast: S4U i.p.v. Interactive - winget heeft geen zichtbaar venster nodig (in
        # tegenstelling tot live.ps1), alleen de gebruiker-context/profiel voor MSIX/AppX-
        # registratie. S4U werkt bovendien ook als de interactieve desktop niet volledig
        # "aandacht" heeft, robuuster voor dit specifieke, onzichtbare doel.
        [switch]$AsInteractiveUser
    )
    if ($AsInteractiveUser) {
        return Invoke-WingetInstallAsInteractiveUser -PackageId $PackageId -TimeoutSec $TimeoutSec -WingetExe $WingetExe -Scope $Scope
    }
    $tempOut = [System.IO.Path]::GetTempFileName()
    $tempErr = [System.IO.Path]::GetTempFileName()
    try {
        $installArgs = @("install", "--id", $PackageId, "--exact", "--silent",
            "--accept-package-agreements", "--accept-source-agreements")
        if ($Scope) { $installArgs += @("--scope", $Scope) }
        $proc = Start-Process -FilePath $WingetExe -ArgumentList $installArgs `
            -PassThru -NoNewWindow -RedirectStandardOutput $tempOut -RedirectStandardError $tempErr

        # Zelfde .Handle-eigenaardigheid als Invoke-WingetUpgradeAllSafe
        # (lokaal bevestigd nodig voor een betrouwbare ExitCode, zie die
        # changelog-toelichting).
        $null = $proc.Handle
        $klaar = $proc.WaitForExit($TimeoutSec * 1000)
        if (-not $klaar) {
            try { Stop-ProcessTree -ProcessId $proc.Id } catch {}
            return [PSCustomObject]@{ Output = @(); Exit = $null; TimedOut = $true }
        }
        $output = @(Get-Content $tempOut -ErrorAction SilentlyContinue) + @(Get-Content $tempErr -ErrorAction SilentlyContinue)
        return [PSCustomObject]@{ Output = $output; Exit = $proc.ExitCode; TimedOut = $false }
    } finally {
        Remove-Item $tempOut, $tempErr -Force -ErrorAction SilentlyContinue
    }
}

# v3.218: aparte functie (niet inline in Invoke-WingetInstallSafe) - fundamenteel ander
# uitvoeringspad (S4U-Taakplanner-taak i.p.v. rechtstreekse Start-Process), verdient een
# eigen naam/leesbare scheiding i.p.v. één functie met twee sterk uiteenlopende takken.
# Retourneert HETZELFDE contract als Invoke-WingetInstallSafe (Output/Exit/TimedOut) zodat
# bestaande aanroepers hun afhandeling niet hoeven aan te passen.
function Invoke-WingetInstallAsInteractiveUser {
    param(
        [Parameter(Mandatory)][string]$PackageId,
        [int]$TimeoutSec = 1800,
        [string]$WingetExe = "winget.exe",
        [string]$Scope = ""
    )
    $sid = Get-InteractiveUserSid
    if (-not $sid) {
        Log "  Winget-als-interactieve-gebruiker: geen actieve interactieve sessie gevonden (quser) - kan niet via deze route, terugval op de aanroeper." -Color Gray
        return [PSCustomObject]@{ Output = @("Geen interactieve sessie gevonden"); Exit = $null; TimedOut = $false }
    }

    $werkId       = [Guid]::NewGuid().ToString("N").Substring(0, 8)
    $launcherPad  = "C:\EspritICT\winget-s4u-launch-$werkId.ps1"
    $resultaatPad = "C:\EspritICT\winget-s4u-result-$werkId.txt"
    $outPad       = "C:\EspritICT\winget-s4u-out-$werkId.txt"
    $errPad       = "C:\EspritICT\winget-s4u-err-$werkId.txt"

    $installArgs = @("install", "--id", $PackageId, "--exact", "--silent",
        "--accept-package-agreements", "--accept-source-agreements")
    if ($Scope) { $installArgs += @("--scope", $Scope) }
    # Los lanceerscript i.p.v. een inline -Command-string - zelfde, lokaal bevestigde les als
    # Invoke-LiveScriptInteractiveSpawn (een inline -Command bleek onbetrouwbaar te quoten,
    # een los .ps1-bestand met -File werkte 100% betrouwbaar).
    $argsLiteraal = ($installArgs | ForEach-Object { "'$($_ -replace "'", "''")'" }) -join ", "
    $launcherInhoud = @"
`$p = Start-Process -FilePath '$WingetExe' -ArgumentList @($argsLiteraal) -PassThru -NoNewWindow -RedirectStandardOutput '$outPad' -RedirectStandardError '$errPad' -Wait
Set-Content -Path '$resultaatPad' -Value `$p.ExitCode
"@
    Set-Content -Path $launcherPad -Value $launcherInhoud -Force -Encoding UTF8

    $taskName = "$($Config.TaskName)WingetS4U"
    try { Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue } catch {}

    try {
        $action    = New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$launcherPad`""
        # S4U (Service-for-User): draait met het bestaande token van de opgegeven gebruiker,
        # GEEN wachtwoord nodig (in tegenstelling tot LogonType Password) - officieel
        # gedocumenteerde Microsoft-techniek, zie [[project_winget_install_system_context_s4u_plan]].
        $principal = New-ScheduledTaskPrincipal -UserId $sid -LogonType S4U -RunLevel Highest
        $settings  = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Seconds $TimeoutSec)

        Register-ScheduledTask -TaskName $taskName -Action $action -Principal $principal -Settings $settings -Force -ErrorAction Stop | Out-Null
        Start-ScheduledTask -TaskName $taskName -ErrorAction Stop
    } catch {
        Log "  Winget-als-interactieve-gebruiker: S4U-taak registreren/starten mislukt ($_) - terugval op de aanroeper." -Color Gray
        try { Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue } catch {}
        return [PSCustomObject]@{ Output = @("S4U-taak registreren/starten mislukt: $_"); Exit = $null; TimedOut = $false }
    }

    $verstreken = 0
    $poll = 2
    while ($verstreken -lt $TimeoutSec -and -not (Test-Path $resultaatPad)) {
        Start-Sleep -Seconds $poll
        $verstreken += $poll
    }

    $timedOut = -not (Test-Path $resultaatPad)
    $exitCode = $null
    if (-not $timedOut) {
        try { $exitCode = [int](Get-Content $resultaatPad -Raw -ErrorAction Stop).Trim() } catch {}
    }
    $output = @(Get-Content $outPad -ErrorAction SilentlyContinue) + @(Get-Content $errPad -ErrorAction SilentlyContinue)

    try { Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue } catch {}
    Remove-Item $launcherPad, $resultaatPad, $outPad, $errPad -Force -ErrorAction SilentlyContinue

    if ($timedOut) {
        return [PSCustomObject]@{ Output = $output; Exit = $null; TimedOut = $true }
    }
    return [PSCustomObject]@{ Output = $output; Exit = $exitCode; TimedOut = $false }
}

function Test-WingetPackageInstalled {
    # v3.136: echte verificatie i.p.v. exitcode vertrouwen ("beweerd succes
    # zonder verificatie"-patroon, zie CLAUDE.md) - gebruikt zowel VOOR een
    # installatiepoging (overslaan als al aanwezig, tijdwinst) als ERNA
    # (bevestigen dat het echt gelukt is, niet aannemen op basis van
    # exitcode alleen).
    param(
        [Parameter(Mandatory)][string]$PackageId,
        [string]$WingetExe = "winget.exe"
    )
    try {
        $out = & $WingetExe list --id $PackageId --exact --accept-source-agreements 2>&1
        return ($LASTEXITCODE -eq 0) -and (($out -join "`n") -match [regex]::Escape($PackageId))
    } catch {
        return $false
    }
}

function Wait-ForWinget {
    # v3.141 BUGFIX, bevestigd op PW0FC5BB (Lenovo 21KH, 29 juli 2026, klant
    # "Rental" - de eerste keer ooit dat SoftwareUpdates=Ja op dit toestel
    # daadwerkelijk geraakt werd): "winget niet beschikbaar" na de volle
    # wachttijd - en omdat deze specifieke run geen volgende herstart meer
    # kreeg, is winget upgrade voor deze levering toen stilzwijgend nooit
    # gelukt (de belofte "volgende doorloop opnieuw proberen" werd niet
    # ingelost). Root cause OPGEZOCHT (niet gegokt), bevestigd via meerdere
    # onafhankelijke community-bronnen (microsoft/winget-cli GitHub-issues
    # #4422 en #2721, call4cloud.nl, njen.com - allemaal onafhankelijk tot
    # dezelfde conclusie): "App Execution Aliases" (waar `Get-Command
    # winget` op leunt) werken NIET onder NT AUTHORITY\SYSTEM - dat account
    # heeft geen normaal gebruikersprofiel waarin zo'n alias geregistreerd
    # kan worden. Dit was dus GEEN timing-probleem (langer wachten had hier
    # nooit geholpen, ongeacht de duur) maar een structurele SYSTEM-context-
    # beperking. Verklaart ook waarom dit tot nu toe soms toevallig wel
    # leek te werken (StoreUpdates/SoftwareUpdates stonden bij alle eerdere
    # runs op "Nee" - dit pad is hier feitelijk voor het eerst echt beproefd).
    # Fix, uit dezelfde bronnen (het gedocumenteerde standaard-workaround):
    # de map met het echte winget.exe (staat gewoon op schijf onder
    # WindowsApps, alleen niet op PATH bij SYSTEM) rechtstreeks opzoeken en
    # TOEVOEGEN aan $env:PATH voor dit proces. Daarna werken zowel
    # Get-Command winget hier als de bestaande kale "& winget ..."-aanroepen
    # elders in dit script (5 plekken) ongewijzigd, zonder dat elke
    # aanroepplek zelf een volledig pad hoeft te kennen - één centrale fix
    # i.p.v. 5x dezelfde padresolutie te dupliceren.
    param([int]$MaxWaitSec = 30, [int]$IntervalSec = 5)
    $verstreken = 0
    while ($verstreken -lt $MaxWaitSec) {
        $cmd = Get-Command winget -ErrorAction SilentlyContinue
        if ($cmd) { return $cmd }
        Start-Sleep $IntervalSec
        $verstreken += $IntervalSec
    }

    # v3.141: PATH-alias niet gevonden binnen de wachttijd - probeer het
    # echte winget.exe rechtstreeks te vinden onder WindowsApps (bekende,
    # stabiele publisher-ID "8wekyb3d8bbwe" voor Microsoft's eigen
    # DesktopAppInstaller-pakket, bevestigd via meerdere community-bronnen)
    # en die map alsnog aan PATH toevoegen voor de rest van deze run.
    try {
        $wingetExe = Get-ChildItem -Path "$env:ProgramFiles\WindowsApps\Microsoft.DesktopAppInstaller_*_x64__8wekyb3d8bbwe\winget.exe" -ErrorAction SilentlyContinue |
            Sort-Object FullName -Descending | Select-Object -First 1
        if ($wingetExe) {
            $wingetDir = $wingetExe.DirectoryName
            if (($env:PATH -split ';') -notcontains $wingetDir) {
                $env:PATH = "$wingetDir;$env:PATH"
            }
            $cmd = Get-Command winget -ErrorAction SilentlyContinue
            if ($cmd) {
                Log "  winget niet via de normale alias gevonden (bekende beperking onder SYSTEM) - rechtstreeks gevonden onder WindowsApps en aan PATH toegevoegd." -Color Gray
                return $cmd
            }
        }
    } catch {}
    return $null
}

