# v3.264 (4 okt 2026, op verzoek: "valt dat niet te loggen ipv foto"): alles wat het consolevenster van dit script toont (ook foutmeldingen die niet via Log() lopen) gaat naar een transcript op de laptop en wordt tijdens de run naar de server gekopieerd (status\console\<serienummer>.txt).
try { New-Item -ItemType Directory -Path "C:\EspritICT\AuditLogs" -Force -ErrorAction SilentlyContinue | Out-Null; $Script:ConsoleLogPad = "C:\EspritICT\AuditLogs\$Serial.console.txt"; Start-Transcript -Path $Script:ConsoleLogPad -Append -Force | Out-Null } catch { $Script:ConsoleLogPad = $null }
function Copy-ConsoleLogNaarServer {
    param([string]$StatusDir, [string]$Serie, [switch]$Forceer)
    try {
        $ErrorActionPreference = 'Stop'   # alle fouten hier opvangen: een niet-fatale fout zou anders als rode tekst op het scherm komen
        if (-not $Script:ConsoleLogPad -or -not (Test-Path $Script:ConsoleLogPad)) { return }
        $nu = Get-Date
        if (-not $Forceer -and $Script:LaatsteConsoleKopie -and (($nu - $Script:LaatsteConsoleKopie).TotalSeconds -lt 30)) { return }
        $Script:LaatsteConsoleKopie = $nu
        $doelDir = Join-Path $StatusDir "console"
        if (-not (Test-Path $doelDir -PathType Container)) { New-Item -ItemType Directory -Path $doelDir -Force -ErrorAction Stop | Out-Null }
        $bron = [System.IO.File]::Open($Script:ConsoleLogPad, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        try { $doel = [System.IO.File]::Open((Join-Path $doelDir "$Serie.txt"), [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::Read); try { $bron.CopyTo($doel) } finally { $doel.Dispose() } } finally { $bron.Dispose() }
    } catch {}
}
# v4.11 (beveiliging): geheime bestanden (share-login, Wi-Fi-gegevens) mogen NIET meegaan naar de klant. Overschrijven met nullen, verwijderen, TERUGLEZEN dat ze weg zijn, share-koppelingen verbreken.
function Remove-GeheimeBestanden {
    param([string[]]$Paden = @('C:\EspritICT\server-login.txt', 'C:\EspritICT\wifi-credentials.txt', 'C:\EspritICT\server-mac.txt', 'C:\EspritICT\wifi-profile.xml', 'C:\EspritICT\oogst-wifi-profiel.xml'), [switch]$GeenNetUse, [switch]$Stil)
    $weg = New-Object System.Collections.ArrayList; $blijft = New-Object System.Collections.ArrayList
    foreach ($p in $Paden) {
        try {
            if (Test-Path -LiteralPath $p) {
                $len = (Get-Item -LiteralPath $p -Force).Length
                try { [IO.File]::SetAttributes($p, [IO.FileAttributes]::Normal); [IO.File]::WriteAllBytes($p, (New-Object byte[] ([int][Math]::Max(1, $len)))) } catch {}
                [IO.File]::Delete($p)
            }
        } catch {}
        if (Test-Path -LiteralPath $p) { [void]$blijft.Add($p) } else { [void]$weg.Add([IO.Path]::GetFileName($p)) }
    }
    if (-not $GeenNetUse) { try { & net.exe use * /delete /y 2>&1 | Out-Null } catch {} }
    if ($blijft.Count) { Log "[beveiliging] LET OP: geheim bestand NIET verwijderd (blijft op het toestel): $($blijft -join ', ')" -Color Red } elseif (-not $Stil) { Log "[beveiliging] geheime bestanden opgeruimd en teruggelezen (niet meer aanwezig): $($weg -join ', ') ; share-koppelingen verbroken" -Color Green }
    return ($blijft.Count -eq 0)
}
# v4.22-wifi-opruimen (security officer punt 4): resten van een eerdere run weghalen en bij ELKE afsluiting (ook exit/stop) de Wi-Fi-bestanden wissen.
$Script:WifiGeheimPaden = @('C:\EspritICT\wifi-credentials.txt', 'C:\EspritICT\wifi-profile.xml', 'C:\EspritICT\oogst-wifi-profiel.xml')
try { [void](Remove-GeheimeBestanden -Paden $Script:WifiGeheimPaden -GeenNetUse -Stil) } catch {}
try { Register-EngineEvent -SourceIdentifier PowerShell.Exiting -Action { foreach ($gp in @('C:\EspritICT\wifi-credentials.txt', 'C:\EspritICT\wifi-profile.xml', 'C:\EspritICT\oogst-wifi-profiel.xml')) { try { if (Test-Path -LiteralPath $gp) { [IO.File]::SetAttributes($gp, [IO.FileAttributes]::Normal); [IO.File]::WriteAllBytes($gp, (New-Object byte[] 256)); [IO.File]::Delete($gp) } } catch {} } } | Out-Null } catch {}
# v4.7 (14 okt 2026): Sysprep wist het System-, Application- en Setup-log (Eventlog id 104). Daarom VOOR elke Sysprep-poging een export bewaren (lokaal + server), anders is het bewijs van de run weg.
function Save-EvtxVoorSysprep {
    param([string]$Basis = 'C:\EspritICT\AuditLogs\evtx-voor-sysprep', [int]$MaxSets = 3)
    try {
        $ErrorActionPreference = 'Stop'
        if (-not (Test-Path -LiteralPath $Basis)) { New-Item -ItemType Directory -Path $Basis -Force | Out-Null }
        $bestaand = @(Get-ChildItem -LiteralPath $Basis -Directory -ErrorAction SilentlyContinue)
        if ($bestaand.Count -ge $MaxSets) { Log "[evtx-voor-sysprep] al $($bestaand.Count) sets bewaard (maximaal $MaxSets) - niet nogmaals" -Color Gray; return }
        $map = Join-Path $Basis (Get-Date -Format 'yyyyMMdd-HHmmss')
        New-Item -ItemType Directory -Path $map -Force | Out-Null
        $wevt = Join-Path $env:SystemRoot 'System32\wevtutil.exe'
        $gelukt = New-Object System.Collections.ArrayList; $mislukt = New-Object System.Collections.ArrayList
        foreach ($logNaam in 'System', 'Application', 'Setup', 'Microsoft-Windows-TaskScheduler/Operational', 'Microsoft-Windows-NetworkProfile/Operational', 'Microsoft-Windows-Dhcp-Client/Admin', 'Microsoft-Windows-Kernel-PnP/Configuration', 'Microsoft-Windows-Kernel-PnP/Device Management', 'Microsoft-Windows-NDIS/Operational', 'Microsoft-Windows-AppXDeploymentServer/Operational', 'Microsoft-Windows-AppXDeployment/Operational', 'Microsoft-Windows-WindowsUpdateClient/Operational', 'Microsoft-Windows-Windows Defender/Operational', 'Microsoft-Windows-Bits-Client/Operational', 'Microsoft-Windows-Store/Operational') {
            $bestand = Join-Path $map (($logNaam -replace '[\\/]', '%4') + '.evtx')
            try {
                & $wevt epl $logNaam $bestand '/ow:true' 2>&1 | Out-Null
                if ($LASTEXITCODE -eq 0 -and (Test-Path -LiteralPath $bestand) -and ((Get-Item -LiteralPath $bestand).Length -gt 0)) { [void]$gelukt.Add($logNaam) } else { [void]$mislukt.Add("$logNaam (exitcode $LASTEXITCODE)") }
            } catch { [void]$mislukt.Add("$logNaam ($($_.Exception.Message))") }
        }
        Log "[evtx-voor-sysprep] bewaard in ${map}: $($gelukt.Count) logboeken ($($gelukt -join ', '))$(if ($mislukt.Count) { '; NIET gelukt: ' + ($mislukt -join '; ') })" -Color $(if ($mislukt.Count) { 'Yellow' } else { 'Gray' })
        try {
            $sd = Get-StatusDirVroeg
            if ($sd -and (Test-Path -LiteralPath $sd)) {
                $doel = Join-Path $sd ("evtx-voor-sysprep\$Serial\" + (Split-Path $map -Leaf))
                New-Item -ItemType Directory -Path $doel -Force | Out-Null
                $n = 0; foreach ($f in @(Get-ChildItem -LiteralPath $map -File)) { [IO.File]::Copy($f.FullName, (Join-Path $doel $f.Name), $true); $n++ }
                Log "[evtx-voor-sysprep] $n bestanden ook naar de server gekopieerd ($doel)" -Color Gray
            } else { Log "[evtx-voor-sysprep] server niet bereikbaar - alleen de lokale kopie (wordt door de diag-ronde opgehaald)" -Color Gray }
        } catch { Log "[evtx-voor-sysprep] kopie naar de server mislukt: $($_.Exception.Message)" -Color Yellow }
    } catch { Log "[evtx-voor-sysprep] niet gelukt: $($_.Exception.Message)" -Color Yellow }
}
# v4.8 (14 okt 2026): logboeken TUSSENTIJDS naar de server (zodra die bereikbaar is), want na een storing is het netwerk soms uren weg en Sysprep wist daarna het System-log.
function Push-EvtxTussentijds {
    param([string]$StatusDir, [string]$Serie, [switch]$Forceer, [int]$MinSeconden = 600)
    try {
        $ErrorActionPreference = 'Stop'
        if (-not $StatusDir -or -not $Serie) { return }
        $nu = Get-Date
        if (-not $Forceer -and $Script:LaatsteEvtxPush -and (($nu - $Script:LaatsteEvtxPush).TotalSeconds -lt $MinSeconden)) { return }
        if (-not (Test-Path -LiteralPath $StatusDir -PathType Container)) { return }
        $Script:LaatsteEvtxPush = $nu
        $lokaal = Join-Path $(if ($Script:EvtxTussenBasis) { $Script:EvtxTussenBasis } else { 'C:\EspritICT\AuditLogs' }) 'evtx-tussentijds'
        if (-not (Test-Path -LiteralPath $lokaal)) { New-Item -ItemType Directory -Path $lokaal -Force | Out-Null }
        $wevt = Join-Path $env:SystemRoot 'System32\wevtutil.exe'
        $n = 0; $mis = 0
        foreach ($logNaam in 'System', 'Application', 'Setup', 'Microsoft-Windows-TaskScheduler/Operational', 'Microsoft-Windows-NetworkProfile/Operational', 'Microsoft-Windows-Dhcp-Client/Admin', 'Microsoft-Windows-Kernel-PnP/Configuration', 'Microsoft-Windows-Kernel-PnP/Device Management', 'Microsoft-Windows-NDIS/Operational', 'Microsoft-Windows-AppXDeploymentServer/Operational', 'Microsoft-Windows-AppXDeployment/Operational', 'Microsoft-Windows-WindowsUpdateClient/Operational', 'Microsoft-Windows-Windows Defender/Operational', 'Microsoft-Windows-Bits-Client/Operational', 'Microsoft-Windows-Store/Operational') {
            $bestand = Join-Path $lokaal (($logNaam -replace '[\\/]', '%4') + '.evtx')
            try {
                & $wevt epl $logNaam $bestand '/ow:true' 2>&1 | Out-Null
                if ($LASTEXITCODE -ne 0 -or -not (Test-Path -LiteralPath $bestand) -or ((Get-Item -LiteralPath $bestand).Length -le 0)) { $mis++; continue }
                $doelDir = Join-Path $StatusDir "evtx-tussentijds\$Serie"
                if (-not (Test-Path -LiteralPath $doelDir)) { New-Item -ItemType Directory -Path $doelDir -Force | Out-Null }
                [IO.File]::Copy($bestand, (Join-Path $doelDir (Split-Path $bestand -Leaf)), $true); $n++
            } catch { $mis++ }
        }
        try { [IO.File]::WriteAllText((Join-Path $StatusDir "evtx-tussentijds\$Serie\laatste-push.txt"), ("tijd={0:yyyy-MM-dd HH:mm:ss}`r`nbestanden={1}`r`nmislukt={2}`r`n" -f $nu, $n, $mis)) } catch {}
        if ($n -gt 0) { Log "[evtx-tussentijds] $n logboeken naar de server gekopieerd (status\evtx-tussentijds\$Serie)$(if ($mis) { ", $mis mislukt" })" -Color Gray }
        try { Copy-LogBestandenNaarServer -StatusDir $StatusDir -Serie $Serie } catch {}
    } catch {}
}

# v4.20 (17 okt 2026): Secure Boot METEN (alleen lezen) en naar de server. Wijzigt NIETS aan de BIOS. Basis voor een latere, bewezen 'zet Secure Boot weer aan' per merk.
function Write-SecureBootMeting {
    try {
        $ErrorActionPreference = 'Stop'
        $regels = New-Object System.Collections.ArrayList
        function Voeg([string]$t) { [void]$regels.Add($t) }
        function Props($o) { (($o.PSObject.Properties | Where-Object { $_.Name -notmatch '^(CIM|__|PS|Cim)' -and $null -ne $_.Value } | ForEach-Object { "$($_.Name)=$(@($_.Value) -join '/')" }) -join '; ') }
        $w = 'onbekend'; try { $w = "$(Confirm-SecureBootUEFI)" } catch { $w = "niet te lezen ($($_.Exception.Message.Trim()))" }
        Voeg "Windows (Confirm-SecureBootUEFI): $w"
        try { $st = (Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\SecureBoot\State' -ErrorAction Stop).UEFISecureBootEnabled; Voeg "Register UEFISecureBootEnabled: $st" } catch { Voeg "Register UEFISecureBootEnabled: niet aanwezig" }
        try { $fw = (Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control' -Name PEFirmwareType -ErrorAction Stop).PEFirmwareType; Voeg "Firmwaretype (1=BIOS, 2=UEFI): $fw" } catch { Voeg "Firmwaretype: niet te lezen" }
        # fabrikant-interfaces: ALLE drie proberen, ook als het merk anders lijkt (bewijs voor onbekende modellen); alleen LEZEN
        try { $hp = @(Get-CimInstance -Namespace 'root\HP\InstrumentedBIOS' -ClassName HP_BIOSEnumeration -ErrorAction Stop | Where-Object { "$($_.Name)" -match 'Secure ?Boot|Legacy|Boot Mode' }); if ($hp.Count) { foreach ($x in $hp) { Voeg "HP-BIOS: $(Props $x)" } } else { Voeg "HP-BIOS: interface aanwezig maar geen Secure Boot/Legacy-instelling gevonden" } } catch { Voeg "HP-BIOS-interface: niet aanwezig ($($_.Exception.Message.Trim()))" }
        try { $hpw = @(Get-CimInstance -Namespace 'root\HP\InstrumentedBIOS' -ClassName HP_BIOSPassword -ErrorAction Stop); foreach ($x in $hpw) { Voeg "HP-BIOS-wachtwoord: $(Props $x)" } } catch {}
        try { $lv = @(Get-CimInstance -Namespace 'root\wmi' -ClassName Lenovo_BiosSetting -ErrorAction Stop | Where-Object { "$($_.CurrentSetting)" -match 'Secure ?Boot' }); if ($lv.Count) { foreach ($x in $lv) { Voeg "Lenovo-BIOS: $($x.CurrentSetting)" } } else { Voeg "Lenovo-BIOS: interface aanwezig maar geen SecureBoot-instelling gevonden" } } catch { Voeg "Lenovo-BIOS-interface: niet aanwezig ($($_.Exception.Message.Trim()))" }
        try { $lvw = @(Get-CimInstance -Namespace 'root\wmi' -ClassName Lenovo_BiosPasswordSettings -ErrorAction Stop); foreach ($x in $lvw) { Voeg "Lenovo-BIOS-wachtwoordstatus: $(Props $x)" } } catch {}
        try { $dl = @(Get-CimInstance -Namespace 'root\dcim\sysman\biosattributes' -ClassName EnumerationAttribute -ErrorAction Stop | Where-Object { "$($_.AttributeName)" -match 'Secure ?Boot' }); if ($dl.Count) { foreach ($x in $dl) { Voeg "Dell-BIOS: $(Props $x)" } } else { Voeg "Dell-BIOS: interface aanwezig maar geen SecureBoot-instelling gevonden" } } catch { Voeg "Dell-BIOS-interface (Dell Command | Monitor): niet aanwezig ($($_.Exception.Message.Trim()))" }
        foreach ($c in "$env:ProgramFiles\Dell\Command Configure\X86_64\cctk.exe", "${env:ProgramFiles(x86)}\Dell\Command Configure\X86_64\cctk.exe") { if ($c -and (Test-Path -LiteralPath $c)) { Voeg "Dell CCTK aanwezig: $c" } }
        $kop = "tijd=$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')`r`nserienummer=$Serial`r`n"
        foreach ($r in $regels) { Log "[secureboot] $r" -Color Gray }
        $pad = Join-Path 'C:\EspritICT' 'securebootmeting.log'
        try { [IO.File]::WriteAllText($pad, $kop + (($regels | ForEach-Object { $_ }) -join "`r`n") + "`r`n") } catch {}
        try { if (Test-Path -LiteralPath $pad) { Copy-OemRapportNaarServer -Serie $Serial -Merk 'securebootmeting' -Bestanden @($pad) -Reden 'Secure Boot meten (alleen lezen)' } } catch {}
    } catch { try { Log "[secureboot] meting niet gelukt: $($_.Exception.Message)" -Color Yellow } catch {} }
}

# v4.19 (17 okt 2026): ALLE tekstlogs (CBS, DISM, SetupAPI, WindowsUpdate, Panther, Defender, installer-logs) naar de server; alleen veranderde bestanden, begrensd.
function Copy-LogBestandenNaarServer {
    param([string]$StatusDir, [string]$Serie, [int]$MaxPerBestandMB = 40, [int]$MaxTotaalMB = 200)
    try {
        $ErrorActionPreference = 'Stop'
        if (-not $StatusDir -or -not $Serie -or -not (Test-Path -LiteralPath $StatusDir -PathType Container)) { return }
        $doelDir = Join-Path $StatusDir "logs-alles\$Serie"
        if (-not $Script:LogKopieen) { $Script:LogKopieen = @{} }
        $sys = $env:SystemRoot
        $patronen = @("$sys\Logs\CBS\CBS.log", "$sys\Logs\DISM\dism.log", "$sys\INF\setupapi.dev.log", "$sys\INF\setupapi.setup.log", "$sys\INF\setupapi.offline.log", "$sys\SoftwareDistribution\ReportingEvents.log", "$sys\debug\mrt.log", "$sys\Panther\*.log", "$sys\Panther\UnattendGC\*.log", "$sys\System32\Sysprep\Panther\*.log", "$sys\Logs\MoSetup\*.log", "$sys\Logs\WindowsUpdate\*.etl", "$sys\Temp\*.log", "C:\EspritICT\*.log", "C:\EspritICT\AuditLogs\*.log", "C:\EspritICT\AuditLogs\*.txt", "C:\EspritICT\AuditLogs\*.json", "$env:ProgramData\Microsoft\Windows Defender\Support\MPLog-*.log")
        $totaal = 0L; $n = 0; $over = 0; $max = [long]$MaxTotaalMB * 1MB; $maxF = [long]$MaxPerBestandMB * 1MB
        foreach ($pat in $patronen) {
            foreach ($f in @(Get-ChildItem -Path $pat -File -Force -ErrorAction SilentlyContinue)) {
                try {
                    $sleutel = "$($f.Length)|$($f.LastWriteTimeUtc.Ticks)"
                    if ($Script:LogKopieen[$f.FullName] -eq $sleutel) { continue }
                    $lees = [Math]::Min($f.Length, $maxF)
                    if ($totaal + $lees -gt $max) { $over++; continue }
                    if (-not (Test-Path -LiteralPath $doelDir)) { New-Item -ItemType Directory -Path $doelDir -Force | Out-Null }
                    $naam = ($f.FullName.Substring(3) -replace '[\\/:\s]', '_')
                    $bron = [IO.File]::Open($f.FullName, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::ReadWrite)
                    try {
                        if ($f.Length -gt $maxF) { [void]$bron.Seek($f.Length - $maxF, [IO.SeekOrigin]::Begin) }
                        $doel = [IO.File]::Open((Join-Path $doelDir $naam), [IO.FileMode]::Create, [IO.FileAccess]::Write, [IO.FileShare]::Read)
                        try { $bron.CopyTo($doel) } finally { $doel.Dispose() }
                    } finally { $bron.Dispose() }
                    $Script:LogKopieen[$f.FullName] = $sleutel; $totaal += $lees; $n++
                } catch {}
            }
        }
        if ($n -gt 0) {
            try { [IO.File]::WriteAllText((Join-Path $doelDir 'laatste-push.txt'), ("tijd={0:yyyy-MM-dd HH:mm:ss}`r`nbestanden={1}`r`nmb={2:N1}`r`novergeslagen-door-limiet={3}`r`n" -f (Get-Date), $n, ($totaal / 1MB), $over)) } catch {}
            Log ("[logs-alles] {0} logbestand(en) ({1:N1} MB) naar de server gekopieerd (status\logs-alles\{2}){3}" -f $n, ($totaal / 1MB), $Serie, $(if ($over) { ", $over overgeslagen door de limiet" } else { "" })) -Color Gray
        }
    } catch {}
}
# v4.17 (17 okt 2026): het HPIA-rapport (de echte foutmelding) LIVE naar de server, want de map op de laptop wordt aan het eind opgeruimd.
function Copy-HpiaRapportNaarServer {
    param([string]$Serie, [string]$Reden = '')
    try {
        $bron = $Config.HpiaReport
        if (-not $Serie -or -not $bron -or -not (Test-Path -LiteralPath $bron)) { return }
        $sd = Get-StatusDirVroeg; if (-not $sd -or -not (Test-Path -LiteralPath $sd -PathType Container)) { return }
        $doel = Join-Path $sd ("hpia\{0}\{1:yyyyMMdd-HHmmss}" -f $Serie, (Get-Date))
        New-Item -ItemType Directory -Path $doel -Force | Out-Null
        $n = 0; $tot = [long]0
        foreach ($f in @(Get-ChildItem -LiteralPath $bron -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.log', '.json', '.xml', '.html', '.txt', '.csv' -and $_.Length -le 20MB })) {
            if ($tot -gt 60MB) { break }
            $rel = $f.FullName.Substring($bron.Length).TrimStart('\'); $d = Join-Path $doel $rel
            New-Item -ItemType Directory -Path (Split-Path $d) -Force | Out-Null
            [IO.File]::Copy($f.FullName, $d, $true); $n++; $tot += $f.Length
        }
        $meta = @("tijd=$((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))", "serienummer=$Serie", "reden=$Reden", "bestanden=$n", "bytes=$tot", "os=$((Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue).Version)", "bord=$((Get-CimInstance Win32_BaseBoard -ErrorAction SilentlyContinue).Product)", "sku=$((Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue).SystemSKUNumber)")
        [IO.File]::WriteAllLines((Join-Path $doel 'hpia-meta.txt'), [string[]]$meta)
        Log "[hpia-rapport] $n bestand(en) naar de server gekopieerd (status\hpia\$Serie)$(if ($Reden) { ' - ' + $Reden })" -Color Gray
    } catch { Log "[hpia-rapport] kopie naar de server mislukt (niet fataal): $($_.Exception.Message)" -Color Yellow }
}

# v4.18 (17 okt 2026): het rapport/log van een fabrikanttool (nu: Surface-msiexec) LIVE naar de server, voor elk merk dezelfde plek: status\oem\<serie>\<merk>\<datum-tijd>\.
function Copy-OemRapportNaarServer {
    param([string]$Serie, [string]$Merk, [string[]]$Bestanden, [string]$Reden = '')
    try {
        if (-not $Serie -or -not $Merk -or -not $Bestanden) { return }
        $sd = Get-StatusDirVroeg; if (-not $sd -or -not (Test-Path -LiteralPath $sd -PathType Container)) { return }
        $doel = Join-Path $sd ("oem\{0}\{1}\{2:yyyyMMdd-HHmmss}" -f $Serie, ($Merk -replace '[^A-Za-z0-9_-]', '_'), (Get-Date))
        $n = 0; $tot = [long]0
        foreach ($b in $Bestanden) {
            foreach ($f in @(Get-ChildItem -Path $b -File -ErrorAction SilentlyContinue)) {
                if ($f.Length -gt 20MB -or $tot -gt 60MB) { continue }
                if ($n -eq 0) { New-Item -ItemType Directory -Path $doel -Force | Out-Null }
                [IO.File]::Copy($f.FullName, (Join-Path $doel $f.Name), $true); $n++; $tot += $f.Length
            }
        }
        if ($n -gt 0) {
            [IO.File]::WriteAllLines((Join-Path $doel 'oem-meta.txt'), [string[]]@("tijd=$((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))", "serienummer=$Serie", "merk=$Merk", "reden=$Reden", "bestanden=$n", "bytes=$tot"))
            Log "[oem-rapport] $n bestand(en) naar de server gekopieerd (status\oem\$Serie\$Merk)$(if ($Reden) { ' - ' + $Reden })" -Color Gray
        } else { Log "[oem-rapport] geen bestanden om naar de server te kopieren ($Merk$(if ($Reden) { ', ' + $Reden }))" -Color Gray }
    } catch { Log "[oem-rapport] kopie naar de server mislukt (niet fataal): $($_.Exception.Message)" -Color Yellow }
}# v4.9 (14 okt 2026): na de maandupdate starten de automatische services (Event Log, DHCP, Taakplanner, ...) soms niet vanzelf. Expliciet opbrengen in vaste volgorde, per stap de EXACTE fout loggen, begrensd.
function Start-NetwerkDiensten {
    param([switch]$Kort, [int]$MaxSeconden = 90, [int]$WachtPerDienst = 15)
    try {
        $start = Get-Date
        $lijst = if ($Kort) { 'Dhcp', 'LanmanWorkstation', 'Schedule' } else { 'EventLog', 'RpcEptMapper', 'DcomLaunch', 'SystemEventsBroker', 'TimeBrokerSvc', 'Dhcp', 'NlaSvc', 'netprofm', 'LanmanWorkstation', 'Schedule' }
        $samen = New-Object System.Collections.ArrayList
        foreach ($n in $lijst) {
            if (((Get-Date) - $start).TotalSeconds -ge $MaxSeconden) { [void]$samen.Add("$n=OVERGESLAGEN(tijdbudget)"); continue }
            try { $s = Get-Service -Name $n -ErrorAction Stop } catch { [void]$samen.Add("$n=ONBEKEND"); continue }
            if ($s.Status -eq 'Running') { [void]$samen.Add("$n=Running"); continue }
            if ($s.StartType -eq 'Disabled') { [void]$samen.Add("$n=UITGESCHAKELD"); continue }
            try {
                Start-Service -Name $n -ErrorAction Stop
                $w = 0; while ($w -lt $WachtPerDienst -and (Get-Service -Name $n).Status -ne 'Running') { Start-Sleep 1; $w++ }
                $na = (Get-Service -Name $n).Status
                [void]$samen.Add("$n=$na(na ${w}s gestart)")
                if ($na -ne 'Running') { Log "[net-diensten] ${n}: gestart maar staat op $na" -Color Yellow }
            } catch {
                $m = "$($_.Exception.Message)"; $inner = if ($_.Exception.InnerException) { " / " + $_.Exception.InnerException.Message } else { '' }
                Log "[net-diensten] ${n}: start MISLUKT: $m$inner" -Color Yellow
                [void]$samen.Add("$n=MISLUKT")
            }
        }
        Log "[net-diensten] $($samen -join '; ')" -Color Gray
    } catch { try { Log "[net-diensten] niet gelukt: $($_.Exception.Message)" -Color Yellow } catch {} }
}
# v4.8 (14 okt 2026): als het netwerk niet opkomt, de toestand ervan in het log zetten (anders weten we pas na een diag-ronde wat er speelde). Maximaal 2x per start.
# v4.11: herstel voor een netwerkkaart die na een herstart 'Dormant'/zonder verkeer blijft (zie changelog). Begrensd: max 3 per start, min 90 s ertussen.
$Script:NetKaartHerstarts = 0
$Script:NetKaartLaatste = Get-Date
function Restart-NetwerkKaartAlsStil {
    param([string]$ServerHost)
    if ($Script:NetKaartHerstarts -ge 3) { return }
    if (((Get-Date) - $Script:NetKaartLaatste).TotalSeconds -lt 90) { return }
    $Script:NetKaartHerstarts++; $Script:NetKaartLaatste = Get-Date
    try {
        $kaarten = @(Get-NetAdapter -Physical -ErrorAction Stop | Where-Object { $_.PhysicalMediaType -eq '802.3' -and "$($_.Status)" -notin @('Disabled', 'Not Present') })
        if (-not $kaarten.Count) { Log "[net-herstel] geen bekabelde fysieke kaart gevonden om te herstarten." -Color Gray; return }
        foreach ($k in $kaarten) {
            Log "[net-herstel] poging $($Script:NetKaartHerstarts)/3: server ($ServerHost) onbereikbaar; kaart '$($k.Name)' ($($k.InterfaceDescription)) staat op '$($k.Status)' - herstarten..." -Color Yellow
            try { Restart-NetAdapter -Name $k.Name -Confirm:$false -ErrorAction Stop } catch { Log "[net-herstel] Restart-NetAdapter gaf: $_" -Color Gray; continue }
            $w = [System.Diagnostics.Stopwatch]::StartNew(); $na = $null
            while ($w.Elapsed.TotalSeconds -lt 40) { Start-Sleep 2; $na = Get-NetAdapter -Name $k.Name -ErrorAction SilentlyContinue; if ($na -and "$($na.Status)" -eq 'Up') { break } }
            $ip = @(Get-NetIPAddress -InterfaceAlias $k.Name -AddressFamily IPv4 -ErrorAction SilentlyContinue | ForEach-Object { "$($_.IPAddress) ($($_.PrefixOrigin))" }) -join ', '
            $bereik = $false; if ($ServerHost) { $bereik = [bool](Test-TcpPortQuick -HostName $ServerHost -Port 445) }
            Log "[net-herstel] na $([int]$w.Elapsed.TotalSeconds) s: kaart '$($k.Name)' status '$($na.Status)', ip: $ip, server poort 445 bereikbaar: $bereik" -Color $(if ($bereik) { 'Green' } else { 'Yellow' })
        }
    } catch { Log "[net-herstel] fout (genegeerd): $_" -Color Gray }
}
# v4.11 (voorkomen): stroombesparing/offload van de bekabelde kaart uit tijdens de run; oude waarden worden bewaard en voor Sysprep teruggezet. Alleen sleutels die de driver kent, alleen 802.3-kaarten.
$Script:NicSleutels = [ordered]@{ '*EEE' = '0'; 'EEELinkAdvertisement' = '0'; 'ReduceSpeedOnPowerDown' = '0'; 'ULPMode' = '0'; 'GigaLite' = '0'; 'AutoPowerSaveModeEnabled' = '0'; 'AdvancedEEE' = '0'; '*ARPOffload' = '0'; '*NSOffload' = '0'; '*WakeOnPattern' = '0'; '*WakeOnMagicPacket' = '0'; 'EnablePME' = '0'; '*SelectiveSuspend' = '0' }
function Set-NicStroombesparingUit {
    param([string]$VoorBestand = 'C:\EspritICT\nic-voor.json')
    $gewijzigd = 0
    try {
        $voor = @(); if (Test-Path -LiteralPath $VoorBestand) { try { $jj = Get-Content -LiteralPath $VoorBestand -Raw | ConvertFrom-Json; if ($jj) { $voor = @($jj | ForEach-Object { $_ }) } } catch { $voor = @() } }   # PS 5.1: ConvertFrom-Json geeft een array als EEN object terug; daarom uitrollen
        $nieuw = New-Object System.Collections.ArrayList
        foreach ($a in @(Get-NetAdapter -Physical -ErrorAction Stop | Where-Object { $_.PhysicalMediaType -eq '802.3' })) {
            foreach ($k in $Script:NicSleutels.Keys) {
                try {
                    $p = Get-NetAdapterAdvancedProperty -Name $a.Name -RegistryKeyword $k -ErrorAction Stop
                    if (-not $p) { continue }
                    $huidig = "$(@($p.RegistryValue)[0])"; $wens = $Script:NicSleutels[$k]
                    if ($huidig -ne $wens) {
                        if (-not (@($voor) | Where-Object { $_.Kaart -eq $a.Name -and $_.Sleutel -eq $k })) { [void]$nieuw.Add([pscustomobject]@{ Kaart = $a.Name; Sleutel = $k; Waarde = $huidig }) }
                        Set-NetAdapterAdvancedProperty -Name $a.Name -RegistryKeyword $k -RegistryValue @($wens) -NoRestart -ErrorAction Stop; $gewijzigd++
                    }
                } catch {}
            }
            try {
                $pm = Get-NetAdapterPowerManagement -Name $a.Name -ErrorAction Stop
                if ("$($pm.AllowComputerToTurnOffDevice)" -eq 'Enabled') {
                    if (-not (@($voor) | Where-Object { $_.Kaart -eq $a.Name -and $_.Sleutel -eq 'AllowComputerToTurnOffDevice' })) { [void]$nieuw.Add([pscustomobject]@{ Kaart = $a.Name; Sleutel = 'AllowComputerToTurnOffDevice'; Waarde = 'Enabled' }) }
                    Set-NetAdapterPowerManagement -Name $a.Name -AllowComputerToTurnOffDevice Disabled -NoRestart -ErrorAction Stop; $gewijzigd++
                }
            } catch {}
        }
        if ($nieuw.Count) { [IO.File]::WriteAllText($VoorBestand, (@($voor) + @($nieuw) | ConvertTo-Json -Compress)) }
        if ($gewijzigd) { try { Get-NetAdapter -Physical -ErrorAction Stop | Where-Object { $_.PhysicalMediaType -eq '802.3' } | Restart-NetAdapter -Confirm:$false -ErrorAction SilentlyContinue } catch {}; Log "[nic-preventie] $gewijzigd stroombesparings-/offload-instellingen van de bekabelde kaart uitgezet (oude waarden bewaard in nic-voor.json; worden voor Sysprep teruggezet)" -Color Gray }
        else { Log "[nic-preventie] niets te wijzigen (stroombesparing stond al uit of de driver kent de sleutels niet)" -Color Gray }
    } catch { Log "[nic-preventie] fout (genegeerd): $_" -Color Gray }
    return $gewijzigd
}
function Restore-NicStroombesparing {
    param([string]$VoorBestand = 'C:\EspritICT\nic-voor.json')
    try {
        if (-not (Test-Path -LiteralPath $VoorBestand)) { return 0 }
        $jj = Get-Content -LiteralPath $VoorBestand -Raw | ConvertFrom-Json; $voor = @($jj | ForEach-Object { $_ }); $terug = 0   # PS 5.1: array uitrollen (zie Set-NicStroombesparingUit)
        foreach ($r in $voor) {
            try {
                if ($r.Sleutel -eq 'AllowComputerToTurnOffDevice') { Set-NetAdapterPowerManagement -Name $r.Kaart -AllowComputerToTurnOffDevice $r.Waarde -NoRestart -ErrorAction Stop }
                else { Set-NetAdapterAdvancedProperty -Name $r.Kaart -RegistryKeyword $r.Sleutel -RegistryValue @("$($r.Waarde)") -NoRestart -ErrorAction Stop }
                $terug++
            } catch {}
        }
        if ($terug -eq @($voor).Count) { [IO.File]::Delete($VoorBestand) }
        Log "[nic-preventie] $terug van $(@($voor).Count) instellingen teruggezet naar de fabriekswaarde$(if ($terug -ne @($voor).Count) { ' - LET OP: niet alles teruggezet, nic-voor.json blijft staan' })" -Color $(if ($terug -eq @($voor).Count) { 'Gray' } else { 'Yellow' })
        return $terug
    } catch { Log "[nic-preventie] terugzetten mislukt (genegeerd): $_" -Color Yellow; return 0 }
}
# v4.11: MAC-adres van de server bewaren (zodra het netwerk werkt) en na een herstart als vaste ARP-ingang zetten als de server onbereikbaar blijft. Strikte controle op ip en mac (geen vrije tekst naar het systeem).
function Save-ServerMac {
    param([string]$ServerHost, [string]$Pad = 'C:\EspritICT\server-mac.txt')
    try {
        if ($ServerHost -notmatch '^\d{1,3}(\.\d{1,3}){3}$') { return $false }
        $n = @(Get-NetNeighbor -IPAddress $ServerHost -ErrorAction Stop | Where-Object { "$($_.State)" -in @('Reachable', 'Stale', 'Delay', 'Probe', 'Permanent') -and "$($_.LinkLayerAddress)" -match '^([0-9A-Fa-f]{2}-){5}[0-9A-Fa-f]{2}$' -and "$($_.LinkLayerAddress)" -ne '00-00-00-00-00-00' -and "$($_.LinkLayerAddress)" -ne 'FF-FF-FF-FF-FF-FF' }) | Select-Object -First 1
        if (-not $n) { return $false }
        [IO.File]::WriteAllText($Pad, "ip=$ServerHost`r`nmac=$($n.LinkLayerAddress.ToUpper())`r`n"); Log "[server-mac] MAC van de server bewaard voor herstel na een herstart: $($n.LinkLayerAddress.ToUpper())" -Color Gray
        return $true
    } catch { return $false }
}
function Set-ServerMacStatisch {
    param([string]$ServerHost, [string]$Pad = 'C:\EspritICT\server-mac.txt')
    try {
        if ($ServerHost -notmatch '^\d{1,3}(\.\d{1,3}){3}$' -or -not (Test-Path -LiteralPath $Pad)) { return $false }
        $kv = @{}; foreach ($r in @(Get-Content -LiteralPath $Pad -ErrorAction Stop)) { if ($r -match '^(ip|mac)=(.+)$') { $kv[$Matches[1]] = $Matches[2].Trim() } }
        if ($kv['ip'] -ne $ServerHost -or $kv['mac'] -notmatch '^([0-9A-F]{2}-){5}[0-9A-F]{2}$') { return $false }
        $bestaand = @(Get-NetNeighbor -IPAddress $ServerHost -ErrorAction SilentlyContinue | Where-Object { "$($_.State)" -eq 'Permanent' -and "$($_.LinkLayerAddress)" -eq $kv['mac'] })
        if ($bestaand.Count) { return $false }
        $prefix = ($ServerHost -replace '\.\d+$', '.')
        $ifx = @(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction Stop | Where-Object { $_.IPAddress.StartsWith($prefix) } | Select-Object -First 1)
        if (-not $ifx.Count) { return $false }
        try { Remove-NetNeighbor -IPAddress $ServerHost -InterfaceIndex $ifx[0].InterfaceIndex -Confirm:$false -ErrorAction SilentlyContinue } catch {}
        New-NetNeighbor -IPAddress $ServerHost -InterfaceIndex $ifx[0].InterfaceIndex -LinkLayerAddress $kv['mac'] -State Permanent -ErrorAction Stop | Out-Null
        Log "[server-mac] server onbereikbaar: vaste ARP-ingang gezet $ServerHost -> $($kv['mac']) (kaart index $($ifx[0].InterfaceIndex)); een ARP-antwoord van de server is nu niet nodig" -Color Yellow
        return $true
    } catch { Log "[server-mac] zetten mislukt (genegeerd): $_" -Color Gray; return $false }
}
function Write-NetwerkDiagnose {
    param([string]$ServerHost)
    try {
        $Script:NetDiagTeller = 1 + [int]$Script:NetDiagTeller
        if ($Script:NetDiagTeller -gt 2) { return }
        Log "[net-diag] ---- toestand van het netwerk (aanroep $($Script:NetDiagTeller)) ----" -Color Yellow
        $diensten = foreach ($d in 'LanmanWorkstation', 'Dhcp', 'Dnscache', 'NlaSvc', 'netprofm', 'Schedule', 'BFE', 'mpssvc', 'RpcSs', 'EventLog', 'TrustedInstaller') {
            try { $s = Get-Service -Name $d -ErrorAction Stop; "$d=$($s.Status)/$($s.StartType)" } catch { "$d=FOUT($($_.Exception.Message))" }
        }
        Log "[net-diag] services: $($diensten -join '; ')"
        try { foreach ($a in @(Get-NetAdapter -ErrorAction Stop)) { Log "[net-diag] kaart: $($a.Name) | $($a.InterfaceDescription) | $($a.Status) | $($a.LinkSpeed) | driver $($a.DriverVersionString)" } } catch { Log "[net-diag] kaarten niet te lezen: $($_.Exception.Message)" }
        try { foreach ($ip in @(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction Stop)) { Log "[net-diag] ip: $($ip.InterfaceAlias) $($ip.IPAddress)/$($ip.PrefixLength) ($($ip.PrefixOrigin), $($ip.AddressState))" } } catch { Log "[net-diag] adressen niet te lezen: $($_.Exception.Message)" }
        try {
            foreach ($a in @(Get-NetAdapter -Physical -ErrorAction Stop | Where-Object { $_.PhysicalMediaType -eq '802.3' })) {
                $pr = @(Get-NetAdapterAdvancedProperty -Name $a.Name -ErrorAction SilentlyContinue | ForEach-Object { "$($_.DisplayName)=$($_.DisplayValue)" }); Log "[net-diag] geavanceerd $($a.Name): $($pr -join '; ')"
                try { $pm = Get-NetAdapterPowerManagement -Name $a.Name -ErrorAction Stop; Log "[net-diag] energiebeheer $($a.Name): uitzetten-toegestaan=$($pm.AllowComputerToTurnOffDevice) wake-magic=$($pm.WakeOnMagicPacket) wake-pattern=$($pm.WakeOnPattern) arp-offload=$($pm.ArpOffload) ns-offload=$($pm.NSOffload) eee=$($pm.DeviceSleepOnDisconnect)" } catch { Log "[net-diag] energiebeheer $($a.Name) niet te lezen: $($_.Exception.Message)" }
                try { $sx = Get-NetAdapterStatistics -Name $a.Name -ErrorAction Stop; Log "[net-diag] statistieken $($a.Name): ontvangen unicast=$($sx.ReceivedUnicastPackets) broadcast=$($sx.ReceivedBroadcastPackets) verzonden unicast=$($sx.SentUnicastPackets) broadcast=$($sx.SentBroadcastPackets) fouten-in=$($sx.ReceivedPacketErrors) weggegooid-uit=$($sx.OutboundDiscardedPackets)" } catch {}
            }
        } catch {}
        try { foreach ($nb in @(Get-NetNeighbor -AddressFamily IPv4 -ErrorAction Stop | Where-Object { "$($_.State)" -ne 'Permanent' -and $_.IPAddress -notmatch '^(224|239|255)\.' })) { Log "[net-diag] buur: $($nb.InterfaceAlias) $($nb.IPAddress) $($nb.LinkLayerAddress) $($nb.State)" } } catch {}        if (-not $ServerHost) { try { $ServerHost = Get-ServerCacheHostQuick } catch {} }
        if ($ServerHost) { try { Log "[net-diag] poort 445 naar ${ServerHost}: $(Test-TcpPortQuick -HostName $ServerHost -Port 445)" } catch { Log "[net-diag] poort 445 test gaf een fout: $($_.Exception.Message)" } }
        if ($ServerHost) { foreach ($pt in 80, 8081, 135) { try { Log "[net-diag] poort $pt naar ${ServerHost}: $(Test-TcpPortQuick -HostName $ServerHost -Port $pt)" } catch { Log "[net-diag] poort $pt test gaf een fout: $($_.Exception.Message)" } } }
        try { $sc = Get-SmbClientConfiguration -ErrorAction Stop; Log ("[net-diag] SMB-client: RequireSecuritySignature={0} EnableSecuritySignature={1} EnableInsecureGuestLogons={2} BlockNTLM={3} AuditInsecureGuestLogon={4}" -f $sc.RequireSecuritySignature, $sc.EnableSecuritySignature, $sc.EnableInsecureGuestLogons, $(if ($sc.PSObject.Properties['BlockNTLM']) { $sc.BlockNTLM } else { 'n.v.t.' }), $sc.AuditInsecureGuestLogon) } catch { Log "[net-diag] SMB-clientinstellingen niet te lezen: $($_.Exception.Message)" }
        try { $p = @(Get-Process -Name TiWorker, TrustedInstaller -ErrorAction SilentlyContinue | ForEach-Object { $_.ProcessName }); Log "[net-diag] actieve update-processen: $(if ($p) { $p -join ', ' } else { 'geen' })" } catch {}
        try {
            $ev = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; Level = 1, 2, 3; StartTime = (Get-Date).AddMinutes(-20) } -MaxEvents 15 -ErrorAction Stop)
            foreach ($e in $ev) { $m = ("$($e.Message)" -split "`r?`n")[0]; if ($m.Length -gt 160) { $m = $m.Substring(0, 160) }; Log ("[net-diag] System {0:HH:mm:ss} {1} id{2}: {3}" -f $e.TimeCreated, $e.ProviderName, $e.Id, $m) }
            if (-not $ev) { Log "[net-diag] geen fouten/waarschuwingen in het System-log van de laatste 20 minuten" }
        } catch { Log "[net-diag] System-log niet te lezen: $($_.Exception.Message)" }
    } catch {}
}
$Script:MetricsFile  = "C:\EspritICT\AuditLogs\$Serial.metrics.jsonl"
$Script:CurrentPhase = $null
$Script:PhaseStart   = $null

function Write-RunMetric {
    param([string]$Event, [hashtable]$Extra = @{})
    try {
        $record = [ordered]@{
            ts     = (Get-Date -Format "yyyy-MM-ddTHH:mm:ss")
            event  = $Event
            serial = $Serial
            model  = if ($cs) { $cs.Model } else { $null }
            mfg    = if ($cs) { $cs.Manufacturer } else { $null }
            order  = $State.Ordernummer
            reboot = $State.RebootCount
        }
        foreach ($k in $Extra.Keys) { $record[$k] = $Extra[$k] }
        $json = $record | ConvertTo-Json -Compress
        try {
            Add-Content -Path $Script:MetricsFile -Value $json -ErrorAction Stop
        } catch {
            try { Start-Sleep -Milliseconds 250; Add-Content -Path $Script:MetricsFile -Value $json -ErrorAction Stop } catch {}
        }
        Update-UsbLogPath
        if ($Script:UsbLog) {
            $usbMetricsFile = Join-Path (Split-Path $Script:UsbLog -Parent) "$Serial.metrics.jsonl"
            if (-not $Script:UsbMetricsSynced) {
                # Zelfde inhaalslag-patroon als Log() - zie de uitleg daar.
                try {
                    Copy-Item -Path $Script:MetricsFile -Destination $usbMetricsFile -Force -ErrorAction Stop
                    $Script:UsbMetricsSynced = $true
                } catch {
                    try {
                        Start-Sleep -Milliseconds 250
                        Copy-Item -Path $Script:MetricsFile -Destination $usbMetricsFile -Force -ErrorAction Stop
                        $Script:UsbMetricsSynced = $true
                    } catch {}
                }
            } else {
                try {
                    Add-Content -Path $usbMetricsFile -Value $json -ErrorAction Stop
                } catch {
                    try { Start-Sleep -Milliseconds 250; Add-Content -Path $usbMetricsFile -Value $json -ErrorAction Stop } catch {}
                }
            }
        }
    } catch {}
}

function Log-TpmStatus {
    # v3.51 - n.a.v. MP25PF46 (Autopilot 0x800705b4 bij "Uw hardware
    # beveiligen", ook na herinstallatie). Puur diagnostisch: Get-Tpm is
    # read-only, deze functie wijzigt niets aan de TPM. Doel is alleen
    # bewijsmateriaal in het log/metrics als een toestel later een
    # Autopilot-hardware-attestatiefout geeft, i.p.v. achteraf te gokken.
    # v3.52 - bevestigd op MP25PF46 (eerste live run): ManufacturerVersion
    # komt van Get-Tpm terug als een met NUL-bytes opgevulde vaste-lengte-
    # string ("3.92.0.5\0\0\0...") - trimmen, anders staat de metrics.jsonl
    # vol met letterlijke NUL-teken-escapes.
    param([string]$Moment)
    try {
        $tpm = Get-Tpm -ErrorAction Stop
        $mfgVersion = if ($tpm.ManufacturerVersion) { $tpm.ManufacturerVersion.TrimEnd([char]0).Trim() } else { $tpm.ManufacturerVersion }
        Log "TPM ($Moment): Ready=$($tpm.TpmReady) Enabled=$($tpm.TpmEnabled) Owned=$($tpm.TpmOwned) RestartPending=$($tpm.RestartPending) ManufacturerVersion=$mfgVersion" -Color Gray
        Write-RunMetric -Event "tpm_status" -Extra @{
            moment                   = $Moment
            tpm_ready                = $tpm.TpmReady
            tpm_enabled              = $tpm.TpmEnabled
            tpm_owned                = $tpm.TpmOwned
            tpm_restart_pending      = $tpm.RestartPending
            tpm_manufacturer_version = $mfgVersion
        }
    } catch {
        Log "TPM-status ($Moment) niet op te vragen: $_" -Color Yellow
    }
}

# v3.176 (10 augustus 2026, op verzoek van Roderick: "check apparaatbeheer dat daar geen
# fouten tussen zitten, bv driverfouten bij USB of iets dergelijks"). Get-PnpDevice is een
# standaard, ingebouwde Windows-PowerShell-module (PnpDevice), GEEN vendor-tool - puur
# read-only, wijzigt niets.
# Lokaal ECHT getest (deze machine, 255 aanwezige apparaten): ZONDER -PresentOnly toont
# Get-PnpDevice ook allang niet meer aangesloten "phantom"-apparaten (Status=Unknown,
# Problem=CM_PROB_PHANTOM - bv. een oude USB-stick of telefoon die ooit is aangesloten
# geweest) - elk toestel dat ooit een USB-stick heeft gehad zou daardoor valse meldingen
# geven. MET -PresentOnly verdwijnen die volledig (bevestigd: alle 255 aanwezige apparaten
# hadden Status=OK, 0 fout). CM_PROB_DISABLED (een toestel dat bewust/handmatig is
# uitgezet) wordt ook uitgesloten - dat is geen fout, dat is een keuze van de gebruiker.
function Get-ThinInstallerStatussen {
    # v3.296: ThinInstaller schrijft per pakket zijn EIGEN uitkomst weg in update_history.txt (regel: id %-% titel %-% status %-% ... %-% versie). Statussen: InstallSuccess, AlreadyInstalled (zelfde of nieuwere versie staat er al), NotApplicable (hardware niet aanwezig). Alleen vertrouwen als het bestand bij DEZE ThinInstaller-run hoort (tijdstip dicht bij zijn logbestand).
    param([string[]]$Pad, [string]$LogPad)
    foreach ($p in @($Pad)) {
        try {
            if (-not $p -or -not (Test-Path $p)) { continue }
            if ($LogPad -and (Test-Path $LogPad) -and ([Math]::Abs(((Get-Item $p).LastWriteTime - (Get-Item $LogPad).LastWriteTime).TotalMinutes) -gt 15)) { continue }
            $h = @{}
            foreach ($l in @(Get-Content -Path $p -Encoding UTF8 -ErrorAction Stop)) {
                $d = @("$l" -split ' %-% ')
                if ($d.Count -ge 3 -and $d[0].Trim() -match '^[0-9a-z_]+$') { $h[$d[0].Trim()] = [pscustomobject]@{ Titel = $d[1].Trim(); Status = $d[2].Trim() } }
            }
            if ($h.Count -gt 0) { return $h }
        } catch {}
    }
    return $null
}
function Get-ThinInstallerSamenvatting {
    # v3.287: hoeveel pakketten vond ThinInstaller van toepassing en hoeveel installeerde hij echt? (Lenovo 21KH, 8 okt 2026: 26 van toepassing, 17 geinstalleerd; BIOS, audio, camera, graphics, LAN/WLAN/Bluetooth zonder melding weggevallen)
    param([string]$LogPad, [string[]]$HistoriePad)
    try {
        $r = @(Get-Content -Path $LogPad -Encoding UTF8 -ErrorAction Stop)
        $start = -1; for ($i = 0; $i -lt $r.Count; $i++) { if ($r[$i] -match 'Candidate list:') { $start = $i; break } }
        $kand = New-Object System.Collections.ArrayList
        if ($start -ge 0) { for ($j = $start + 1; $j -lt [Math]::Min($r.Count, $start + 80); $j++) { $s = $r[$j].Trim(); if ($s -match '^(.*)\[reboot type \d\]$') { [void]$kand.Add($Matches[1].Trim()) } elseif ($kand.Count -gt 0 -and $s -match '^(Info|Severe|Warning|bij |Message)') { break } } }
        $inst = @($r | Where-Object { $_ -match 'Update (.*) was installed successfully' } | ForEach-Object { if ($_ -match 'Update (.*) was installed successfully') { $Matches[1].Trim() } })
        $instLijst = New-Object System.Collections.ArrayList; foreach ($x in $inst) { [void]$instLijst.Add($x) }   # dubbele titels (2x Bluetooth/WLAN) tellen elk 1x: per kandidaat precies 1 geinstalleerde regel afstrepen
        $gemist = New-Object System.Collections.ArrayList; foreach ($k in $kand) { $pos = $instLijst.IndexOf($k); if ($pos -ge 0) { $instLijst.RemoveAt($pos) } else { [void]$gemist.Add($k) } }
        # v3.296: de EIGEN uitkomst van ThinInstaller per pakket (update_history.txt) is leidend. Zonder dit telde ik pakketten die al op de laptop stonden (zelfde of nieuwere versie) als "zonder melding weggevallen" en installeerde ze opnieuw (bewezen 9 okt, PW0FC5BB: 26 pakketten = 7 InstallSuccess + 15 AlreadyInstalled + 4 NotApplicable, Coreq: Return7Updates).
        $hist = $null; try { $hist = Get-ThinInstallerStatussen -Pad $HistoriePad -LogPad $LogPad } catch {}
        $nOk = 0; $nAl = 0; $nNa = 0; $histGebruikt = $false
        if ($hist -and $kand.Count -gt 0 -and $hist.Count -ge $kand.Count) {
            $histGebruikt = $true
            $nOk = @($hist.Values | Where-Object { $_.Status -eq 'InstallSuccess' }).Count; $nAl = @($hist.Values | Where-Object { $_.Status -eq 'AlreadyInstalled' }).Count; $nNa = @($hist.Values | Where-Object { $_.Status -eq 'NotApplicable' }).Count
            $gemist = New-Object System.Collections.ArrayList; foreach ($hv in @($hist.Values | Where-Object { $_.Status -notin 'InstallSuccess', 'AlreadyInstalled', 'NotApplicable' })) { [void]$gemist.Add($hv.Titel) }
        }
        return [pscustomobject]@{ Kandidaten = $kand.Count; Geinstalleerd = @($r | Where-Object { $_ -match 'was installed successfully' }).Count; Gemist = @($gemist); HistorieGebruikt = $histGebruikt; HistInstalled = $nOk; HistAlAanwezig = $nAl; HistNietVanToepassing = $nNa }
    } catch { return $null }
}
function Get-LenovoAanvulPakketten {
    # v3.289: de pakketten die ThinInstaller wel als 'van toepassing' zag maar niet installeerde, opzoeken in de (lokale) repository. Alleen pakketten van DIT model (id bevat een model-token zoals _83c9_ of _83ca_ uit de wel-geinstalleerde pakketten) en geen BIOS/firmware (Reboot type 5): die laten we aan ThinInstaller/de BIOS-controle.
    param([string]$RepoPad, [string[]]$Gemist, [string[]]$Tokens)
    $uit = New-Object System.Collections.ArrayList
    if (-not $Tokens -or $Tokens.Count -eq 0) { return @() }
    $tokRegex = '(' + (($Tokens | ForEach-Object { [regex]::Escape($_) }) -join '|') + ')'
    foreach ($dir in @(Get-ChildItem -Path $RepoPad -Directory -ErrorAction SilentlyContinue)) {
        if ($dir.Name -notmatch $tokRegex) { continue }
        $xmlPad = Get-ChildItem -Path $dir.FullName -Filter '*.xml' -File -ErrorAction SilentlyContinue | Select-Object -First 1
        if (-not $xmlPad) { continue }
        $x = ''; try { $x = [IO.File]::ReadAllText($xmlPad.FullName) } catch { continue }
        $titel = [regex]::Match($x, '<Desc id="EN">([^<]+)').Groups[1].Value.Trim()
        if (-not $titel -or ($Gemist -notcontains $titel)) { continue }
        $reboot = [regex]::Match($x, '<Reboot type="(\d)"').Groups[1].Value
        if ($reboot -eq '5') { continue }
        $extract = [regex]::Match($x, '<ExtractCommand>([^<]*)').Groups[1].Value.Trim()
        $install = [regex]::Match($x, '<Install [^>]*>\s*<Cmdline[^>]*>([^<]*)').Groups[1].Value.Trim()
        $rc = [regex]::Match($x, '<Install rc="([^"]*)"').Groups[1].Value
        if (-not $extract -or -not $install) { continue }
        [void]$uit.Add([pscustomobject]@{ Id = $dir.Name; Titel = $titel; Map = $dir.FullName; Extract = $extract; Install = $install; RcOk = @($rc -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -match '^-?\d+$' } | ForEach-Object { [int]$_ }) })
    }
    return @($uit)
}
function Invoke-LenovoPakketAanvulling {
    # v3.289: een enkel pakket zelf installeren zoals ThinInstaller het zou doen: eerst ExtractCommand (zelfuitpakker in de pakketmap), daarna de Install-opdracht uit de pakket-XML; teruggave = exitcodes. $Runner(Bestand, Argumenten, Werkmap, TimeoutSec) -> exitcode (-1 = timeout/fout); testbaar met een nep-runner.
    param([Parameter(Mandatory = $true)]$Pakket, [scriptblock]$Runner, [int]$TimeoutSec = 900)
    $splits = {
        param([string]$cmd, [string]$map)
        $c = $cmd.Replace('%PACKAGEPATH%', $map)
        if ($c -match '^\s*("([^"]+)"|(\S+))\s*(.*)$') { $f = if ($Matches[2]) { $Matches[2] } else { $Matches[3] }; return @($f, $Matches[4]) }
        return @($c, '')
    }
    $e = & $splits $Pakket.Extract $Pakket.Map
    $eFile = $e[0]; if (-not [IO.Path]::IsPathRooted($eFile)) { $eFile = Join-Path $Pakket.Map $eFile }
    $rcE = & $Runner $eFile $e[1] $Pakket.Map $TimeoutSec
    $i = & $splits $Pakket.Install $Pakket.Map
    $rcI = & $Runner $i[0] $i[1] $Pakket.Map $TimeoutSec
    return [pscustomobject]@{ ExtractRc = $rcE; InstallRc = $rcI; Gelukt = ($Pakket.RcOk -contains [int]$rcI) }
}
function Invoke-ProcesMetTimeout {
    param([string]$Bestand, [string]$Argumenten, [string]$Werkmap, [int]$TimeoutSec = 900)
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo; $psi.FileName = $Bestand; $psi.Arguments = $Argumenten; $psi.WorkingDirectory = $Werkmap; $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
        $pr = [System.Diagnostics.Process]::Start($psi)
        if (-not $pr.WaitForExit($TimeoutSec * 1000)) { try { $pr.Kill() } catch {}; return -1 }
        return [int]$pr.ExitCode
    } catch { return -1 }
}
function Get-FabrikantSoftwareBewijs {
    # v4.24: wat van de fabrikant (en bijbehorende leveranciers) staat er NU echt op de laptop? Alleen lezen. $LeesProgrammas/$LeesApps zijn te vervangen voor tests.
    param([string]$Patroon = 'HP|Hewlett|Lenovo|Dell|Intel|Realtek|Elevoc|Surface|Waves|Synaptics|ELAN', [scriptblock]$LeesProgrammas = $null, [scriptblock]$LeesApps = $null)
    $uit = New-Object System.Collections.ArrayList
    if (-not $LeesProgrammas) { $LeesProgrammas = { foreach ($pad in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*') { Get-ItemProperty -Path $pad -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName } | Select-Object DisplayName, DisplayVersion, Publisher } } }
    if (-not $LeesApps) { $LeesApps = { try { Get-AppxPackage -AllUsers -ErrorAction Stop | Select-Object Name, Version, Publisher } catch { Get-AppxPackage -ErrorAction Stop | Select-Object Name, Version, Publisher } } }
    try {
        $prog = @(& $LeesProgrammas | Where-Object { "$($_.Publisher) $($_.DisplayName)" -match $Patroon } | Sort-Object DisplayName -Unique)
        [void]$uit.Add("[bewijs] fabrikantsoftware (programma's): $($prog.Count)")
        foreach ($p in $prog) { [void]$uit.Add(("[bewijs]   PROGRAMMA {0} | v{1} | {2}" -f $p.DisplayName, $p.DisplayVersion, $p.Publisher)) }
    } catch { [void]$uit.Add("[bewijs] fabrikantsoftware (programma's) niet te lezen: $($_.Exception.Message)") }
    try {
        $apps = @(& $LeesApps | Where-Object { "$($_.Name) $($_.Publisher)" -match $Patroon -and "$($_.Name)" -notmatch '^Microsoft\.' } | Sort-Object Name -Unique)
        [void]$uit.Add("[bewijs] fabrikantsoftware (apps): $($apps.Count)")
        foreach ($a in $apps) { [void]$uit.Add(("[bewijs]   APP {0} | v{1}" -f $a.Name, $a.Version)) }
    } catch { [void]$uit.Add("[bewijs] fabrikantsoftware (apps) niet te lezen: $($_.Exception.Message)") }
    return @($uit)
}
function Write-DriverBewijs {
    # v3.290 (Roderick: 'keihard bewijs dat alles werkt'): leg aan het einde van de run VAST wat er echt op de laptop staat: BIOS, en per apparaatklasse (geluid, beeld, netwerk, bluetooth, camera, kaartlezer, biometrie) het stuurprogramma met leverancier, versie, datum en INF-naam, plus ALLE apparaten met een fout (met InstanceId). Alleen lezen. Gaat in het auditlog (dus ook naar de server) en naar <status>\bewijs\<serie>.log.
    param([string]$Moment = 'einde')
    $regels = New-Object System.Collections.ArrayList
    function Add-R([string]$s) { [void]$regels.Add($s) }
    foreach ($xr in @($Script:ExtraUpdatesRegels)) { Add-R $xr }   # v4.2: wat de extra-updates-fase deed (MSRT, Security platform)
    foreach ($xr in @($Script:OogstRegels)) { Add-R $xr }   # v4.5: wat het oogstvenster deed
    try {
        $bios = Get-CimInstance Win32_BIOS -ErrorAction Stop | Select-Object -First 1
        Add-R ("[bewijs] BIOS: versie=" + $bios.SMBIOSBIOSVersion + " datum=" + $(try { ([datetime]$bios.ReleaseDate).ToString('yyyy-MM-dd') } catch { '?' }) + " fabrikant=" + $bios.Manufacturer + " EC=" + $bios.EmbeddedControllerMajorVersion + "." + $bios.EmbeddedControllerMinorVersion)
    } catch { Add-R "[bewijs] BIOS: niet te lezen ($($_.Exception.Message))" }
    # v4.28 (21 okt 2026): SDHOST (BayHubTech SD-kaartlezer) en EXTENSION (o.a. Dolby APO-service) toegevoegd; zonder die klassen kon de eindcontrole de kaartlezer- en audiodriver van de Lenovo nooit terugvinden.
    $klassen = @('MEDIA', 'DISPLAY', 'NET', 'BLUETOOTH', 'CAMERA', 'IMAGE', 'SMARTCARDREADER', 'BIOMETRIC', 'SYSTEM', 'HIDCLASS', 'SOFTWAREDEVICE', 'SOFTWARECOMPONENT', 'FIRMWARE', 'SDHOST', 'EXTENSION')
    try {
        $drv = @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction Stop | Where-Object { ($_.DeviceName -or $_.HardWareID) -and $klassen -contains "$($_.DeviceClass)".ToUpper() })   # v4.28: ook apparaten zonder DeviceName (bv. softwarecomponenten) tellen mee
        $n = 0
        foreach ($d in ($drv | Sort-Object DeviceClass, DeviceName)) {
            $dat = ''; try { $dat = ([datetime]$d.DriverDate).ToString('yyyy-MM-dd') } catch {}
            Add-R ("[bewijs] {0,-9} | {1} | {2} | v{3} | {4} | {5}" -f $d.DeviceClass, $d.DeviceName, $d.DriverProviderName, $d.DriverVersion, $dat, $d.InfName)
            try { Add-R ("[bewijs-hwid] {0} | {1} | {2} | v{3} | {4} | {5}" -f $d.DeviceClass, $d.HardWareID, $d.DeviceID, $d.DriverVersion, $dat, $d.InfName) } catch {}   # v4.27: hardware-ID erbij, zodat de eindcontrole de detectieregels van de ThinInstaller- en HPIA-pakketten kan controleren
            $n++
        }
        Add-R "[bewijs] $n stuurprogramma's in de klassen: $($klassen -join ', ')"
    } catch { Add-R "[bewijs] stuurprogramma's niet te lezen: $($_.Exception.Message)" }
    # v4.30 (22 okt 2026): aanvulling via Get-PnpDeviceProperty voor aanwezige apparaten die Win32_PnPSignedDriver niet gaf (geen DeviceName, of een klasse die we niet kennen); ALLE apparaten in EEN gebundelde aanroep (2,4 s voor 211 apparaten; de v4.29-lus met 4 aanroepen per apparaat duurde 66 s en haalde er door de tijdsgrens maar 14). Zelfde regelvorm als [bewijs-hwid] zodat de eindcontrole (301) niets hoeft te veranderen. Alleen lezen.
    try {
        $pnpGezien = @{}
        foreach ($pd0 in @($drv)) { if ($pd0.DeviceID) { $pnpGezien["$($pd0.DeviceID)".ToUpper()] = $true } }
        $pnpKand = @(Get-PnpDevice -PresentOnly -ErrorAction Stop | Where-Object { $_.Status -eq 'OK' -and -not $pnpGezien.ContainsKey("$($_.InstanceId)".ToUpper()) })
        $pnpN = 0
        if ($pnpKand.Count -gt 0) {
            $pnpProps = @(Get-PnpDeviceProperty -InstanceId @($pnpKand | ForEach-Object { $_.InstanceId }) -KeyName 'DEVPKEY_Device_DriverVersion', 'DEVPKEY_Device_HardwareIds', 'DEVPKEY_Device_DriverDate', 'DEVPKEY_Device_DriverInfPath' -ErrorAction SilentlyContinue)
            $pnpPer = @{}
            foreach ($pp in $pnpProps) { $pk = "$($pp.InstanceId)"; if (-not $pnpPer.ContainsKey($pk)) { $pnpPer[$pk] = @{} }; $pnpPer[$pk]["$($pp.KeyName)"] = $pp.Data }
            foreach ($pd in $pnpKand) {
                $pm = $pnpPer["$($pd.InstanceId)"]; if (-not $pm) { continue }
                $pv = $pm['DEVPKEY_Device_DriverVersion']; if ($pv -is [array]) { $pv = $pv[0] }; if (-not $pv) { continue }
                $ph = $pm['DEVPKEY_Device_HardwareIds']; if ($ph -is [array]) { $ph = $ph[0] }
                $pdat = ''; try { $pdat = ([datetime]$pm['DEVPKEY_Device_DriverDate']).ToString('yyyy-MM-dd') } catch {}
                $pinf = "$($pm['DEVPKEY_Device_DriverInfPath'])"
                Add-R ("[bewijs-hwid] {0} | {1} | {2} | v{3} | {4} | {5}" -f $pd.Class, $ph, $pd.InstanceId, $pv, $pdat, $pinf)
                $pnpN++
            }
        }
        Add-R "[bewijs] PnP-aanvulling (Get-PnpDeviceProperty, 1 aanroep): $pnpN extra apparaten met driverversie"
    } catch { Add-R "[bewijs] PnP-aanvulling niet gelukt: $($_.Exception.Message)" }
    try {
        $fout = @(Get-PnpDevice -PresentOnly -ErrorAction Stop | Where-Object { $_.Status -ne 'OK' -and $_.Problem -ne 'CM_PROB_DISABLED' })
        Add-R "[bewijs] apparaten met een fout: $($fout.Count)"
        foreach ($f in $fout) { Add-R ("[bewijs]   FOUT {0} ({1}) {2} [{3}]" -f $f.FriendlyName, $f.Class, $f.Problem, $f.InstanceId) }
    } catch { Add-R "[bewijs] foutcontrole niet gelukt: $($_.Exception.Message)" }
    try { foreach ($sw in @(Get-FabrikantSoftwareBewijs)) { Add-R $sw } } catch { Add-R "[bewijs] fabrikantsoftware niet te lezen: $($_.Exception.Message)" }   # v4.24
    # v3.297 (Roderick 10 okt: 'waarom runt hij niet volledig?'): wat staat er NU echt aan Windows-updates, Defender, Edge en .NET op de laptop? Sysprep wist de eventlogs, dus nu vastleggen (onafhankelijk bewijs, niet alleen onze eigen meldingen).
    try { $osr = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop; Add-R ("[bewijs] Windows: " + $osr.ProductName + " " + $osr.DisplayVersion + " build " + $osr.CurrentBuild + "." + $osr.UBR) } catch { Add-R "[bewijs] Windows-versie niet te lezen" }
    try {
        $hf = @(Get-HotFix -ErrorAction Stop | Sort-Object InstalledOn -Descending)
        Add-R ("[bewijs] geinstalleerde KB's (Get-HotFix): " + $hf.Count)
        foreach ($h in ($hf | Select-Object -First 25)) { Add-R ("[bewijs]   " + $h.HotFixID + " | " + $h.Description + " | " + $(try { ([datetime]$h.InstalledOn).ToString('yyyy-MM-dd') } catch { '?' })) }
    } catch { Add-R "[bewijs] KB-lijst niet te lezen: $($_.Exception.Message)" }
    try {
        $wj = Start-Job -ScriptBlock { $se = (New-Object -ComObject Microsoft.Update.Session).CreateUpdateSearcher(); $n = $se.GetTotalHistoryCount(); "TOTAAL|$n"; if ($n -gt 0) { foreach ($x in @($se.QueryHistory(0, [Math]::Min($n, 60)))) { "H|" + $x.Date.ToString('yyyy-MM-dd HH:mm') + "|" + $x.ResultCode + "|" + $x.Title } } }
        if (Wait-Job $wj -Timeout 60) { foreach ($r in @(Receive-Job $wj)) { $p = "$r" -split '\|', 4; if ($p[0] -eq 'TOTAAL') { Add-R ("[bewijs] Windows Update-geschiedenis: " + $p[1] + " regels (resultaat 2=geslaagd, 3=geslaagd met fouten, 4=mislukt, 5=afgebroken); laatste 60:") } elseif ($p[0] -eq 'H') { Add-R ("[bewijs]   " + $p[1] + " | resultaat " + $p[2] + " | " + $p[3]) } } } else { Add-R "[bewijs] Windows Update-geschiedenis: NIET gelezen (timeout 60 s)" }
        Remove-Job $wj -Force -ErrorAction SilentlyContinue
    } catch { Add-R "[bewijs] Windows Update-geschiedenis niet te lezen: $($_.Exception.Message)" }
    try {
        $mp = Get-MpComputerStatus -ErrorAction Stop
        $dagen = [int]((Get-Date) - $mp.AntivirusSignatureLastUpdated).TotalDays; $Script:DefenderDagenOud = $dagen
        Add-R ("[bewijs] Defender: handtekeningen " + $mp.AntivirusSignatureVersion + " van " + $mp.AntivirusSignatureLastUpdated.ToString('yyyy-MM-dd HH:mm') + ", engine " + $mp.AMEngineVersion + ", antimalware-client " + $mp.AMProductVersion)
        Add-R ("[bewijs] Defender-handtekeningen " + $(if ($dagen -gt 7) { "OUDER dan 7 dagen ($dagen dagen)" } else { "maximaal 7 dagen oud ($dagen dagen)" }))
    } catch { Add-R "[bewijs] Defender-status niet te lezen: $($_.Exception.Message)" }
    try { $edge = (Get-Item "${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe" -ErrorAction Stop).VersionInfo.ProductVersion; Add-R "[bewijs] Edge: $edge" } catch { Add-R "[bewijs] Edge-versie niet te lezen" }
    try { $net = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full' -ErrorAction Stop).Release; Add-R "[bewijs] .NET Framework 4.x release-nummer: $net (533320 en hoger = 4.8.1)" } catch { Add-R "[bewijs] .NET-versie niet te lezen" }
    # v3.292: de hardware-ID's van ALLE aanwezige apparaten vastleggen (VEN&DEV, VID&PID, ACPI-id) en als verzoek voor de SERVER neerleggen (<status>\wudrivers\<modelsleutel>.txt, bestaat het al dan niet opnieuw). De server (scripts\171) zoekt daarmee in de Microsoft Update Catalog naar ondertekende drivers en zet ze in modeldrivers\<model>\wu; de volgende installatie van dit model krijgt ze via WinPE (DISM) mee. De laptop zelf blijft offline.
    try {
        $hw = New-Object System.Collections.Generic.SortedSet[string]
        foreach ($pd in @(Get-PnpDevice -PresentOnly -ErrorAction Stop)) {
            $iid = "$($pd.InstanceId)"
            if ($iid -match '^PCI\\(VEN_[0-9A-F]{4}&DEV_[0-9A-F]{4})') { [void]$hw.Add($Matches[1]) }
            elseif ($iid -match '^HDAUDIO\\FUNC_01&(VEN_[0-9A-F]{4}&DEV_[0-9A-F]{4})') { [void]$hw.Add($Matches[1]) }
            elseif ($iid -match '^USB\\(VID_[0-9A-F]{4}&PID_[0-9A-F]{4})') { [void]$hw.Add($Matches[1]) }
            elseif ($iid -match '^(ACPI\\(?!PNP)[A-Z]{3,4}[0-9A-Z]{4})(\\|$)') { [void]$hw.Add($Matches[1]) }   # v3.293: ELKE ACPI-leverancier (VPC2004 van Lenovo ontbrak in v3.292 doordat alleen INTC/ELAN/MSFT/LEN/INT3 werden meegenomen)
        }
        # v3.295: ook de hardware-ID's van SOFTWARE-onderdelen (SWC\, SWD\, INTELAUDIO\, ROOT\, HDAUDIO\ ...): Windows Update biedt daarvoor 'Extension'-drivers aan (Intel, Elevoc, Lenovo, AudioProcessingObject) die alleen aan zulke ID's hangen. De volledige HardwareIds-lijst per apparaat (eerste 2), zonder het instantie-deel.
        $swTel = 0
        try {
            foreach ($pd in @(Get-PnpDevice -PresentOnly -ErrorAction Stop | Where-Object { "$($_.InstanceId)" -match '^(SWC|SWD|INTELAUDIO|ROOT|HDAUDIO|BTHENUM|SoundWire|SDCA|USB\\ROOT_HUB|DISPLAY)' -and "$($_.InstanceId)" -notmatch '^(SWD\\(MMDEVAPI|PRINTENUM|WPDBUSENUM|IP_TUN|DAFUPNPProvider|WSDPRINTPROXY|RADIO|COMPUTER|ENUM|MSIPC|SCDEVICE)|ROOT\\(VDRVROOT|SYSTEM|ACPI_HAL|UMBUS|COMPOSITEBUS|BASICDISPLAY|BASICRENDER|GENERIC)|DISPLAY\\Default)' })) {
                $ids = $null; try { $ids = @((Get-PnpDeviceProperty -InstanceId $pd.InstanceId -KeyName 'DEVPKEY_Device_HardwareIds' -ErrorAction Stop).Data) } catch {}
                foreach ($hid in @($ids | Select-Object -First 2)) { if ("$hid" -and "$hid".Length -lt 120) { if ($hw.Add("$hid")) { $swTel++ } } }
                if ($swTel -ge 80) { break }
            }
        } catch {}
        Add-R "[bewijs] software-onderdeel-ID's toegevoegd: $swTel"
        Add-R ("[bewijs] hardware-ID's aanwezig: " + $hw.Count)
        Add-R ("[bewijs] hwids: " + ($hw -join ';'))
        $sdW = Get-StatusDirVroeg
        if ($sdW -and (Test-Path $sdW) -and $hw.Count -gt 0) {
            $csW = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
            $sleutel = ("$($csW.Model)" -replace '\s', '' -replace '[^A-Za-z0-9_-]', '')
            if ($sleutel) {
                $wm = Join-Path $sdW 'wudrivers'; if (-not (Test-Path $wm)) { New-Item -ItemType Directory -Path $wm -Force | Out-Null }
                $rq = Join-Path $wm "$sleutel.txt"
                $uitkomstRq = Update-WuVerzoek -Pad $rq -Hwids @($hw) -Serie "$Serial" -Fabrikant ("$($csW.Manufacturer)".Trim()) -Model ("$($csW.Model)".Trim()) -Sleutel $sleutel
                if ($uitkomstRq -eq 'nieuw') { Add-R "[bewijs] verzoek voor de server neergelegd: wudrivers\$sleutel.txt" }
                elseif ($uitkomstRq -like 'bijgewerkt:*') { Add-R "[bewijs] verzoek voor de server BIJGEWERKT ($($uitkomstRq.Split(':')[1]) nieuwe hardware-ID's erbij): wudrivers\$sleutel.txt" }
                elseif ($uitkomstRq -eq 'ongewijzigd') { Add-R "[bewijs] verzoek voor dit model bestond al en bevat alle $($hw.Count) ID's: wudrivers\$sleutel.txt" }
                else { Add-R "[bewijs] verzoek voor de server NIET weggeschreven: wudrivers\$sleutel.txt" }
            }
        }
    } catch { Add-R "[bewijs] hardware-ID's vastleggen mislukt: $($_.Exception.Message)" }    # v3.291: wat biedt Microsoft Update (ONLINE) nog aan? Onafhankelijk bewijs naast WSUS Offline en ThinInstaller: alleen LEZEN (zoeken, niets downloaden/installeren), in een aparte taak met harde timeout. Geen internet (strikte servercache-modus) = dat staat er letterlijk.
    try {
        if (Test-InternetConnectivity) {
            $wuR = Get-WuOnlineAanbod -TimeoutSec 240
            if ($wuR.Status -eq 'ok') {
                Add-R "[bewijs] Windows Update ONLINE biedt nog aan: $(@($wuR.Regels).Count) update(s) (alleen gezocht, niets geinstalleerd)"
                foreach ($u in @($wuR.Regels)) { Add-R ("[bewijs]   WU: " + $u) }
                try { $sdG = Get-StatusDirVroeg; $okG = Write-WuGaten -StatusDir $sdG -Sleutel (Get-ModelSleutel) -Serie "$Serial" -Model ("$((Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue).Model)") -Bron 'bewijsrapport' -Regels @($wuR.Regels); Add-R "[bewijs] wu-gaten voor dit model $(if ($okG) { 'weggeschreven' } else { 'NIET weggeschreven' })" } catch {}
            } elseif ($wuR.Status -eq 'timeout') { Add-R "[bewijs] Windows Update ONLINE: zoeken duurde > 240 s, afgebroken" }
            else { Add-R "[bewijs] Windows Update ONLINE: zoeken mislukt ($(@($wuR.Regels) -join ' '))" }
        } else { Add-R "[bewijs] Windows Update ONLINE: niet gecontroleerd (geen internet - strikte servercache-modus)" }
    } catch { Add-R "[bewijs] Windows Update ONLINE: controle mislukt ($($_.Exception.Message))" }    foreach ($r in $regels) { Log ("  " + $r) -Color Gray }
    try {
        $sd = Get-StatusDirVroeg
        if ($sd -and (Test-Path $sd)) {
            $bm = Join-Path $sd 'bewijs'; if (-not (Test-Path $bm)) { New-Item -ItemType Directory -Path $bm -Force | Out-Null }
            $naam = ("$Serial" -replace '[^A-Za-z0-9_-]', '')
            Set-Content -Path (Join-Path $bm "$naam.log") -Value (@("# bewijs $Moment - $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') - tool $($Config.ToolVersion)") + @($regels)) -Encoding UTF8
        }
    } catch {}
}
function Test-DeviceManagerProblems {
    try {
        $problemen = Get-PnpDevice -PresentOnly -ErrorAction Stop | Where-Object {
            $_.Status -ne 'OK' -and $_.Problem -ne 'CM_PROB_DISABLED'
        }
        return @($problemen)
    } catch {
        Log "Apparaatbeheer-controle mislukt (niet fataal): $_" -Color Yellow
        return @()
    }
}

function Mark-Phase {
    # Sluit de vorige fase automatisch af (duur = nu - start) en opent
    # de nieuwe - zo hoeft niet op elk van de vele eindpunten van een
    # fase (inclusief foutpaden) een aparte "einde"-aanroep gezet te
    # worden, wat bij dit aantal vertakkingen foutgevoelig zou zijn.
    param([string]$Naam)
    if ($Script:CurrentPhase) {
        $duur = [int]((Get-Date) - $Script:PhaseStart).TotalSeconds
        Write-RunMetric -Event "phase_end" -Extra @{phase = $Script:CurrentPhase; duration_sec = $duur}
    }
    $Script:CurrentPhase = $Naam
    $Script:PhaseStart   = Get-Date
    Write-RunMetric -Event "phase_start" -Extra @{phase = $Naam}
}

function Close-CurrentPhase {
    if ($Script:CurrentPhase) {
        $duur = [int]((Get-Date) - $Script:PhaseStart).TotalSeconds
        Write-RunMetric -Event "phase_end" -Extra @{phase = $Script:CurrentPhase; duration_sec = $duur}
        $Script:CurrentPhase = $null
        $Script:PhaseStart   = $null
    }
}

# ----------------------------------------------------------------
# 7b. VEILIG WACHTEN OP TOETSAANSLAG
#     Draait dit script onzichtbaar (bv. via CmdLine tijdens de
#     specialize-fase, als SYSTEM, zonder interactieve desktop - Session
#     0), dan kan NIEMAND ooit een toets indrukken. Een gewone blokkerende
#     ReadKey() zou dan voor altijd vastlopen, terwijl het van buitenaf
#     lijkt alsof het apparaat "vastzit". Deze functie wacht daarom alleen
#     echt op een toets als er een echte interactieve sessie is (Session
#     hoger dan 0); anders gaat hij direct door.
# ----------------------------------------------------------------
function Test-InteractiveSession {
    # v3.56: geÃ«xtraheerd uit Wait-ForKeyIfInteractive/Wait-ForEnterIfInteractive
    # (dezelfde SessionId-check stond daar al twee keer identiek) zodat de
    # nieuwe modus-keuze (sectie 2b) 'm ook kan hergebruiken i.p.v. een
    # derde losse kopie te onderhouden.
    try {
        $sessionId = (Get-Process -Id $PID -ErrorAction Stop).SessionId
    } catch {
        $sessionId = -1
    }
    return ($sessionId -gt 0)
}

function Wait-ForKeyIfInteractive {
    if (-not (Test-InteractiveSession)) {
        Log "Niet-interactieve sessie gedetecteerd - niemand kan hier een toets indrukken, direct doorgaan" -Color Gray
        return
    }
    [void][System.Console]::ReadKey($true)
}

function Wait-ForEnterIfInteractive {
    # Zelfde bescherming als Wait-ForKeyIfInteractive, maar voor Read-Host
    # (bv. "Druk op Enter om te sluiten"-schermen). Zonder dit zouden ook
    # deze schermen voor altijd blijven hangen in een onzichtbare sessie -
    # inclusief de LOOP BEVEILIGING, die juist bedoeld is als laatste,
    # gegarandeerd veilige stopmaatregel.
    if (-not (Test-InteractiveSession)) {
        Log "Niet-interactieve sessie gedetecteerd - niemand kan hier op Enter drukken, direct doorgaan" -Color Gray
        return
    }
    Read-Host "  Druk op Enter om te sluiten"
}

# ----------------------------------------------------------------
# 7c. HEARTBEAT
#     Schrijft alleen een timestamp naar een los, klein bestand - los van
#     het logbestand, waarvan het schrijftempo sterk varieert per fase
#     (soms elke 30 sec, soms pas na een paar minuten bij een lange
#     download). Een los kijkvenster (bv. live.ps1) kan hierop een veel
#     preciezer "leeft hij nog"-signaal baseren dan op de laatste logregel.
# ----------------------------------------------------------------
# v3.251 (2 oktober 2026, op verzoek van Roderick: "ik zie alleen regio kiezen en weet niet wat de laptop doet; ik wil
# een dashboard waar elke laptop mee bezig is en in welke fase"): meldt de voortgang aan de SERVER. Alleen als de
# servercache al in gebruik is ($Config.ServerCachePath, gezet door Resolve-ServerCachePath/Connect-ServerCacheShare)
# EN de map `status\` op de server bestaat (de server maakt die aan; de laptop maakt niets aan). Schrijft
# `<server>\status\<serienummer>.txt` met sleutel=waarde-regels (door het dashboard leesbaar zonder JSON-parser).
# Elke fout wordt stil genegeerd: statusmelding mag NOOIT de run verstoren. Zonder servercache (stick-flow) doet dit niets.
function Get-ServerCacheHostQuick {
    foreach ($p in @("C:\EspritICT\server-cache.txt", $(if ($PSScriptRoot) { Join-Path $PSScriptRoot 'server-cache.txt' }))) {
        try {
            if ($p -and (Test-Path $p)) {
                foreach ($ln in (Get-Content $p -ErrorAction Stop)) {
                    $t = "$ln".Trim()
                    if ($t -and -not $t.StartsWith('#') -and $t -match '^\\\\([^\\]+)\\') { return $Matches[1] }
                }
            }
        } catch {}
    }
    return $null
}
function Test-TcpPortQuick {
    param([string]$HostName, [int]$Port = 445, [int]$TimeoutMs = 1500)
    try {
        $c = New-Object System.Net.Sockets.TcpClient
        $iar = $c.BeginConnect($HostName, $Port, $null, $null)
        $ok = $iar.AsyncWaitHandle.WaitOne($TimeoutMs, $false) -and $c.Connected
        try { $c.Close() } catch {}
        return [bool]$ok
    } catch { return $false }
}


# v3.252: vroege statusverbinding. De servercache wordt pas laat in de opstart gekoppeld (na de netwerkwachtlus); draait het script na een
# herstart maar kort en herstart het weer vóór dat punt, dan was er nooit een melding en zag het dashboard niets. Daarom legt Send-ServerStatus
# zelf, zo vroeg mogelijk, een lichte verbinding met de share uit server-cache.txt (+ server-login.txt) en schrijft via het UNC-pad.
# Alleen als server-cache.txt bestaat en de server (SMB 445) bereikbaar is; maximaal 1 poging per 30 s; stil bij elke fout. Geen server-cache.txt = niets.
$Script:StatusUncDir = $null
$Script:StatusUncPoging = $null
function Get-StatusDirVroeg {
    $root = $Config.ServerCachePath
    if ($root) { return (Join-Path $root "status") }
    if ($Script:StatusUncDir) { return $Script:StatusUncDir }
    $nu = Get-Date
    if ($Script:StatusUncPoging -and (($nu - $Script:StatusUncPoging).TotalSeconds -lt 30)) { return $null }
    $Script:StatusUncPoging = $nu
    $unc = $null
    foreach ($p in @("C:\EspritICT\server-cache.txt", $(if ($PSScriptRoot) { Join-Path $PSScriptRoot 'server-cache.txt' }))) {
        try {
            if ($p -and (Test-Path $p)) {
                foreach ($ln in (Get-Content $p -ErrorAction Stop)) {
                    $t = "$ln".Trim()
                    if ($t -and -not $t.StartsWith('#') -and $t -match '^\\\\[^\\]+\\[^\\]+') { $unc = $t.TrimEnd('\'); break }
                }
            }
        } catch {}
        if ($unc) { break }
    }
    if (-not $unc) { return $null }
    $srvHost = ($unc.TrimStart('\') -split '\\')[0]
    if (-not (Test-TcpPortQuick -HostName $srvHost -Port 445)) { return $null }
    $user = $null; $pw = $null
    foreach ($lp in @("C:\EspritICT\server-login.txt", $(if ($PSScriptRoot) { Join-Path $PSScriptRoot 'server-login.txt' }))) {
        try {
            if ($lp -and (Test-Path $lp)) {
                $regels = @(Get-Content $lp -ErrorAction Stop | ForEach-Object { "$_".Trim() } | Where-Object { $_ -and -not $_.StartsWith('#') })
                foreach ($r in $regels) {
                    if ($r -match '^(?i)gebruiker\s*=\s*(.+)$') { $user = $Matches[1].Trim() }
                    elseif ($r -match '^(?i)wachtwoord\s*=\s*(.*)$') { $pw = $Matches[1] }
                }
                if (-not $user -and $regels.Count -ge 2) { $user = $regels[0]; $pw = $regels[1] }
            }
        } catch {}
        if ($user) { break }
    }
    try { if ($user) { & net use $unc "/user:$user" $pw 2>&1 | Out-Null } else { & net use $unc 2>&1 | Out-Null } } catch {}
    $d = Join-Path $unc "status"
    if (Test-Path $d -PathType Container -ErrorAction SilentlyContinue) { $Script:StatusUncDir = $d; return $d }
    return $null
}

# v3.252, op verzoek van Roderick ("elke herstart opent hij weer PXE/WinPE, dat kost elke keer minimaal 5 minuten, zomaar 30 minuten"):
# op een laptop met netwerk-boot vóór Windows kost elke herstart een PXE-poging (IPv4 + IPv6-time-out, ~1,5-2 min). Dit zet de firmware zo dat de
# EERSTVOLGENDE start direct Windows Boot Manager kiest (UEFI BootNext via bcdedit; eenmalig, verdwijnt na die start). Het script roept dit bij elke
# start aan, dus ook de volgende herstart slaat PXE over. Alleen UEFI, alleen Audit Mode (niet update-only op een klantlaptop), en NIET als BitLocker
# actief beschermt (een gewijzigde opstartvolgorde kan dan een herstelsleutel vragen). Mislukt het: logregel en gewoon doorgaan (dan blijft het oude gedrag).
$Script:BootNextStatus = 'nog niet uitgevoerd'   # v3.252: resultaat zichtbaar op het dashboard (veld bootnext=)
# v3.253: firmwaretype als getal (1=BIOS, 2=UEFI), $null als onbekend. PEFirmwareType bestaat ALLEEN in WinPE (leeg in gewoon Windows/Audit Mode, ook op UEFI-machines);
# GetFirmwareType (kernel32) werkt overal. Aparte functie zodat de test het type kan nabootsen.
function Get-FirmwareTypeNr {
    $fw = $null
    try { if (-not ("W32Fw.Native" -as [type])) { Add-Type -Namespace W32Fw -Name Native -MemberDefinition '[DllImport("kernel32.dll")] public static extern bool GetFirmwareType(ref uint t);' -ErrorAction Stop }; $fwT = [uint32]0; if ([W32Fw.Native]::GetFirmwareType([ref]$fwT)) { $fw = [int]$fwT } } catch {}
    if (-not $fw) { try { $fw = (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control" -Name PEFirmwareType -ErrorAction Stop).PEFirmwareType } catch {} }
    return $fw
}
function Set-BootNextWindows {
    try {
        if ($State.UpdateOnlyMode) { return }
        if (-not (Get-ServerCacheHostQuick)) { return }   # alleen in de netwerk/PXE-flow (server-cache.txt aanwezig); de USB-stick-flow blijft ongewijzigd
        $fw = Get-FirmwareTypeNr
        if ($fw -ne 2) { $Script:BootNextStatus = 'overgeslagen: geen UEFI'; Log "BootNext: geen UEFI-firmware gedetecteerd - PXE-overslaan niet toegepast." -Color Gray; return }
        $blv = $null; try { $blv = Get-CimInstance -Namespace "root/cimv2/Security/MicrosoftVolumeEncryption" -ClassName Win32_EncryptableVolume -Filter "DriveLetter='C:'" -ErrorAction Stop } catch {}
        if ($blv -and $blv.ProtectionStatus -eq 1) { $Script:BootNextStatus = 'overgeslagen: BitLocker beschermt C:'; Log "BootNext: BitLocker beschermt C: - opstartvolgorde NIET gewijzigd (voorkomt een herstelsleutel-vraag)." -Color Gray; return }
        $out = & bcdedit.exe /set "{fwbootmgr}" bootsequence "{bootmgr}" 2>&1 | Out-String
        if ($LASTEXITCODE -eq 0) {
            # v3.258: terugkijken of de firmware de bootsequence echt onthoudt (op de Surface bleek PXE toch weer te starten; de eerste conclusie was fout omdat het type nooit herkend werd).
            $terug = ""
            try { $terug = "" + ((& bcdedit.exe /enum "{fwbootmgr}" 2>&1 | Out-String) -split "`r?`n" | Where-Object { $_ -match '(?i)bootsequence' } | Select-Object -First 1) } catch {}
            if ($terug.Trim()) { $Script:BootNextStatus = ('gezet, teruggelezen: ' + (($terug -replace '\s+', ' ').Trim() -replace '[=\r\n]', ' ')); Log "BootNext gezet en teruggelezen ($($terug.Trim())): de volgende start gaat direct naar Windows (PXE/netwerk overgeslagen, bespaart ~2 min per herstart)." -Color Gray }
            else { $Script:BootNextStatus = 'gezet maar bij terugkijken NIET bevestigd'; Log "BootNext: bcdedit meldde succes, maar bij terugkijken staat er geen bootsequence in {fwbootmgr} - de firmware onthoudt het mogelijk niet; PXE kan dus alsnog starten." -Color Yellow }
        }
        else { $Script:BootNextStatus = ('mislukt: ' + ($out.Trim() -replace '[\r\n=]',' ')); Log "BootNext zetten mislukt (niet erg, PXE-poging blijft bij de volgende herstart): $($out.Trim())" -Color Gray }
    } catch { $Script:BootNextStatus = 'fout: ' + ("$_" -replace '[\r\n=]',' '); Log "BootNext: fout (genegeerd): $_" -Color Gray }
}

# v3.252, op verzoek van Roderick ("waarom die 8? je doet toch exact hetzelfde"): herstarten bij een WU-fout is alleen zinvol als het iets kan veranderen.
# Dezelfde foutcode een TWEEDE keer (na de herstart die er al op volgde) = niet nog eens herstarten, maar doorgaan. De algemene limiet van 8 reboots blijft
# als laatste noodrem. Geeft $true als een herstart nog zin heeft; telt de herhaling bij en slaat de state op.
function Test-WuHerstartZinvol {
    param([string]$Fout)
    try {
        if ($State.RebootCount -ge $Script:MaxHerstarts) { return $false }
        $code = if ($Fout -match '0x[0-9A-Fa-f]{8}') { $Matches[0].ToUpper() } else { 'ONBEKEND' }
        if ($State.WuFoutLaatste -eq $code) { $State.WuFoutAantal = [int]$State.WuFoutAantal + 1 } else { $State.WuFoutLaatste = $code; $State.WuFoutAantal = 1 }
        Save-State $State
        if ($State.WuFoutAantal -ge 2) { Log "WU-fout $code kwam na de vorige herstart opnieuw terug - nog een herstart heeft geen zin, doorgaan." -Color Yellow; return $false }
        return $true
    } catch { return ($State.RebootCount -lt $Script:MaxHerstarts) }
}
# v3.252: een WU-fout die in werkelijkheid "geen internet" is (netwerkfout), terwijl een servercache is ingesteld, lost zich niet op door te
# herstarten: de updates horen uit de servercache te komen. Gebruikt door ALLE plekken die bij een WU-fout herstarten. Zonder servercache = $false.
# v3.254: de laptop heeft in de PXE-opstelling bewust geen internet (DHCP geeft de server als router/DNS, maar die routeert/resolvet niet): elke online WU-aanroep wacht dan ~1 min
# op een DNS-time-out en eindigt toch in 0x8024402C. Eenmalig per proces vaststellen (ping 2 s + http 3 s) en daarna die aanroepen meteen overslaan. Zonder server-cache.txt: altijd $false.
$Script:OnlineWuZinloosCache = $null
function Test-OnlineWuZinloos {
    try {
        if ($null -ne $Script:OnlineWuZinloosCache) { return $Script:OnlineWuZinloosCache }
        $r = [bool]((Get-ServerCacheHostQuick) -and -not (Test-InternetConnectivity))
        $Script:OnlineWuZinloosCache = $r
        if ($r) { Log "Geen internet en servercache actief - online Windows Update-aanroepen worden zonder wachttijd overgeslagen (updates komen uit de servercache)." -Color Yellow }
        return $r
    } catch { return $false }
}
function Test-WuNetwerkFoutOffline {
    param([string]$Fout)
    try { return [bool](($Fout -match '0x8024402C|0x80072EE7|0x80072EFD|0x80072EFE|0x8024401C') -and (Get-ServerCacheHostQuick) -and -not (Test-InternetConnectivity)) } catch { return $false }
}
$Script:LaatsteStatusTijd = $null
$Script:LaatsteLogRegel = ""
$Script:HuidigeFase = ""
# v3.280 (8 okt 2026, Roderick: 'snelheid per plek up en down, dan zie je gelijk of er een kink in de kabel zit'): de laptop meldt aan de server (1) de ONDERHANDELDE snelheid van zijn netwerkkaart naar de server (nic_mbps) en de pakketfouten
# (nic_fouten), en (2) een korte meting: 24 MB LEZEN uit <servercache>\speedtest\test-256MB.bin op een willekeurige plek (down_mbs) en 12 MB SCHRIJVEN naar <status>\snelheid\<serie>.bin (up_mbs, daarna gewist).
# Eerste meting 30 s na de start, daarna hooguit 1x per 10 min, elke richting max 5 s; elke fout = lege velden (nooit een fout of vertraging voor de run). De server-kant staat in dashboard-genereer.ps1 (Get-Verbinding).
# v3.281 (8 oktober 2026, Roderick: 'per plek wil ik ook live de up en down zien, 2 kleuren boven en onder'): LIVE verkeer van de netwerkkaart naar de server, per laptop, uit de tellers van Windows zelf (Get-NetAdapterStatistics): delta sinds de vorige
# statusmelding (>= 2 s en <= 120 s geleden; een teller die terugloopt of een fout geeft lege velden). live_down_mbs = ontvangen (ophalen van de server), live_up_mbs = verzonden (terugsturen). Nooit een fout of vertraging voor de run.
$Script:LiveNicNaam = $null; $Script:LiveVorig = $null
function Get-NetLive {
    $r = @{ live_down_mbs = ''; live_up_mbs = '' }
    try {
        $nu = Get-Date
        if (-not $Script:LiveNicNaam) {
            $srv = Get-ServerCacheHostQuick
            if (-not $srv) { return $r }
            $ifx = (Find-NetRoute -RemoteIPAddress $srv -ErrorAction Stop | Where-Object { $_.InterfaceIndex } | Select-Object -First 1).InterfaceIndex
            $Script:LiveNicNaam = (Get-NetAdapter -InterfaceIndex $ifx -ErrorAction Stop).Name
        }
        $stl = Get-NetAdapterStatistics -Name $Script:LiveNicNaam -ErrorAction Stop
        $cur = @{ t = $nu; rx = [double]$stl.ReceivedBytes; tx = [double]$stl.SentBytes }
        $vorig = $Script:LiveVorig; $Script:LiveVorig = $cur
        if ($vorig) {
            $dtl = ($nu - $vorig.t).TotalSeconds
            if ($dtl -ge 2 -and $dtl -le 120 -and $cur.rx -ge $vorig.rx -and $cur.tx -ge $vorig.tx) {
                $inv = [Globalization.CultureInfo]::InvariantCulture
                $r.live_down_mbs = (($cur.rx - $vorig.rx) / $dtl / 1MB).ToString('0.0', $inv)
                $r.live_up_mbs = (($cur.tx - $vorig.tx) / $dtl / 1MB).ToString('0.0', $inv)
            }
        }
    } catch { $Script:LiveNicNaam = $null; $Script:LiveVorig = $null }
    return $r
}$Script:NetMeting = $null; $Script:NetMetingTijd = $null; $Script:NetMetingStart = Get-Date
function Get-NetSpeedMeting {
    $r = @{ nic_mbps = ''; nic_fouten = ''; down_mbs = ''; up_mbs = '' }
    try {
        $nu = Get-Date
        if ($Script:NetMeting -and $Script:NetMetingTijd -and (($nu - $Script:NetMetingTijd).TotalSeconds -lt 600)) { return $Script:NetMeting }
        if (-not $Script:NetMeting -and (($nu - $Script:NetMetingStart).TotalSeconds -lt 30)) { return $r }
        $Script:NetMetingTijd = $nu
        $srv = Get-ServerCacheHostQuick
        if ($srv) {
            $inv = [Globalization.CultureInfo]::InvariantCulture
            try {
                $ifx = (Find-NetRoute -RemoteIPAddress $srv -ErrorAction Stop | Where-Object { $_.InterfaceIndex } | Select-Object -First 1).InterfaceIndex
                $na = Get-NetAdapter -InterfaceIndex $ifx -ErrorAction Stop
                if ([double]$na.Speed -gt 0) { $r.nic_mbps = [string][int]([double]$na.Speed / 1e6) }
                $stn = Get-NetAdapterStatistics -Name $na.Name -ErrorAction Stop
                $r.nic_fouten = [string][int]([double]$stn.ReceivedPacketErrors + [double]$stn.OutboundPacketErrors)
            } catch {}
            try {
                $sc = Resolve-ServerCachePath
                if ($sc) {
                    $tp = Join-Path $sc 'speedtest\test-256MB.bin'
                    if (Test-Path $tp) {
                        $fs = New-Object IO.FileStream($tp, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::ReadWrite, [int]1MB, [IO.FileOptions]::SequentialScan)
                        try {
                            $lenT = $fs.Length
                            if ($lenT -ge 40MB) {
                                $maxMb = [int](($lenT - 24MB) / 1MB); $startPos = (Get-Random -Minimum 0 -Maximum $maxMb) * 1MB; [void]$fs.Seek($startPos, 'Begin')
                                $buf = New-Object byte[] (1MB); $gelezen = 0L; $sw = [Diagnostics.Stopwatch]::StartNew()
                                while ($gelezen -lt 24MB -and $sw.Elapsed.TotalSeconds -lt 5) { $n = $fs.Read($buf, 0, $buf.Length); if ($n -le 0) { break }; $gelezen += $n }
                                $sw.Stop()
                                if ($gelezen -ge 4MB -and $sw.Elapsed.TotalSeconds -gt 0) { $r.down_mbs = ($gelezen / 1MB / $sw.Elapsed.TotalSeconds).ToString('0.0', $inv) }
                            }
                        } finally { $fs.Dispose() }
                    }
                }
            } catch {}
            try {
                $sd = Get-StatusDirVroeg
                $serieM = "$Serial" -replace '[^A-Za-z0-9_-]', ''
                if ($sd -and $serieM -and (Test-Path $sd -PathType Container)) {
                    $ud = Join-Path $sd 'snelheid'; if (-not (Test-Path $ud)) { New-Item -ItemType Directory -Force -Path $ud | Out-Null }
                    $upPad = Join-Path $ud "$serieM.bin"; $wbuf = New-Object byte[] (1MB); (New-Object Random).NextBytes($wbuf)
                    $geschreven = 0L; $sw2 = [Diagnostics.Stopwatch]::StartNew()
                    $fs2 = New-Object IO.FileStream($upPad, [IO.FileMode]::Create, [IO.FileAccess]::Write, [IO.FileShare]::None, [int]1MB, [IO.FileOptions]::WriteThrough)
                    try { while ($geschreven -lt 12MB -and $sw2.Elapsed.TotalSeconds -lt 5) { $fs2.Write($wbuf, 0, $wbuf.Length); $geschreven += $wbuf.Length }; $fs2.Flush() } finally { $fs2.Dispose() }
                    $sw2.Stop(); try { [IO.File]::Delete($upPad) } catch {}
                    if ($geschreven -ge 4MB -and $sw2.Elapsed.TotalSeconds -gt 0) { $r.up_mbs = ($geschreven / 1MB / $sw2.Elapsed.TotalSeconds).ToString('0.0', $inv) }
                }
            } catch {}
        }
        $Script:NetMeting = $r
    } catch {}
    return $r
}
function Send-ServerStatus {
    param([switch]$Klaar, [string]$Fase)
    try {
        $nu = Get-Date
        if (-not $Klaar -and $Script:LaatsteStatusTijd -and (($nu - $Script:LaatsteStatusTijd).TotalSeconds -lt 10)) { return }
        $Script:LaatsteStatusTijd = $nu
        $dir = Get-StatusDirVroeg
        if (-not $dir -or -not (Test-Path $dir -PathType Container -ErrorAction SilentlyContinue)) { return }
        $serie = "$Serial" -replace '[^A-Za-z0-9_-]', ''
        if (-not $serie) { return }
        $b = $null; try { $b = Get-CimInstance Win32_Battery -ErrorAction Stop | Select-Object -First 1 } catch {}
        $accu = if ($b -and $null -ne $b.EstimatedChargeRemaining) { "$($b.EstimatedChargeRemaining)" } else { "" }
        $lader = if ($b) { if ($b.BatteryStatus -in @(2,3,6,7,8,9)) { "ja" } else { "nee" } } else { "" }
        $ipTxt = ""   # v3.252: bronadres naar de server, zodat het dashboard kan zien of de laptop herstart (geen ping meer)
        try { $srvHost = Get-ServerCacheHostQuick; if ($srvHost) { $u = New-Object System.Net.Sockets.UdpClient; $u.Connect($srvHost, 445); $ipTxt = $u.Client.LocalEndPoint.Address.ToString(); $u.Close() } } catch {}
        $laatste = ("$($Script:LaatsteLogRegel)" -replace '[\r\n=]', ' ')
        if ($laatste.Length -gt 200) { $laatste = $laatste.Substring(0, 200) }
        $activiteitTxt = ("$($Script:InstallActiviteitTekst)" -replace '[\r\n=]', ' '); if ($activiteitTxt.Length -gt 160) { $activiteitTxt = $activiteitTxt.Substring(0, 160) }   # v3.277: of Windows echt bezig is (alleen tijdens een lange installatie)
        $nm = @{ nic_mbps = ''; nic_fouten = ''; down_mbs = ''; up_mbs = '' }; try { $nm = Get-NetSpeedMeting } catch {}   # v3.280: verbinding/snelheid van deze laptop naar de server
        $lv = @{ live_down_mbs = ''; live_up_mbs = '' }; try { $lv = Get-NetLive } catch {}   # v3.281: live ophalen/terugsturen van deze laptop
        $faseTxt = if ($Fase) { $Fase } else { "$($State.Phase)" }
        # v3.265: Windows-versie, build en doelversie voor het dashboard
        # v3.271: het ECHTE doel melden (doelversie.txt kan de bovenin bepaalde waarde overrulen; die wordt pas in de feature-fase opnieuw bepaald); max. 1x per minuut opnieuw bepalen
        $doelTxt = "$($Script:ResolvedTargetFeatureVersion)"; try { if (-not $Script:DoelTekstTijd -or ((Get-Date) - $Script:DoelTekstTijd).TotalSeconds -ge 60) { $Script:DoelTekstTijd = Get-Date; $ovd = Get-DoelversieOverride; $Script:DoelTekstCache = if ($ovd) { $ovd } else { "$($Script:ResolvedTargetFeatureVersion)" } }; if ($Script:DoelTekstCache) { $doelTxt = $Script:DoelTekstCache } } catch {}
        $winVer = ""; $winBuild = ""; try { $cvk = Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion" -ErrorAction Stop; $winVer = "$($cvk.DisplayVersion)"; $winBuild = "$($cvk.CurrentBuild).$($cvk.UBR)" } catch {}
        # (windows-regels staan hieronder in de regels-lijst)
        $regels = @(
            "serienummer=$serie",
            "klant=$($State.Klant)", "ordernummer=$($State.Ordernummer)", "engineer=$($State.Engineer)",
            "fase=$faseTxt", "herstarts=$($State.RebootCount)", "mislukt=$($State.TotalFailed)",
            # v3.252: voor het dashboard (stappenplan + verwachte eindtijd): echte starttijd van de run, huidige FASE-regel, ingestelde opties
            "runstart=$($State.RunStartedAt)", "stap=$($Script:HuidigeFase)",
            "ip=$ipTxt", "bootnext=$($Script:BootNextStatus)",
            "opt_store=$($State.StoreUpdates)", "opt_software=$($State.SoftwareUpdates)",
            "opt_branding=$(if ($State.BrandingLockscreen -eq 'Ja' -or $State.BrandingWallpaper -eq 'Ja' -or $State.BrandingBootlogo -eq 'Ja') { 'Ja' } else { 'Nee' })",
            "voltooid_oem=$($State.OemDone)", "voltooid_wu=$($State.WinUpdateDone)", "voltooid_feature=$($State.FeatureUpdateDone)",
            "klaar=$(if ($Klaar) { 'ja' } else { 'nee' })",
            "verificatie=$($Script:VerificatieStatus)", "verificatie_sinds=$($Script:VerificatieSinds)", "modelsleutel=$(try { Get-ModelSleutel } catch { '' })",
            "accu=$accu", "lader=$lader",
            "versie=$($Config.ToolVersion)",
            "windows=$winVer", "build=$winBuild", "doel=$doelTxt", "oem=$(("$($Script:OemSamenvatting)" -replace '[\r\n=]', ' '))",
            "activiteit=$activiteitTxt",
            "nic_mbps=$($nm.nic_mbps)", "nic_fouten=$($nm.nic_fouten)", "down_mbs=$($nm.down_mbs)", "up_mbs=$($nm.up_mbs)",
            "live_down_mbs=$($lv.live_down_mbs)", "live_up_mbs=$($lv.live_up_mbs)",
            "oem_pakketten=$(if ($Script:OemPakketten) { try { if ("$($State.OemPakketten)" -ne "$($Script:OemPakketten)") { $State | Add-Member -NotePropertyName OemPakketten -NotePropertyValue "$($Script:OemPakketten)" -Force; Save-State $State } } catch {}; $Script:OemPakketten } elseif ("$($State.OemPakketten)") { "$($State.OemPakketten)" } else { '' })",
            "apparaatfouten=$(if ($null -ne $Script:ApparaatFouten) { $Script:ApparaatFouten } else { '' })",
            "defender_dagen=$(if ($null -ne $Script:DefenderDagenOud) { $Script:DefenderDagenOud } else { '' })",
            "defender_platform=$(if ($Script:DefenderStand) { $Script:DefenderStand.Platform } else { '' })", "defender_definities=$(if ($Script:DefenderStand) { $Script:DefenderStand.Definities } else { '' })", "defender_definities_tijd=$(if ($Script:DefenderDefTijd) { $Script:DefenderDefTijd.ToString('yyyy-MM-dd HH:mm:ss') } else { '' })",
            "merk=$(try { "$((Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).Manufacturer)" -replace '[\r\n=]', ' ' } catch { '' })",
            "model=$(try { $cs0 = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop; $cv0 = "$((Get-CimInstance Win32_ComputerSystemProduct -ErrorAction Stop).Version)"; ("$($cs0.Model) $cv0").Trim() -replace '[\r\n=]', ' ' } catch { '' })",
            "laatste=$laatste",
            "tijd=$($nu.ToUniversalTime().ToString('yyyy-MM-dd HH:mm:ss'))"
        )
        $tmp = Join-Path $dir ("$serie.tmp")
        [System.IO.File]::WriteAllText($tmp, ($regels -join "`r`n") + "`r`n", (New-Object System.Text.UTF8Encoding($false)))
        Move-Item -Path $tmp -Destination (Join-Path $dir "$serie.txt") -Force -ErrorAction Stop
        try { Copy-ConsoleLogNaarServer -StatusDir $dir -Serie $serie -Forceer:$Klaar } catch {}
        try { Push-EvtxTussentijds -StatusDir $dir -Serie $serie -Forceer:$Klaar } catch {}
    } catch {}
}

function Get-WuOnlineAanbod {
    # v3.298: gedeelde ALLEEN-LEZEN zoekopdracht naar wat Microsoft Update online nog aanbiedt (stond inline in Write-DriverBewijs, v3.291). Zoekt alleen (Search), downloadt/installeert NIETS. Aparte taak met harde timeout.
    param([int]$TimeoutSec = 240)
    $res = @{ Status = 'fout'; Regels = @() }
    $job = $null
    try {
        $job = Start-Job -ScriptBlock { try { $s = New-Object -ComObject Microsoft.Update.Session; $z = $s.CreateUpdateSearcher(); $r = $z.Search("IsInstalled=0 and IsHidden=0"); @($r.Updates | ForEach-Object { "{0} | KB={1} | type={2} | categorie={3} | id={4}" -f $_.Title, ($_.KBArticleIDs -join ','), $(if ($_.Type -eq 2) { 'driver' } else { 'software' }), (($_.Categories | ForEach-Object { $_.Name }) -join '/'), $_.Identity.UpdateID }) } catch { "FOUT: $($_.Exception.Message)" } }
        if (Wait-Job -Job $job -Timeout $TimeoutSec) {
            $res.Regels = @(Receive-Job -Job $job -ErrorAction SilentlyContinue)
            $res.Status = 'ok'
        } else {
            $res.Status = 'timeout'
            try { Stop-Job -Job $job } catch {}
        }
    } catch {
        $res.Status = 'fout'
        $res.Regels = @("FOUT: $($_.Exception.Message)")
    } finally {
        try { if ($job) { Remove-Job -Job $job -Force -ErrorAction SilentlyContinue } } catch {}
    }
    return $res
}

function Invoke-OfflineWuVergelijking {
    # v4.28 (21 okt 2026, Roderick: "vergelijken is toch vergelijken? als het klopt, dan klopt het"): zonder internet vergelijkt de laptop zichzelf OFFLINE met de Microsoft-catalogus wsusscn2.cab (Windows Update Agent, ALLEEN ZOEKEN: niets downloaden, niets installeren).
    # De catalogus komt van de server (<share>\WSUS\scan, door scripts\343 actueel gehouden) en wordt pas gebruikt na controle op SHA-256 (uit wsusscn2.txt) en een geldige Microsoft-handtekening. Dekt Windows-updates, GEEN driver-aanbod van Microsoft Update en geen fabrikantdrivers.
    # Schrijft <status>\wu-offline\<serie>.txt voor scripts\180. Elke voorwaarde die niet klopt (geen catalogus, hash, handtekening, geen beheerder, scan mislukt of te langzaam) geeft Gelukt=$false met een reden: geen bewijs, nooit stil groen.
    param([string]$StatusDir, [string]$Serie, [int]$MaxMinuten = 25, [string]$LokaalDir = 'C:\EspritICT\scan')
    $res = @{ Gelukt = $false; Tekst = ''; Aantal = -1; CatalogusDatum = ''; Seconden = 0; Regels = @() }
    $naam = 'EspritOfflineScan'; $sm = $null; $svc = $null; $job = $null
    $lokaal = Join-Path $LokaalDir 'wsusscn2.cab'
    try {
        if (-not $StatusDir -or -not $Serie) { $res.Tekst = 'statusmap of serienummer onbekend'; return $res }
        $scanDir = Join-Path (Split-Path -Parent $StatusDir) 'WSUS\scan'
        $bron = Join-Path $scanDir 'wsusscn2.cab'; $infoP = Join-Path $scanDir 'wsusscn2.txt'
        if (-not (Test-Path -LiteralPath $bron) -or -not (Test-Path -LiteralPath $infoP)) { $res.Tekst = 'de scancatalogus staat niet op de server (WSUS\scan\wsusscn2.cab + wsusscn2.txt)'; return $res }
        $info = @{}
        foreach ($l in @(Get-Content -LiteralPath $infoP -Encoding UTF8 -ErrorAction Stop)) { if ("$l" -match '^\s*([A-Za-z0-9_]+)\s*=\s*(.*)$') { $info[$Matches[1]] = $Matches[2].Trim() } }
        if (-not $info['sha256'] -or -not $info['bron_datum']) { $res.Tekst = 'wsusscn2.txt is onvolledig (sha256 of bron_datum ontbreekt)'; return $res }
        $res.CatalogusDatum = $info['bron_datum']
        New-Item -ItemType Directory -Path $LokaalDir -Force | Out-Null
        if (Test-Path -LiteralPath $lokaal) { [IO.File]::Delete($lokaal) }
        [IO.File]::Copy($bron, $lokaal, $true)
        $h = (Get-FileHash -LiteralPath $lokaal -Algorithm SHA256).Hash
        if ($h -ne $info['sha256']) { $res.Tekst = "de gekopieerde catalogus heeft een andere SHA-256 ($h) dan wsusscn2.txt ($($info['sha256'])): NIET gebruikt"; return $res }
        $sig = Get-AuthenticodeSignature -LiteralPath $lokaal
        if ($sig.Status -ne 'Valid' -or -not $sig.SignerCertificate -or $sig.SignerCertificate.Subject -notmatch 'Microsoft') { $res.Tekst = "de handtekening van de catalogus is niet geldig of niet van Microsoft (status $($sig.Status)): NIET gebruikt"; return $res }
        $isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
        if (-not $isAdmin) { $res.Tekst = 'geen beheerdersrechten: de offline scan kan zonder die rechten geen scanservice toevoegen (0x80070005)'; return $res }
        $t0 = Get-Date
        $sm = New-Object -ComObject Microsoft.Update.ServiceManager
        foreach ($sv in @($sm.Services)) { if ($sv.Name -eq $naam) { try { $sm.RemoveService($sv.ServiceID) } catch {} } }   # een achtergebleven testservice van een eerdere (afgebroken) poging
        $svc = $sm.AddScanPackageService($naam, $lokaal, 1)
        $job = Start-Job -ScriptBlock { param($id) try { $x = New-Object -ComObject Microsoft.Update.Session; $z = $x.CreateUpdateSearcher(); $z.ServerSelection = 3; $z.ServiceID = $id; $r = $z.Search("IsInstalled=0 and IsHidden=0 and Type='Software'"); "RC=$($r.ResultCode)"; foreach ($u in $r.Updates) { "{0} | KB={1} | type=software | categorie={2} | id={3}" -f $u.Title, ($u.KBArticleIDs -join ','), (($u.Categories | ForEach-Object { $_.Name }) -join '/'), $u.Identity.UpdateID } } catch { "FOUT: $($_.Exception.Message)" } } -ArgumentList $svc.ServiceID
        $eind = (Get-Date).AddMinutes($MaxMinuten); $nood = Get-Date
        while ($job.State -eq 'Running' -and (Get-Date) -lt $eind) {
            Start-Sleep 5
            try { Update-Heartbeat } catch {}
            if (((Get-Date) - $nood).TotalSeconds -ge 30) { $nood = Get-Date; try { if (Test-NoodStop) { Write-Host ""; Invoke-NoodStop } } catch {} }
        }
        if ($job.State -eq 'Running') { try { Stop-Job -Job $job } catch {}; $res.Tekst = "de offline scan duurde langer dan $MaxMinuten min en is afgebroken"; return $res }
        $uit = @(Receive-Job -Job $job -ErrorAction SilentlyContinue)
        $res.Seconden = [int]((Get-Date) - $t0).TotalSeconds
        $fout = @($uit | Where-Object { "$_" -match '^FOUT:' })
        if ($fout.Count -gt 0) { $res.Tekst = "de offline scan gaf een fout: $($fout[0])"; return $res }
        $rcRegel = @($uit | Where-Object { "$_" -match '^RC=\d+$' } | Select-Object -First 1)
        if ($rcRegel.Count -eq 0) { $res.Tekst = 'de offline scan gaf geen resultaatcode'; return $res }
        $rc = [int](("$($rcRegel[0])") -replace '^RC=', '')
        if ($rc -ne 2) { $res.Tekst = "de offline scan is niet geslaagd (ResultCode $rc, verwacht 2)"; return $res }
        $open = @($uit | Where-Object { "$_" -notmatch '^RC=' -and "$_".Trim() })
        $res.Aantal = $open.Count; $res.Regels = $open
        # uitkomst voor de server (scripts\180); atomair schrijven (eerst tijdelijk bestand, dan verplaatsen)
        $wMap = Join-Path $StatusDir 'wu-offline'
        if (-not (Test-Path -LiteralPath $wMap)) { New-Item -ItemType Directory -Path $wMap -Force | Out-Null }
        $doel = Join-Path $wMap "$Serie.txt"; $tmp = "$doel.tmp"
        $model = ''; try { $model = "$((Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).Model)" } catch {}
        $inhoud = @("gecontroleerd = $((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))", "serienummer = $Serie", "sleutel = $(Get-ModelSleutel)", "model = $model", "bron = offline-catalogus", "catalogus_datum = $($info['bron_datum'])", "catalogus_sha256 = $h", "scan_seconden = $($res.Seconden)", "resultcode = $rc", "openstaand = $($open.Count)", "--- openstaand") + $open
        [IO.File]::WriteAllLines($tmp, [string[]]$inhoud, (New-Object Text.UTF8Encoding($false)))
        if (Test-Path -LiteralPath $doel) { [IO.File]::Delete($doel) }
        [IO.File]::Move($tmp, $doel)
        if (-not (Test-Path -LiteralPath $doel)) { $res.Tekst = 'de uitkomst kon niet naar de server geschreven worden'; $res.Aantal = -1; return $res }
        $res.Gelukt = $true
        $res.Tekst = "OFFLINE vergelijking met de Microsoft-catalogus van $($info['bron_datum']) (UTC): $($open.Count) update(s) openstaand, scan $($res.Seconden) s"
        return $res
    } catch {
        $res.Gelukt = $false; $res.Tekst = "offline vergelijking mislukt: $($_.Exception.Message)"
        return $res
    } finally {
        try { if ($job) { Remove-Job -Job $job -Force -ErrorAction SilentlyContinue } } catch {}
        try { if ($sm -and $svc) { $sm.RemoveService($svc.ServiceID) } } catch { Log "[LET OP] [VERIFICATIE] tijdelijke scanservice niet verwijderd: $($_.Exception.Message)" -Color Yellow }
        try { $rest = @((New-Object -ComObject Microsoft.Update.ServiceManager).Services | Where-Object { $_.Name -eq $naam }); if ($rest.Count -gt 0) { Log "[LET OP] [VERIFICATIE] de tijdelijke scanservice $naam staat er nog (teruggelezen)" -Color Yellow } } catch {}
        try { if (Test-Path -LiteralPath $lokaal) { [IO.File]::Delete($lokaal) } } catch {}
    }
}
function Get-VerificatieUitkomst {
    # v3.298: leest het antwoord van de server (scripts\180 -> <status>\volledigheid\<serie>.txt) op DEZE verificatiestop. Alleen een antwoord dat verificatie_sinds=<onze stempel> bevat telt; een oud antwoord van een eerdere run wordt genegeerd (geen schijn-bewezen).
    param([string]$Pad, [string]$Sinds)
    try {
        if (-not $Pad -or -not $Sinds) { return $null }
        if (-not (Test-Path $Pad -ErrorAction Stop)) { return $null }
        $h = @{}
        foreach ($l in @(Get-Content $Pad -Encoding UTF8 -ErrorAction Stop)) { if ("$l" -match '^\s*([^=#\s][^=]*)=(.*)$') { $h[$Matches[1].Trim()] = $Matches[2].Trim() } }
        if ("$($h['verificatie_sinds'])" -ne "$Sinds") { return $null }
        if (-not $h['uitkomst']) { return $null }
        return $h
    } catch { return $null }
}

# v4.11: server-flow met onbereikbare server = NIET naar Sysprep zonder bewijs. Probeert maximaal $MaxMinuten min opnieuw; geeft de status-map terug of $null.
function Wacht-OpServerVoorSysprep {
    param([string]$ServerHost, [double]$MaxMinuten = 20)
    $eind = (Get-Date).AddMinutes($MaxMinuten); $poging = 0
    Log "[VERIFICATIE] server ($ServerHost) niet bereikbaar - NIET naar Sysprep zonder bewijs; maximaal $MaxMinuten min opnieuw proberen (diensten starten, kaart herstarten, opnieuw koppelen)..." -Color Yellow
    while ((Get-Date) -lt $eind) {
        $poging++
        try { Update-Heartbeat } catch {}
        try { if (Test-NoodStop) { Invoke-NoodStop } } catch {}
        try { Start-NetwerkDiensten } catch {}
        try { [void](Set-ServerMacStatisch -ServerHost $ServerHost) } catch {}
        try { Restart-NetwerkKaartAlsStil -ServerHost $ServerHost } catch {}
        $d = $null; try { $d = Get-StatusDirVroeg } catch {}
        if ($d -and (Test-Path $d -PathType Container -ErrorAction SilentlyContinue)) { Log "[VERIFICATIE] server weer bereikbaar na $poging pogingen." -Color Green; return $d }
        Start-Sleep 20
    }
    return $null
}
function Test-VerseOnlineVergelijking {
    # v4.32 (24 okt 2026): is er voor dit model een online vergelijking met Microsoft Update die scripts\180 als bruikbaar accepteert? Dan is de offline scan overbodig. Zelfde eisen als 180 (Test-WuGaten), met 1 dag marge op GatenMaxDagen (10): bron verificatiestop/bewijsrapport/oogstvenster, niet ouder dan $MaxDagen dagen, niet in de toekomst, openstaand = 0. Elke twijfel = Vers $false (dan draait de offline scan als altijd).
    param([string]$StatusDir, [string]$Sleutel, [double]$MaxDagen = 9)
    $r = @{ Vers = $false; Tekst = '' }
    if (-not $Sleutel) { $r.Tekst = 'modelsleutel onbekend'; return $r }
    $p = Join-Path $StatusDir ("wu-gaten\" + $Sleutel + ".txt")
    if (-not (Test-Path -LiteralPath $p)) { $r.Tekst = "geen online vergelijking voor model $Sleutel"; return $r }
    $kv = @{}
    try {
        foreach ($l in @(Get-Content -LiteralPath $p -Encoding UTF8 -ErrorAction Stop)) {
            $l2 = ("$l").TrimStart([char]0xFEFF)
            if ($l2 -like '--- openstaand*') { break }
            if ($l2 -match '^\s*([^=\s]+)\s*=\s*(.*)$') { $kv[$Matches[1].Trim().ToLower()] = $Matches[2].Trim() }
        }
    } catch { $r.Tekst = "online vergelijking onleesbaar ($($_.Exception.Message))"; return $r }
    $bron = "$($kv['bron'])".Trim()
    if ($bron -notin @('verificatiestop', 'bewijsrapport', 'oogstvenster')) { $r.Tekst = "online vergelijking van model $Sleutel heeft bron '$bron' (telt niet)"; return $r }
    $gec = [datetime]::MinValue
    if (-not [datetime]::TryParseExact("$($kv['gecontroleerd'])".Trim(), 'yyyy-MM-dd HH:mm:ss', [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::None, [ref]$gec)) { $r.Tekst = "online vergelijking van model $Sleutel heeft geen leesbare datum"; return $r }
    $dagen = ((Get-Date) - $gec).TotalDays
    if ($dagen -lt -0.05) { $r.Tekst = "online vergelijking van model $Sleutel ligt in de toekomst ($($gec.ToString('yyyy-MM-dd HH:mm')))"; return $r }
    if ($dagen -gt $MaxDagen) { $r.Tekst = "online vergelijking van model $Sleutel is $([math]::Floor($dagen)) dagen oud (maximaal $MaxDagen)"; return $r }
    if ("$($kv['openstaand'])".Trim() -ne '0') { $r.Tekst = "online vergelijking van model $Sleutel meldt openstaand = '$($kv['openstaand'])' (niet 0)"; return $r }
    $r.Vers = $true
    $r.Tekst = "verse online vergelijking voor model $Sleutel (bron $bron, $($gec.ToString('yyyy-MM-dd HH:mm')), $([math]::Round($dagen, 1)) dagen oud, 0 openstaand)"
    return $r
}
function Get-VerificatieUitleg {
    # v4.34 (26 okt 2026, Roderick: 'totaal geen uitleg waarom hij niet af was'; bewijs: Surface 033135623657 stond 30 min stil met een reden waarin GOED nieuws ("pakket is gelijk aan of nieuwer") naast de echte oorzaak stond, zonder uitleg wat nu te doen). Zet de reden van de server om in punten in gewone taal: IN ORDE / NIET BEWEZEN / NIET GEDAAN, met uitleg en of het aan de server of aan deze laptop ligt. Gebruikt de aparte delen (deel_fabrikant, deel_microsoft_update) als de server die meegeeft (scripts\180 v4.34), anders de tekst zelf.
    param([string]$Reden, $Antwoord = $null, [string[]]$Gemist = @())
    $uit = New-Object System.Collections.Generic.List[object]
    $punten = New-Object System.Collections.Generic.List[object]
    $delen = @()
    if ($Antwoord) {
        foreach ($sl in @('deel_fabrikant', 'deel_microsoft_update')) {
            $dv = "$($Antwoord[$sl])"
            if ($dv -match '^(bewezen|niet-bewezen|afwijking|herstel)\|(.*)$') { $delen += ,@($Matches[1], $Matches[2]) }
        }
    }
    if ($delen.Count -gt 0) {
        foreach ($d in $delen) { foreach ($p in @($d[1] -split ';\s+' | ForEach-Object { $_.Trim() } | Where-Object { $_ })) { $punten.Add([pscustomobject]@{ Uitkomst = $d[0]; Tekst = $p }) } }
    } else {
        $kaal = "$Reden" -replace '^(volledigheid|GEFORCEERD)[^:]*:\s*', ''
        foreach ($p in @($kaal -split ';\s+' | ForEach-Object { $_.Trim() } | Where-Object { $_ })) {
            $u = if ($p -match 'gelijk aan of nieuwer dan het nieuwste|OFFLINE \([^)]*\): 0 openstaand') { 'bewezen' } else { 'niet-bewezen' }
            $punten.Add([pscustomobject]@{ Uitkomst = $u; Tekst = $p })
        }
    }
    $gezien = @{}
    foreach ($pt in $punten) {
        if ($gezien.ContainsKey($pt.Tekst)) { continue }
        $gezien[$pt.Tekst] = $true
        $soort = if ($pt.Uitkomst -eq 'bewezen') { 'IN ORDE' } else { 'NIET BEWEZEN' }
        $kant = 'laptop'; $uitleg = ''
        if ($soort -ne 'IN ORDE') {
            if ($pt.Tekst -match 'mislukte zoekopdracht') { $kant = 'server'; $uitleg = 'De SERVER kon bij Microsoft Update niet alles opzoeken voor dit model. Dat ligt aan de server, niet aan deze laptop; de online controle van de server moet opnieuw draaien (scripts\171 -Hercontroleer).' }
            elseif ($pt.Tekst -match 'langer dan \d+ uur geleden|server-controle ontbreekt|nog niet online gecontroleerd|geen datum van een online') { $kant = 'server'; $uitleg = 'De online controle van de server voor dit model is te oud of ontbreekt. Deze laptop heeft zelf bewust geen internet.' }
            elseif ($pt.Tekst -match 'geen geinstalleerd Surface-pakket') { $uitleg = 'In deze run is het Surface-pakket (drivers en firmware) NIET geinstalleerd. Een pakket uit een eerdere run telt niet mee.' }
            elseif ($pt.Tekst -match 'nog iets nieuws in de cache') { $kant = 'server'; $uitleg = 'De server haalde tijdens deze run nog iets nieuws op dat deze laptop niet heeft gehad.' }
        }
        $uit.Add([pscustomobject]@{ Soort = $soort; Tekst = $pt.Tekst; Uitleg = $uitleg; Kant = $kant })
    }
    foreach ($g in @($Gemist)) { if ($g) { $uit.Add([pscustomobject]@{ Soort = 'NIET GEDAAN'; Tekst = $g; Uitleg = 'Dit onderdeel is in deze run overgeslagen (strikte servercache-modus: geen online terugval).'; Kant = 'laptop' }) } }
    return $uit.ToArray()
}
function Get-CacheSchijfMelding {
    # v4.34 (26 okt 2026, Roderick: 'de ssd schijf zat er niet in, maar dat geeft hij ook niet aan'; bewijs: de koppelingen modeldrivers, Surface-Repository en WSUS op de server wijzen naar D:\share-utilities; zonder SSD zijn ze leeg en zag de laptop 'geen .msi'). De server schrijft status\cache-schijf.txt (scripts\424); is de toestand niet ok, dan geeft dit een duidelijke zin, anders een lege tekst.
    try {
        $d = Get-StatusDirVroeg; if (-not $d) { return '' }
        $p = Join-Path $d 'cache-schijf.txt'; if (-not (Test-Path -LiteralPath $p)) { return '' }
        $h = @{}; foreach ($l in @(Get-Content -LiteralPath $p -Encoding UTF8 -ErrorAction Stop)) { if ("$l" -match '^\s*([^=#\s][^=]*)=(.*)$') { $h[$Matches[1].Trim()] = $Matches[2].Trim() } }
        if ($h['toestand'] -and $h['toestand'] -ne 'ok') { return "DE CACHE-SCHIJF (SSD) VAN DE SERVER ONTBREEKT of is niet leesbaar (gemeld door de server om $($h['tijd']): $($h['details'])). Steek de SSD in de server; zonder die schijf zijn de Surface-, driver- en WSUS-mappen leeg." }
    } catch {}
    return ''
}
function Wait-SurfaceMsi {
    # v4.34 (26 okt 2026; bewijs: Surface 033135623657 run 1 op 25 okt 11:48:21 zag in Z:\drivers\Surface-Repository GEEN .msi terwijl het bestand er (sinds 16 okt) stond en 31 min later wel werd gevonden; oorzaak van die ene lege lijst is NIET bewezen). Zoekt maximaal $WachtMin min opnieuw (elke $PauzeSec s) en legt per poging vast hoeveel .msi-bestanden de laptop zag. $Zoek is het zoekblok (geeft het bestand of $null).
    param([scriptblock]$Zoek, [string]$RepoPath, [double]$WachtMin = 4, [int]$PauzeSec = 20)
    $gevonden = $null; $tot = (Get-Date).AddMinutes($WachtMin); $poging = 0
    while ((Get-Date) -lt $tot) {
        $poging++
        $gezien = @(Get-ChildItem -LiteralPath $RepoPath -Filter '*.msi' -File -ErrorAction SilentlyContinue)
        $bereikbaar = Test-Path -LiteralPath $RepoPath
        Log "  [Surface] poging ${poging} om het pakket in de servercache te vinden: map bereikbaar=$bereikbaar, $($gezien.Count) .msi-bestand(en) gezien" -Color Gray
        $gevonden = & $Zoek
        if ($gevonden) { Log "  [Surface] pakket gevonden bij poging ${poging}: $($gevonden.Name)" -Color Green; break }
        Start-Sleep -Seconds $PauzeSec
        try { Update-Heartbeat } catch {}
    }
    return [pscustomobject]@{ Gevonden = $gevonden; Pogingen = $poging; MsiAantal = @(Get-ChildItem -LiteralPath $RepoPath -Filter '*.msi' -File -ErrorAction SilentlyContinue).Count }
}
function Invoke-VerificatieStop {
    # v3.298 (10 okt 2026, Roderick: 'dat gaan we doen'): verificatiestop vlak voor Sysprep. Alleen met een bereikbare server (stand-alone stick-flow blijft ongewijzigd), niet in update-only, maximaal 1x per run.
    # Stap A: de server (scripts\180) vergelijkt met de LIVE catalogus van de fabrikant; wij wachten maximaal $WachtOpServerMin min op dat antwoord. 'bewezen' = direct door.
    # Stap B: anders (afwijking, niet-bewezen of geen antwoord) pauzeren we maximaal $WachtOpEngineerMin min: engineer zet Wi-Fi aan, de laptop zoekt dan ZELF (alleen lezen) wat Microsoft Update nog aanbiedt en legt dat vast; vrijgeven kan eerder (status\vrijgave\<serie>.txt of C:\Windows\Temp\verificatie-vrijgave.txt). Daarna gaat Sysprep door; het dashboard blijft dan 'klaar met voorbehoud'.
    param([double]$WachtOpServerMin = 8, [double]$WachtOpEngineerMin = 30, [double]$TweedeScanNaMin = 5, [double]$HerhaalVraagNaMin = 5, [int]$MaxHerhaalVragen = 8, [int]$HerhaalWachtSec = 150)
    if ($State.UpdateOnlyMode) { return }
    try { if ($State.PSObject.Properties['VerificatieStopGedaan'] -and $State.VerificatieStopGedaan) { Log "[VERIFICATIE] al gedaan in deze run - niet opnieuw." -Color Gray; return } } catch {}
    $vDir = Get-StatusDirVroeg
    if (-not $vDir -or -not (Test-Path $vDir -PathType Container -ErrorAction SilentlyContinue)) {
        $vHostCfg = $null; try { $vHostCfg = Get-ServerCacheHostQuick } catch {}
        if (-not $vHostCfg) {
            Log "[VERIFICATIE] overgeslagen: geen servercache/status bereikbaar (stand-alone flow blijft ongewijzigd)." -Color Gray
            return
        }
        # v4.11: server-flow, server onbereikbaar: fail-closed
        $vDir = Wacht-OpServerVoorSysprep -ServerHost $vHostCfg
        if (-not $vDir) {
            Log "==================================================" -Color Red
            Log "  STOP VOOR SYSPREP - server ($vHostCfg) niet bereikbaar" -Color Red
            Log "==================================================" -Color Red
            Log "  Zonder server is er geen bewijs dat dit toestel volledig is bijgewerkt; Sysprep zou ook het logboek wissen." -Color Red
            Log "  Het toestel blijft in Audit Mode (geen Sysprep, geen herstart). Engineer: controleer kabel/netwerk en start het script daarna opnieuw (C:\EspritICT\audit-update.ps1)." -Color Red
            try { $State | Add-Member -NotePropertyName SysprepGeblokkeerdServerWeg -NotePropertyValue $true -Force; Save-State $State } catch {}
            try { Send-ServerStatus -Fase "STOP VOOR SYSPREP - server onbereikbaar" } catch {}
            exit
        }
    }
    $vSerie = "$Serial" -replace '[^A-Za-z0-9_-]', ''
    if (-not $vSerie) { Log "[VERIFICATIE] overgeslagen: serienummer onbekend." -Color Yellow; return }
    $vSinds = (Get-Date).ToString('yyyyMMddHHmmss')
    try { $State | Add-Member -NotePropertyName VerificatieStopGedaan -NotePropertyValue $true -Force; Save-State $State } catch {}
    $vBewijs = { param($regels) try { $bm = Join-Path $vDir 'bewijs'; if (-not (Test-Path $bm)) { New-Item -ItemType Directory -Path $bm -Force | Out-Null }; Add-Content -Path (Join-Path $bm "$vSerie.log") -Value @($regels) -Encoding UTF8 -ErrorAction Stop } catch { Log "[LET OP] [VERIFICATIE] bewijsregels niet weggeschreven: $($_.Exception.Message)" -Color Yellow } }
    $vNu = { (Get-Date).ToString('yyyy-MM-dd HH:mm:ss') }

    # --- Stap 0 (v4.28): OFFLINE vergelijking met de Microsoft-catalogus; zonder internet de enige onafhankelijke Windows Update-vergelijking van deze laptop zelf. Een fout hierin blokkeert niets: de server telt dan 'niet bewezen' en de stop voor Sysprep werkt als altijd. ---
    $vVers = $null
    try { $vVers = Test-VerseOnlineVergelijking -StatusDir $vDir -Sleutel (Get-ModelSleutel) } catch { $vVers = $null }
    if ($vVers -and $vVers.Vers) {
        Log "[VERIFICATIE] offline scan OVERGESLAGEN: $($vVers.Tekst); de server gebruikt die online vergelijking." -Color Cyan
        & $vBewijs @("[verificatie] $(& $vNu) Windows Update OFFLINE: overgeslagen ($($vVers.Tekst)); alleen de online vergelijking telt voor het oordeel van de server")
    } else {
    if ($vVers) { Log "[VERIFICATIE] offline scan nodig: $($vVers.Tekst)" -Color Gray }
    try {
        try { Send-ServerStatus -Fase "OFFLINE WINDOWS-UPDATE-VERGELIJKING (catalogus van de server)" } catch {}
        Log "[VERIFICATIE] dit toestel wordt OFFLINE vergeleken met de Microsoft-catalogus van de server (alleen lezen, duurt enkele minuten)..." -Color Cyan
        $vOff = Invoke-OfflineWuVergelijking -StatusDir $vDir -Serie $vSerie
        if ($vOff.Gelukt) {
            Log "[VERIFICATIE] $($vOff.Tekst)" -Color $(if ($vOff.Aantal -eq 0) { 'Green' } else { 'Yellow' })
            $vOffR = @("[verificatie] $(& $vNu) Windows Update OFFLINE (catalogus van $($vOff.CatalogusDatum) UTC): $($vOff.Aantal) update(s) openstaand, scan $($vOff.Seconden) s (alleen gezocht, niets geinstalleerd)")
            foreach ($u in @($vOff.Regels)) { $vOffR += ("[verificatie]   WU-offline: " + $u) }
            & $vBewijs $vOffR
        } else {
            Log "[VERIFICATIE] offline vergelijking GEEN bewijs: $($vOff.Tekst)" -Color Yellow
            & $vBewijs @("[verificatie] $(& $vNu) Windows Update OFFLINE: geen bewijs ($($vOff.Tekst))")
        }
    } catch { Log "[LET OP] [VERIFICATIE] offline vergelijking: onverwachte fout: $($_.Exception.Message)" -Color Yellow }
    }
    # --- Stap A: antwoord van de server afwachten ---
    $Script:VerificatieSinds = $vSinds
    $Script:VerificatieStatus = 'wacht'
    $Script:LaatsteStatusTijd = $null
    try { Send-ServerStatus -Fase "WACHT OP VOLLEDIGHEIDSCONTROLE (server)" } catch {}
    Log "[VERIFICATIE] vlak voor Sysprep: de server vergelijkt dit toestel met de live fabrikant-catalogus (maximaal $WachtOpServerMin min wachten)..." -Color Cyan
    $vUitPad = Join-Path $vDir ("volledigheid\" + $vSerie + ".txt")
    $vUit = $null
    $vEind = (Get-Date).AddMinutes($WachtOpServerMin)
    $vNood = Get-Date
    while ((Get-Date) -lt $vEind) {
        Start-Sleep 5
        try { Update-Heartbeat } catch {}
        $vUit = Get-VerificatieUitkomst -Pad $vUitPad -Sinds $vSinds
        if ($vUit) { break }
        if (((Get-Date) - $vNood).TotalSeconds -ge 30) { $vNood = Get-Date; if (Test-NoodStop) { Write-Host ""; Invoke-NoodStop } }
    }
    # v3.299: een engineer kan de stop forceren (test van Windows Update online); eenmalig, de laptop haalt het bestand zelf weg
    $vGeforceerd = $false
    $vForceerPad = Join-Path $vDir ("forceer-stop\" + $vSerie + ".txt")
    try { if (Test-Path $vForceerPad) { $vGeforceerd = $true; [IO.File]::Delete($vForceerPad) } } catch {}
    # v4.29 (21 okt 2026, niet bewezen = fixen): antwoordt de server 'herstel' (alleen als daar de herstel-schakelaar aanstaat), dan voert de laptop maximaal 2 rondes uit met ALLEEN vaste acties uit status\herstel\<serie>.txt. HERLEES = teruglezing opnieuw (nieuw bewijs); de andere acties worden op de laptop NOG NIET uitgevoerd (alleen gelogd). Daarna vraagt hij de server opnieuw (nieuwe verificatie_sinds); blijft het niet 'bewezen', dan volgt de bestaande pauze voor een engineer.
    $vHerstelRonde = 0
    while ($vUit -and $vUit['uitkomst'] -eq 'herstel' -and -not $vGeforceerd -and $vHerstelRonde -lt 2) {
        $vHerstelRonde++
        Log "[VERIFICATIE] herstel-ronde $vHerstelRonde van 2: de server noemt herstelbare punten ($($vUit['tekst']))." -Color Yellow
        $vActies = @()
        try { $vActies = @(Get-Content -LiteralPath (Join-Path $vDir ("herstel\" + $vSerie + ".txt")) -Encoding UTF8 -ErrorAction Stop | Where-Object { $_ -match '^(HERLEES|HERINSTALLEER|ZOEK-EN-HAAL|VERGELIJK-ONLINE)\t' } | ForEach-Object { ($_ -split "`t")[0] } | Select-Object -Unique) } catch {}
        foreach ($vAct in $vActies) {
            if ($vAct -eq 'HERLEES') {
                try { Write-DriverBewijs -Moment "herstel-ronde $vHerstelRonde"; & $vBewijs @("[verificatie] $(& $vNu) herstel-ronde ${vHerstelRonde}: HERLEES uitgevoerd (teruglezing opnieuw, nieuw bewijs weggeschreven)") } catch { & $vBewijs @("[verificatie] $(& $vNu) herstel-ronde ${vHerstelRonde}: HERLEES mislukt ($($_.Exception.Message))") }
            } else {
                Log "[VERIFICATIE] herstel-ronde ${vHerstelRonde}: actie $vAct wordt op de laptop nog niet uitgevoerd (een mens moet kijken)." -Color Yellow
                & $vBewijs @("[verificatie] $(& $vNu) herstel-ronde ${vHerstelRonde}: $vAct NOG NIET ondersteund op de laptop (niet uitgevoerd)")
            }
        }
        $vSinds = (Get-Date).ToString('yyyyMMddHHmmss'); $Script:VerificatieSinds = $vSinds; $Script:VerificatieStatus = 'wacht'; $Script:LaatsteStatusTijd = $null
        try { Send-ServerStatus -Fase "WACHT OP VOLLEDIGHEIDSCONTROLE (server, herstel-ronde $vHerstelRonde)" } catch {}
        $vUit = $null; $vEindH = (Get-Date).AddMinutes([math]::Min($WachtOpServerMin, 3))
        while ((Get-Date) -lt $vEindH) { Start-Sleep 5; try { Update-Heartbeat } catch {}; $vUit = Get-VerificatieUitkomst -Pad $vUitPad -Sinds $vSinds; if ($vUit) { break } }
    }
    if ($vUit -and $vUit['uitkomst'] -eq 'bewezen' -and -not $vGeforceerd) {
        Log "[VERIFICATIE] BEWEZEN door de server: $($vUit['tekst'])" -Color Green
        & $vBewijs @("[verificatie] $(& $vNu) uitkomst=bewezen: $($vUit['tekst'])")
        $Script:VerificatieStatus = 'afgerond'
        $Script:LaatsteStatusTijd = $null
        try { Send-ServerStatus -Fase "Volledigheid bewezen - door naar Sysprep" } catch {}
        return
    }

    # --- Stap B: pauze voor een engineer ---
    $vReden = if ($vGeforceerd) { "GEFORCEERD door engineer (test van Windows Update online); de server zei: " + $(if ($vUit) { "$($vUit['uitkomst']) - $($vUit['tekst'])" } else { "geen antwoord" }) } elseif ($vUit) { "volledigheid $($vUit['uitkomst']): $($vUit['tekst'])" } else { "geen antwoord van de server binnen $WachtOpServerMin min" }
    $Script:VerificatieStatus = 'stop'
    $Script:LaatsteStatusTijd = $null
    try { Send-ServerStatus -Fase "WACHT OP ENGINEER - controle vereist (zie laptop)" } catch {}
    $vVrijServer = Join-Path $vDir ("vrijgave\" + $vSerie + ".txt")
    $vVrijLokaal = "C:\EspritICT\verificatie-vrijgave.txt"
    # oude vrijgave-bestanden van een eerdere run mogen deze stop niet meteen vrijgeven
    try { if (Test-Path $vVrijServer) { [IO.File]::Delete($vVrijServer) } } catch {}
    try { if (Test-Path $vVrijLokaal) { [IO.File]::Delete($vVrijLokaal) } } catch {}
    & $vBewijs @("[verificatie] $(& $vNu) STOP voor Sysprep: $vReden")
    Log "==================================================" -Color Yellow
    Log "  STOP VOOR SYSPREP - volledigheid niet bewezen" -Color Yellow
    Log "==================================================" -Color Yellow
    Log "  Reden (zoals de server hem meldt): $vReden" -Color Yellow
    $vUitleg = @()
    try { $vUitleg = @(Get-VerificatieUitleg -Reden $vReden -Antwoord $vUit -Gemist @($Script:StriktGemist)) } catch { Log "[LET OP] uitleg niet opgebouwd: $($_.Exception.Message)" -Color Yellow }
    $csm2 = Get-CacheSchijfMelding; if ($csm2) { Log "  LET OP (waarschijnlijke hoofdoorzaak): $csm2" -Color Red }
    Log "  WAAROM STAAT DEZE LAPTOP STIL? (punt voor punt):" -Color Yellow
    foreach ($vu in $vUitleg) {
        $vk = if ($vu.Soort -eq 'IN ORDE') { 'Green' } else { 'Yellow' }
        Log ("   [{0}] {1}" -f $vu.Soort, $vu.Tekst) -Color $vk
        if ($vu.Uitleg) { Log "        Uitleg: $($vu.Uitleg)" -Color Gray }
    }
    $vNietOk = @($vUitleg | Where-Object { $_.Soort -ne 'IN ORDE' })
    $vAlleenServer = ($vNietOk.Count -gt 0 -and @($vNietOk | Where-Object { $_.Kant -ne 'server' }).Count -eq 0)
    $vGat = @($vUitleg | Where-Object { $_.Soort -eq 'NIET GEDAAN' }).Count
    $vBetekent = if ($vGat -gt 0) { 'Er is in deze run iets NIET geinstalleerd (zie NIET GEDAAN hierboven). Vrijgeven geeft een toestel met een gat.' } elseif ($vAlleenServer) { 'Alle punten die deze laptop zelf betreffen staan op IN ORDE; alleen het bewijs van de SERVER ontbreekt. Vrijgeven laat de run door; het dashboard blijft dan klaar met voorbehoud tot de server wel bewijst.' } else { 'Minstens een punt is niet bewezen op deze laptop. Vrijgeven laat de run door; het dashboard blijft dan klaar met voorbehoud.' }
    Log "  WAT BETEKENT DIT? $vBetekent" -Color Yellow
    Log "  WAT NU (engineer):" -Color Yellow
    Log "   1. Niets aan Wi-Fi doen: de laptop blijft bewust offline; online meten doet de server." -Color Yellow
    Log "   2. Klik NIET zelf op Windows Update in Instellingen: dat installeert automatisch." -Color Yellow
    Log "   3. Vrijgeven kan met scripts\181-vrijgeven.ps1 op de server (serie $vSerie), of maak hier het bestand $vVrijLokaal" -Color Yellow
    Log "   4. De laptop vraagt de server elke $HerhaalVraagNaMin min opnieuw (maximaal $MaxHerhaalVragen keer; stopt eerder als het antwoord steeds hetzelfde blijft)." -Color Yellow
    Log "  Zonder actie gaat het script na $WachtOpEngineerMin min zelf door (dashboard: klaar met voorbehoud)." -Color Yellow
    $vEind2 = (Get-Date).AddMinutes($WachtOpEngineerMin)
    $vNood = Get-Date
    $vScans = 0
    $vLaatsteScan = $null
    $vScanGelukt = $false   # v4.1: een tweede scan alleen als de eerste NIET gelukt is (anders overschrijft hij de zuivere in-run-meting met een meting van NA de handmatige Windows Update)
    $vAfloop = 'tijd verstreken'
    $vVerlengTotaal = 0   # v4.6: verlengd door de server (status\verleng\<serie>.txt), samen maximaal 120 min
    $vVerlengPad = Join-Path $vDir ('verleng\' + $vSerie + '.txt')
    $vHerhaalAantal = 0   # v4.33: herhaalvragen aan de server tijdens deze pauze
    $vLaatsteTxt = ''; $vGelijk = 0   # v4.34: telt hoe vaak de server exact dezelfde reden gaf
    $vHerhaalLaatst = Get-Date
    while ((Get-Date) -lt $vEind2) {
        Start-Sleep 5
        try { Update-Heartbeat } catch {}
        if ((Test-Path $vVrijServer) -or (Test-Path $vVrijLokaal)) { $vAfloop = 'vrijgegeven door engineer'; break }
        # v4.33 (24 okt 2026, Roderick: 'verbeter alles'; run 3 Lenovo): tijdens de pauze vraagt de laptop elke $HerhaalVraagNaMin min opnieuw aan de server (nieuw stempel = nieuw oordeel van scripts\180), hooguit $MaxHerhaalVragen keer. Alleen 'bewezen' met het nieuwe stempel laat de run door; alles anders laat de pauze doorlopen.
        if ($vHerhaalAantal -lt $MaxHerhaalVragen -and (((Get-Date) - $vHerhaalLaatst).TotalMinutes -ge $HerhaalVraagNaMin)) {
            $vHerhaalAantal++; $vHerhaalLaatst = Get-Date
            $vSinds2 = (Get-Date).ToString('yyyyMMddHHmmss')
            $Script:VerificatieSinds = $vSinds2; $Script:VerificatieStatus = 'wacht'; $Script:LaatsteStatusTijd = $null
            Log "[VERIFICATIE] herhaalvraag $vHerhaalAantal van maximaal ${MaxHerhaalVragen}: de server beoordeelt dit toestel opnieuw..." -Color Cyan
            try { Send-ServerStatus -Fase "WACHT OP VOLLEDIGHEIDSCONTROLE (server, herhaalvraag $vHerhaalAantal)" } catch {}
            $vAnt = $null; $vEind3 = (Get-Date).AddSeconds($HerhaalWachtSec)
            while ((Get-Date) -lt $vEind3 -and -not $vAnt) {
                Start-Sleep 5
                try { Update-Heartbeat } catch {}
                if ((Test-Path $vVrijServer) -or (Test-Path $vVrijLokaal)) { break }
                $vAnt = Get-VerificatieUitkomst -Pad $vUitPad -Sinds $vSinds2
            }
            $Script:VerificatieStatus = 'stop'; $Script:LaatsteStatusTijd = $null
            $vUitTxt = if ($vAnt) { "$($vAnt['uitkomst']): $($vAnt['tekst'])" } else { 'geen antwoord binnen de wachttijd' }
            & $vBewijs @("[verificatie] $(& $vNu) herhaalvraag ${vHerhaalAantal}: $vUitTxt")
            if ($vUitTxt -eq $vLaatsteTxt) { $vGelijk++ } else { $vGelijk = 1; $vLaatsteTxt = $vUitTxt }
            if ($vGelijk -ge 2 -and $vHerhaalAantal -lt $MaxHerhaalVragen) {
                Log "[VERIFICATIE] de server geeft $vGelijk keer exact dezelfde reden; nog eens vragen heeft geen zin zolang er aan de server-kant niets verandert. Geen herhaalvragen meer: wachten op een engineer of de tijdsgrens." -Color Yellow
                & $vBewijs @("[verificatie] $(& $vNu) herhaalvragen gestopt: $vGelijk keer hetzelfde antwoord")
                $vHerhaalAantal = $MaxHerhaalVragen
            }
            if ($vAnt -and $vAnt['uitkomst'] -eq 'bewezen') {
                $vAfloop = "alsnog bewezen na herhaalvraag $vHerhaalAantal"
                Log "[VERIFICATIE] de server meldt nu 'bewezen' ($vUitTxt) - de pauze is niet meer nodig." -Color Green
                break
            }
            if (-not ((Test-Path $vVrijServer) -or (Test-Path $vVrijLokaal))) {
                Log "[VERIFICATIE] herhaalvraag ${vHerhaalAantal}: nog niet bewezen ($vUitTxt)." -Color Yellow
                try { Send-ServerStatus -Fase "WACHT OP ENGINEER - controle vereist (zie laptop)" } catch {}
            }
        }
        # v4.6 (12 okt 2026, Roderick: 'verleng maar aub'; de 30 minuten stonden vast in het draaiende script en liepen af tijdens de handmatige ronde): de server kan de stop verlengen met status\verleng\<serie>.txt (aantal minuten op de eerste regel; het bestand wordt na lezen weggehaald; samen maximaal 120 min)
        try {
            if (Test-Path -LiteralPath $vVerlengPad -ErrorAction SilentlyContinue) {
                $vv = 0.0; $vvTxt = "$(Get-Content -LiteralPath $vVerlengPad -TotalCount 1 -Encoding UTF8 -ErrorAction SilentlyContinue)" -replace ',', '.' -replace '[^\d.]', ''
                [void][double]::TryParse($vvTxt, [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$vv)
                try { [IO.File]::Delete($vVerlengPad) } catch {}
                if ($vv -gt 0 -and $vVerlengTotaal -lt 120) {
                    $plus = [math]::Min($vv, 120 - $vVerlengTotaal); $vEind2 = $vEind2.AddMinutes($plus); $vVerlengTotaal += $plus
                    Log "[VERIFICATIE] verlengd met $plus min door de server (totaal $vVerlengTotaal van maximaal 120 min); de stop duurt nu tot $($vEind2.ToString('HH:mm'))." -Color Cyan
                    & $vBewijs @("[verificatie] $(& $vNu) stop verlengd met $plus min door de server (totaal $vVerlengTotaal)")
                } elseif ($vv -gt 0) { Log "[VERIFICATIE] verlengen gevraagd maar het maximum van 120 min is bereikt." -Color Yellow }
            }
        } catch {}
        if (((Get-Date) - $vNood).TotalSeconds -ge 30) { $vNood = Get-Date; if (Test-NoodStop) { Write-Host ""; Invoke-NoodStop } }
        if (-not $vScanGelukt -and $vScans -lt 2 -and ((-not $vLaatsteScan) -or (((Get-Date) - $vLaatsteScan).TotalMinutes -ge $TweedeScanNaMin)) -and (Test-InternetConnectivity)) {
            $vScans++; $vLaatsteScan = Get-Date
            Log "[VERIFICATIE] internet gevonden: Microsoft Update wordt doorzocht (alleen lezen, max 4 min)..." -Color Cyan
            $vWu = Get-WuOnlineAanbod -TimeoutSec 240
            $vRegels = @()
            if ($vWu.Status -eq 'ok') {
                if (@($vWu.Regels | Where-Object { "$_" -match '^FOUT:' }).Count -eq 0) { $vScanGelukt = $true }
                $vRegels += "[verificatie] $(& $vNu) Windows Update ONLINE biedt nog aan: $(@($vWu.Regels).Count) update(s) (alleen gezocht, niets geinstalleerd)"
                foreach ($u in @($vWu.Regels)) { $vRegels += ("[verificatie]   WU: " + $u) }
                $vGatOk = Write-WuGaten -StatusDir $vDir -Sleutel (Get-ModelSleutel) -Serie $vSerie -Model ("$((Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue).Model)") -Bron 'verificatiestop' -Regels @($vWu.Regels)
                $vGatTxt = if ($vGatOk) { 'weggeschreven' } else { 'NIET weggeschreven (zoeken mislukt of geen server)' }
                $vRegels += "[verificatie] $(& $vNu) wu-gaten voor dit model: $vGatTxt"
            } elseif ($vWu.Status -eq 'timeout') {
                $vRegels += "[verificatie] $(& $vNu) Windows Update ONLINE: zoeken duurde > 240 s, afgebroken"
            } else {
                $vRegels += "[verificatie] $(& $vNu) Windows Update ONLINE: zoeken mislukt ($(@($vWu.Regels) -join ' '))"
            }
            foreach ($r in $vRegels) { Log ("  " + $r) -Color Gray }
            & $vBewijs $vRegels
        }
    }
    try { if (Test-Path $vVrijLokaal) { [IO.File]::Delete($vVrijLokaal) } } catch {}
    Log "[VERIFICATIE] pauze voorbij ($vAfloop) - Sysprep gaat door. Het dashboard toont 'klaar met voorbehoud' zolang de server geen 'bewezen' meldt." -Color Yellow
    & $vBewijs @("[verificatie] $(& $vNu) pauze voorbij: $vAfloop (scans online: $vScans)")
    $Script:VerificatieStatus = 'afgerond'
    $Script:LaatsteStatusTijd = $null
    try { Send-ServerStatus -Fase "Verificatiestop afgerond ($vAfloop) - door naar Sysprep" } catch {}
}

function Get-ModelSleutel {
    # v3.300: de modelsleutel zoals de server die gebruikt (Win32_ComputerSystem.Model zonder spaties/vreemde tekens, bv. 21KH, SurfaceLaptop4). Eenmalig bepaald; ook gemeld in de status (modelsleutel=).
    if ($Script:ModelSleutelCache) { return $Script:ModelSleutelCache }
    try { $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop; $k = ("$($cs.Model)" -replace '\s', '' -replace '[^A-Za-z0-9_-]', ''); if ($k) { $Script:ModelSleutelCache = $k }; return $k } catch { return '' }
}

function Update-WuVerzoek {
    # v3.300 (10 okt 2026): het verzoek <status>\wudrivers\<model>.txt werd maar EEN keer geschreven; latere uitbreidingen van wat we vragen (v3.295: Extension-/software-ID's) bereikten bekende modellen daardoor nooit (21KH: verzoek van 9 okt 02:13). Nu: ontbreken er hardware-ID's in het bestaande verzoek, dan wordt het verzoek BIJGEWERKT (vereniging oud + nieuw, nooit iets weghalen). Geeft terug: nieuw | bijgewerkt:<aantal nieuwe> | ongewijzigd | fout
    param([string]$Pad, [string[]]$Hwids, [string]$Serie, [string]$Fabrikant, [string]$Model, [string]$Sleutel)
    try {
        $oud = @()
        $bestond = Test-Path $Pad
        if ($bestond) { foreach ($ln in @(Get-Content $Pad -Encoding UTF8 -ErrorAction Stop)) { if ("$ln" -match '^\s*hwids\s*=\s*(.*)$') { $oud = @($Matches[1] -split ';' | Where-Object { $_ }) } } }
        $nieuw = @($Hwids | Where-Object { $_ -and ($oud -notcontains $_) })
        if ($bestond -and $nieuw.Count -eq 0) { return 'ongewijzigd' }
        $alle = New-Object System.Collections.Generic.SortedSet[string]
        foreach ($x in $oud) { [void]$alle.Add($x) }
        foreach ($x in $Hwids) { if ($x) { [void]$alle.Add($x) } }
        $inhoud = @("aangevraagd = $(Get-Date -Format 'yyyy-MM-dd HH:mm')", "serienummer = $Serie", "fabrikant = $Fabrikant", "model = $Model", "sleutel = $Sleutel", "hwids = $($alle -join ';')")
        Set-Content -Path $Pad -Value $inhoud -Encoding UTF8 -ErrorAction Stop
        if ($bestond) { return "bijgewerkt:$($nieuw.Count)" } else { return 'nieuw' }
    } catch { return 'fout' }
}

function Write-WuGaten {
    # v3.300: legt vast wat Microsoft Update ONLINE nog aanbiedt voor dit MODEL (<status>\wu-gaten\<modelsleutel>.txt). De server (scripts\180) telt 'bewezen' pas als er een recente vergelijking is met 0 openstaande updates; zonder vergelijking staat er letterlijk 'niet bewezen'. Een mislukte zoekopdracht (regel begint met FOUT:) is GEEN bewijs en wordt niet weggeschreven. Geeft terug: $true/$false
    param([string]$StatusDir, [string]$Sleutel, [string]$Serie, [string]$Model, [string]$Bron, [string[]]$Regels)
    try {
        if (-not $StatusDir -or -not $Sleutel) { return $false }
        $schoon = @($Regels | Where-Object { "$_".Trim() })
        if (@($schoon | Where-Object { "$_" -match '^FOUT:' }).Count -gt 0) { return $false }
        $map = Join-Path $StatusDir 'wu-gaten'
        if (-not (Test-Path $map)) { New-Item -ItemType Directory -Path $map -Force | Out-Null }
        $inhoud = @("gecontroleerd = $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')", "serienummer = $Serie", "sleutel = $Sleutel", "model = $Model", "bron = $Bron", "openstaand = $($schoon.Count)", "--- openstaand") + $schoon
        Set-Content -Path (Join-Path $map "$Sleutel.txt") -Value $inhoud -Encoding UTF8 -ErrorAction Stop
        return $true
    } catch { return $false }
}

function Get-ExtraUpdateInfo {
    # v4.2: leest <cache>\extra-updates\<KB>\latest.txt (geschreven door scripts\186 / Build-ExtraUpdates.ps1): versie + de bestanden met processorsoort en SHA-1. Geeft $null als er niets (bruikbaars) staat.
    param([string]$Root, [string]$Kb)
    try {
        $map = Join-Path $Root "extra-updates\$Kb"; $lp = Join-Path $map 'latest.txt'
        if (-not (Test-Path $lp)) { return $null }
        $versie = ''; $bestanden = @()
        foreach ($l in @(Get-Content $lp -Encoding UTF8 -ErrorAction Stop)) {
            if ("$l" -match '^\s*versie\s*=\s*(.+)$') { $versie = $Matches[1].Trim() }
            elseif ("$l" -match '^\s*bestand\s*=\s*(.+?)\s*\|\s*(\S+)\s*\|\s*sha1\s+([0-9a-fA-F]{40})') { $bestanden += [pscustomobject]@{ Rel = $Matches[1].Trim(); Arch = $Matches[2].Trim(); Sha1 = $Matches[3].ToLower(); Pad = (Join-Path $map $Matches[1].Trim()) } }
        }
        if (-not $versie -or $bestanden.Count -eq 0) { return $null }
        return [pscustomobject]@{ Kb = $Kb; Versie = $versie; Bestanden = $bestanden; Map = $map }
    } catch { return $null }
}

function Test-ExtraBestandVeilig {
    # v4.2: een bestand uit de cache wordt ALLEEN gestart als de SHA-1 gelijk is aan latest.txt EN de Authenticode-handtekening geldig en van Microsoft is. Geeft '' bij OK, anders de reden.
    param($Bestand)
    try {
        if (-not (Test-Path $Bestand.Pad)) { return 'bestand ontbreekt' }
        $sha = (Get-FileHash $Bestand.Pad -Algorithm SHA1 -ErrorAction Stop).Hash.ToLower()
        if ($sha -ne $Bestand.Sha1) { return "SHA-1 klopt niet (cache $sha, latest.txt $($Bestand.Sha1))" }
        $sig = Get-AuthenticodeSignature $Bestand.Pad
        if ($sig.Status -ne 'Valid') { return "handtekening niet geldig ($($sig.Status))" }
        if ("$($sig.SignerCertificate.Subject)" -notmatch 'Microsoft') { return "ondertekenaar is niet Microsoft ($($sig.SignerCertificate.Subject))" }
        return ''
    } catch { return "controle mislukt: $($_.Exception.Message)" }
}

function Copy-ExtraNaarLokaal {
    # v4.4: kopieert een bestand uit de cache naar een lokale map (robocopy, nooit Copy-Item) zodat precies DIE bytes gecontroleerd (SHA-1 + handtekening) en gestart worden, en er geen netwerkpad-/zone-vraag komt. Geeft een kopie van het bestandsobject met het lokale Pad, of $null.
    param($Bestand, [string]$Doel = '')
    try {
        if (-not $Doel) { $Doel = Join-Path 'C:\EspritICT' 'extra-updates' }
        if (-not (Test-Path $Doel)) { New-Item -ItemType Directory -Path $Doel -Force | Out-Null }
        $naam = Split-Path -Leaf $Bestand.Pad
        & robocopy (Split-Path -Parent $Bestand.Pad) $Doel $naam /R:2 /W:2 /NFL /NDL /NJH /NJS /NP | Out-Null
        $lok = Join-Path $Doel $naam
        if (-not (Test-Path $lok)) { return $null }
        try { Unblock-File -Path $lok -ErrorAction SilentlyContinue } catch {}
        return [pscustomobject]@{ Rel = $Bestand.Rel; Arch = $Bestand.Arch; Sha1 = $Bestand.Sha1; Pad = $lok }
    } catch { return $null }
}
function Start-ExtraProces {
    # v4.2: start een bestand uit de cache en wacht BEGRENSD (nooit eindeloos) met hartslag; geeft @{ Exit; Timeout; Seconden }
    param([string]$Pad, [string]$Argumenten = '', [int]$MaxMinuten = 20)
    $start = Get-Date
    # v4.4: CreateProcess (UseShellExecute=false) i.p.v. Start-Process (ShellExecute): ShellExecute toont bij een bestand van een netwerkstation/zone de vraag 'wilt u dit bestand uitvoeren?' en wacht dan EINDELOOS op een klik (Lenovo PW0FC5BB, 12 okt 15:20: 34 min stil, 2 klikken nodig)
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $Pad; $psi.Arguments = "$Argumenten"; $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
    try { $psi.WorkingDirectory = (Split-Path -Parent $Pad) } catch {}
    $p = [System.Diagnostics.Process]::Start($psi)
    $null = $p.Handle
    $eind = $start.AddMinutes($MaxMinuten)
    while (-not $p.HasExited -and (Get-Date) -lt $eind) { Start-Sleep -Seconds 5; try { Update-Heartbeat } catch {} }
    if (-not $p.HasExited) { try { $p.Kill() } catch {}; return @{ Exit = $null; Timeout = $true; Seconden = [int]((Get-Date) - $start).TotalSeconds } }
    return @{ Exit = $p.ExitCode; Timeout = $false; Seconden = [int]((Get-Date) - $start).TotalSeconds }
}

function Get-MrtVersie {
    # v4.2: wat zegt deze laptop zelf over de Malicious Software Removal Tool? (MRT.exe-bestandsversie + de registerwaarde die Microsoft per run bijhoudt: HKLM\SOFTWARE\Microsoft\RemovalTools\MRT\Version, KB891716)
    $bestand = ''; $reg = ''
    try { $f = Join-Path $env:SystemRoot 'System32\MRT.exe'; if (Test-Path $f) { $bestand = "$((Get-Item $f).VersionInfo.FileVersion)" } } catch {}
    try { $rk = Get-Item 'HKLM:\SOFTWARE\Microsoft\RemovalTools\MRT' -ErrorAction SilentlyContinue; if ($rk) { $reg = "$($rk.GetValue('Version'))" } } catch {}   # v4.4: GetValue geeft $null i.p.v. een (in het transcript rood getoonde) fout als de waarde nog niet bestaat
    return @{ Bestand = $bestand; Register = $reg }
}

function Get-SecHealthAppVersie {
    # v4.2: versie van het Windows Security-app-pakket (Microsoft Learn: 'Get-AppPackage Microsoft.SecHealthUI'); leeg als niet te lezen
    try { $pk = @(Get-AppxPackage -AllUsers -Name 'Microsoft.SecHealthUI' -ErrorAction Stop | Sort-Object { [version]$_.Version } -Descending | Select-Object -First 1); if ($pk.Count -gt 0) { return "$($pk[0].Version)" } } catch {}
    return ''
}

function Read-ExtraCfg {
    # v4.2: key=value-bestand naast de installatiebestanden (bv. extra-updates\KB5007651\installatie.txt)
    param([string]$Pad)
    $h = @{}
    try { if (Test-Path $Pad) { foreach ($l in @(Get-Content $Pad -Encoding UTF8 -ErrorAction Stop)) { if ("$l" -match '^\s*([^=#\s][^=]*)=(.*)$') { $h[$Matches[1].Trim().ToLower()] = $Matches[2].Trim() } } } } catch {}
    return $h
}

function Get-DefenderStand {
    # v4.6: wat zegt Defender zelf? Platform = AMProductVersion, definities = AntivirusSignatureVersion (Get-MpComputerStatus). Leeg als Defender niet te lezen is (uit, of een andere antivirus actief).
    try { $s = Get-MpComputerStatus -ErrorAction Stop; return @{ Platform = "$($s.AMProductVersion)"; Definities = "$($s.AntivirusSignatureVersion)" } } catch { return @{ Platform = ''; Definities = '' } }
}

function Test-KbGeinstalleerd {
    # v4.7: staat deze KB al op de laptop? Get-HotFix (Win32_QuickFixEngineering) kent de gewone en .NET-updates; alleen LEZEN
    param([string]$Kb)
    try { if (Get-HotFix -Id $Kb -ErrorAction SilentlyContinue) { return $true } } catch {}
    return $false
}

function Test-CacheMaandupdatesGedekt {
    # v4.13: staan ALLE maandupdates uit de servercache (maandupdates.txt) al op de laptop (bv. ingebakken in het gold-image)? Alleen LEZEN. Zonder servercache, zonder lijst of met 1 ontbrekende KB: Gedekt = $false (dan blijft alles zoals het was).
    $r = @{ Gedekt = $false; Kbs = @(); Reden = '' }
    try {
        $root = $null; try { $root = Resolve-ServerCachePath } catch {}
        if (-not $root) { $r.Reden = 'geen servercache'; return $r }
        $osMap = 'Windows11'; try { if ((Get-CimInstance Win32_OperatingSystem -ErrorAction Stop).Caption -match 'Windows 10') { $osMap = 'Windows10' } } catch {}
        $dv = ''; try { $dv = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -Name 'DisplayVersion' -ErrorAction Stop).DisplayVersion } catch {}
        if (-not $dv) { $r.Reden = 'DisplayVersion onbekend'; return $r }
        $lijst = Join-Path (Get-CacheLayoutRoot -Root $root -Bucket 'WSUS') "windows-updates\$osMap\$dv\maandupdates.txt"
        if (-not (Test-Path -LiteralPath $lijst)) { $r.Reden = 'geen maandupdates.txt in de cache'; return $r }
        $kbs = @(); foreach ($regel in @(Get-Content -LiteralPath $lijst -ErrorAction Stop)) { $d = @("$regel".Trim() -split '\|'); if ($d.Count -ge 2 -and $d[0] -match '^KB\d{7}$') { $kbs += $d[0] } }
        if (-not $kbs.Count) { $r.Reden = 'maandupdates.txt is leeg'; return $r }
        $r.Kbs = $kbs
        $mis = @($kbs | Where-Object { -not (Test-KbGeinstalleerd $_) })
        if ($mis.Count) { $r.Reden = 'nog niet op de laptop: ' + ($mis -join ', '); return $r }
        $r.Gedekt = $true; $r.Reden = 'alle maandupdates uit de cache staan al op de laptop (' + ($kbs -join ', ') + ')'
    } catch { $r.Reden = "niet te bepalen: $($_.Exception.Message)" }
    return $r
}
function Invoke-CacheMaandupdatesFase {
    # v4.7 (13 okt 2026, Patch Tuesday, Roderick: 'perfect succes'): de maandelijkse Windows-update (cumulatief + .NET) komt uit de cache van de server i.p.v. via Windows Update online (die toolset sluit cumulatieve updates daar bewust van uit en een unit is offline).
    # De server (scripts\201) zet de .msu-bestanden in <cache>\WSUS\windows-updates\Windows11\<versie>\ en schrijft maandupdates.txt: een regel per update: KB|doelbestand.msu|voorwaarde.msu|... (de voorwaarde-bestanden staan in dezelfde map nodig voor wusa).
    # Alleen wat in maandupdates.txt staat wordt geprobeerd (nooit alle 4,6 GB-pakketten in de map). Begrensd: per KB maximaal 2 pogingen per run, maximaal 2 herstarts. Daarna volgt het gewone pad (oogstvenster en verificatie).
    # Na een installatie die een herstart nodig heeft: NU herstarten (voor het oogstvenster), zodat de latere online meting de update als geinstalleerd ziet.
    try {
        $root = $null; try { $root = Resolve-ServerCachePath } catch {}
        if (-not $root) { return }
        $osMap = 'Windows11'; try { if ((Get-CimInstance Win32_OperatingSystem -ErrorAction Stop).Caption -match 'Windows 10') { $osMap = 'Windows10' } } catch {}
        $dv = ''; try { $dv = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -Name 'DisplayVersion' -ErrorAction Stop).DisplayVersion } catch {}
        if (-not $dv) { return }
        $map = Join-Path (Get-CacheLayoutRoot -Root $root -Bucket 'WSUS') "windows-updates\$osMap\$dv"
        $lijst = Join-Path $map 'maandupdates.txt'
        if (-not (Test-Path -LiteralPath $lijst)) { return }
        $herstartNodig = $false; $gedaan = 0
        foreach ($regel in @(Get-Content -LiteralPath $lijst -ErrorAction Stop)) {
            $d = @("$regel".Trim() -split '\|'); if ($d.Count -lt 2 -or $d[0] -notmatch '^KB\d{7}$') { continue }
            $kb = $d[0]
            if (Test-KbGeinstalleerd $kb) { Log "[maandupdate] $kb staat al op de laptop - overgeslagen" -Color Green; continue }
            $pk = "MaandUpdatePogingen_$kb"; $nPog = 0; try { if ($State.PSObject.Properties[$pk]) { $nPog = [int]$State.$pk } } catch {}
            if ($nPog -ge 2) { Log "[maandupdate] ${kb}: al $nPog pogingen in deze run - niet opnieuw (een mens moet kijken)" -Color Yellow; continue }
            $State | Add-Member -NotePropertyName $pk -NotePropertyValue ($nPog + 1) -Force; Save-State $State
            $doelBron = Join-Path $map $d[1]
            if (-not (Test-Path -LiteralPath $doelBron)) { Log "[maandupdate] ${kb}: bestand $($d[1]) staat niet in de cache ($map)" -Color Yellow; continue }
            Log "[maandupdate] $kb wordt geinstalleerd vanuit de cache van de server (poging $($nPog + 1) van 2): $($d[1])" -Color Cyan
            # voorwaarde-bestanden (zelfde map nodig voor wusa) eerst lokaal, dan het doelbestand
            foreach ($v in @($d | Select-Object -Skip 2)) { if ($v -and $v -notmatch '^ubr=') { $vb = Join-Path $map $v; if (Test-Path -LiteralPath $vb) { [void](Copy-MsuNaarLokaal -Bron $vb -Label "voorwaarde $v") } } }
            $lokaal = Copy-MsuNaarLokaal -Bron $doelBron -Label $kb
            $msuVoorWusa = if ($lokaal) { $lokaal } else { $doelBron }
            $t0 = Get-Date
            $proc = Start-Process 'wusa.exe' -ArgumentList "`"$msuVoorWusa`" /quiet /norestart" -PassThru -ErrorAction Stop
            Wait-ProcessMetHartslag -Proces $proc -Label "wusa installeert $kb"
            $rc = $proc.ExitCode
            Log "[maandupdate] wusa-exitcode voor $kb : $rc (hex 0x$('{0:X8}' -f [BitConverter]::ToUInt32([BitConverter]::GetBytes([int]$rc),0))), duur $([int]((Get-Date) - $t0).TotalSeconds) s" -Color Gray
            $ok = $false
            if ($rc -eq 0 -or $rc -eq 3010) { $ok = $true; if ($rc -eq 3010) { $herstartNodig = $true } }
            elseif ($rc -eq 2359302) { Log "[maandupdate] $kb bleek al geinstalleerd (WU_S_ALREADY_INSTALLED)" -Color Green; $ok = $true }
            else {
                # terugval: DISM (zelfde aanpak als bij het enablement-package)
                try {
                    Log "[maandupdate] wusa gaf exitcode $rc voor $kb - terugvallen op DISM /Add-Package..." -Color Yellow
                    $dp = Start-Process 'dism.exe' -ArgumentList '/Online', '/Add-Package', "/PackagePath:`"$msuVoorWusa`"", '/NoRestart' -PassThru -WindowStyle Hidden
                    Wait-ProcessMetHartslag -Proces $dp -Label "DISM installeert $kb"
                    Log "[maandupdate] DISM-exitcode voor $kb : $($dp.ExitCode)" -Color Gray
                    if ($dp.ExitCode -eq 0 -or $dp.ExitCode -eq 3010) { $ok = $true; if ($dp.ExitCode -eq 3010) { $herstartNodig = $true } }
                } catch { Log "[maandupdate] DISM starten mislukt voor $kb : $_" -Color Yellow }
            }
            Remove-MsuLokaal -Pad $lokaal
            if ($ok) { $gedaan++; Log "[maandupdate] $kb geinstalleerd vanuit de cache (BEWIJS volgt na de herstart: Get-HotFix en de online meting)" -Color Green }
            else { Log "[maandupdate] $kb NIET gelukt via de cache (exitcode $rc) - het gewone pad (oogstvenster en verificatie) toont het straks als open" -Color Yellow }
        }
        if ($gedaan -gt 0) { try { if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') { $herstartNodig = $true } } catch {} }
        if ($herstartNodig) {
            $nH = 0; try { if ($State.PSObject.Properties['MaandUpdateHerstarts']) { $nH = [int]$State.MaandUpdateHerstarts } } catch {}
            if ($nH -ge 2) { Log "[maandupdate] herstart nodig maar al $nH keer herstart voor maandupdates - niet nog eens (begrensd)" -Color Yellow; return }
            $State | Add-Member -NotePropertyName MaandUpdateHerstarts -NotePropertyValue ($nH + 1) -Force
            Log "[maandupdate] herstart nodig om de maandupdate(s) af te ronden - nu herstarten (voor het oogstvenster), daarna gaat het script vanzelf verder." -Color Cyan
            try { Send-ServerStatus -Fase "HERSTART voor maandupdate (uit de cache)" } catch {}
            try { $sdF = Get-StatusDirVroeg; if ($sdF) { Copy-ConsoleLogNaarServer -StatusDir $sdF -Serie $Serial -Forceer; Push-EvtxTussentijds -StatusDir $sdF -Serie $Serial -Forceer } } catch {}
            Set-AuditModePersistent
            Save-State $State; Start-Sleep 3; shutdown /r /t 10 /f; exit
        }
    } catch { Log "[maandupdate] fase mislukt (niet fataal): $_" -Color Yellow }
}
function Invoke-ExtraUpdatesPhase {
    # v4.2 (10-12 okt 2026, Roderick: 'dat alles echt wordt geinstalleerd'): bewijs op Lenovo 21KH: MSRT (KB890830) en het Windows Security platform (KB5007651) stonden wel in de cache (scripts\186) maar werden NIET geinstalleerd, waardoor Windows Update ze na elke schone installatie opnieuw aanbood.
    # Alles uit <cache>\extra-updates; elk bestand alleen na SHA-1- en handtekeningcontrole; begrensde wachttijd; elke stap met voor/na-bewijs in het log en het bewijsrapport. Mislukt iets: loggen en doorgaan (nooit de run laten vallen).
    $Script:ExtraUpdatesRegels = @()
    function Voeg-Extra([string]$tekst, [string]$kleur = 'Gray') { Log "[extra] $tekst" -Color $kleur; $Script:ExtraUpdatesRegels += "[bewijs] extra-update: $tekst" }
    $root = $null; try { $root = Resolve-ServerCachePath } catch {}
    if (-not $root) { Voeg-Extra "overgeslagen: geen cache (server of stick) gevonden"; return }
    if (-not (Test-Path (Join-Path $root 'extra-updates'))) { Voeg-Extra "overgeslagen: geen map extra-updates in de cache ($root)"; return }

    # --- MSRT (KB890830): stil met /q (Microsoft KB891716); returncodes volgens dezelfde bron ---
    try {
        $mi = Get-ExtraUpdateInfo $root 'KB890830'
        if (-not $mi) { Voeg-Extra "MSRT (KB890830): niet in de cache (extra-updates\KB890830\latest.txt ontbreekt)" 'Yellow' }
        else {
            $f = @($mi.Bestanden | Where-Object { $_.Arch -eq 'x64' }) | Select-Object -First 1
            $pk = [regex]::Match($mi.Versie, '^\d+\.\d+').Value
            $voor = Get-MrtVersie; $inst = [regex]::Match($voor.Bestand, '^\d+\.\d+').Value
            if (-not $f) { Voeg-Extra "MSRT: geen x64-bestand in de cache" 'Yellow' }
            elseif ($inst -and $pk -and ([version]$inst -ge [version]$pk)) { Voeg-Extra "MSRT: staat al op $($voor.Bestand) (pakket $($mi.Versie)) - overgeslagen" 'Green' }
            else {
                $fl = Copy-ExtraNaarLokaal $f; $veilig = $(if ($fl) { Test-ExtraBestandVeilig $fl } else { 'lokaal kopieren mislukt' }); if (-not $veilig) { $f = $fl }
                if ($veilig) { Voeg-Extra "MSRT: NIET gestart - $veilig" 'Red' }
                else {
                    Voeg-Extra "MSRT $($mi.Versie) wordt gestart (stil, /q; voor: MRT.exe '$($voor.Bestand)', register '$($voor.Register)')..." 'Cyan'
                    $r = Start-ExtraProces -Pad $f.Pad -Argumenten '/q' -MaxMinuten 25
                    $na = Get-MrtVersie
                    $uitleg = switch ($r.Exit) { 0 { 'geen infectie gevonden' } 1 { 'fout: besturingssysteem' } 2 { 'fout: geen beheerder' } 3 { 'fout: besturingssysteem niet ondersteund' } 4 { 'fout: scanner kon niet starten' } 6 { 'INFECTIE gevonden, geen fouten' } 7 { 'INFECTIE gevonden, met fouten' } default { "code $($r.Exit)" } }
                    $verandering = ($na.Register -and $na.Register -ne $voor.Register) -or ($na.Bestand -and $na.Bestand -ne $voor.Bestand)
                    $tekst = "MSRT $($mi.Versie): $(if ($r.Timeout) { "AFGEBROKEN na $($r.Seconden) s (tijdslimiet)" } else { "klaar na $($r.Seconden) s, exitcode $($r.Exit) ($uitleg)" }); na: MRT.exe '$($na.Bestand)', register '$($na.Register)'; $(if ($verandering) { 'versie/register VERANDERD = bewezen dat hij draaide' } else { 'GEEN zichtbare verandering - NIET bewezen' })"
                    Voeg-Extra $tekst $(if ($r.Timeout -or ($r.Exit -ne 0) -or -not $verandering) { 'Yellow' } else { 'Green' })
                    if ($r.Exit -ge 6 -and $r.Exit -le 13) { Log "[LET OP] [extra] MSRT meldt een INFECTIE (exitcode $($r.Exit)) - dit toestel moet door een mens bekeken worden." -Color Red }
                }
            }
        }
    } catch { Voeg-Extra "MSRT: fout (niet fataal): $($_.Exception.Message)" 'Yellow' }

    # --- Windows Security platform (KB5007651): geen stille schakelaar gedocumenteerd. v4.3: is het platform OUDER dan het pakket, dan doet het script zelf een begrensde PROEFINSTALLATIE (zonder argumenten, 15 min max, alleen na SHA-1 + Microsoft-handtekening) en MEET het resultaat (buildnummer van de app voor/na). 'bewezen = ja' in installatie.txt voegt alleen argumenten toe; 'bewezen = nee' blokkeert (mens). ---
    try {
        $si = Get-ExtraUpdateInfo $root 'KB5007651'
        if (-not $si) { Voeg-Extra "Security platform (KB5007651): niet in de cache" 'Yellow' }
        else {
            $f = @($si.Bestanden | Where-Object { $_.Arch -eq 'x64' }) | Select-Object -First 1
            $cfg = Read-ExtraCfg (Join-Path $si.Map 'installatie.txt')
            $nu = Get-SecHealthAppVersie
            # gemeten 12 okt 2026 op twee laptops: pakket 10.0.29628.1000 = app-versie 1000.29628.1000.0 -> het BUILDNUMMER (29628) staat in het pakket op plek 3 en in de app op plek 2
            $pkB = 0; if ($si.Versie -match '^10\.0\.(\d+)\.\d+$') { $pkB = [int]$Matches[1] }
            $nuB = 0; if ("$nu" -match '^\d+\.(\d+)\.\d+\.\d+$') { $nuB = [int]$Matches[1] }
            if (-not $f) { Voeg-Extra "Security platform: geen x64-bestand in de cache" 'Yellow' }
            elseif (-not $pkB) { Voeg-Extra "Security platform: versie in latest.txt niet te lezen ('$($si.Versie)') - NIET gestart" 'Yellow' }
            elseif ($cfg['bewezen'] -eq 'nee') { Voeg-Extra "Security platform $($si.Versie): NIET gestart - geblokkeerd door een mens ('bewezen = nee' in installatie.txt); app-versie nu: '$nu'" 'Yellow' }
            elseif (-not $nuB) { Voeg-Extra "Security platform $($si.Versie): NIET gestart - de app-versie is niet te lezen ('$nu'); zonder meting vooraf is er geen bewijs achteraf" 'Yellow' }
            elseif ($nuB -ge $pkB) { Voeg-Extra "Security platform: app-versie $nu heeft buildnummer $nuB, pakket $pkB - al actueel, overgeslagen" 'Green' }
            else {
                $fl = Copy-ExtraNaarLokaal $f; $veilig = $(if ($fl) { Test-ExtraBestandVeilig $fl } else { 'lokaal kopieren mislukt' }); if (-not $veilig) { $f = $fl }
                if ($veilig) { Voeg-Extra "Security platform: NIET gestart - $veilig" 'Red' }
                else {
                    $proef = ($cfg['bewezen'] -ne 'ja')
                    $arg = if ($proef) { '' } else { "$($cfg['argumenten'])" }
                    Voeg-Extra "Security platform $($si.Versie) wordt gestart ($(if ($proef) { 'PROEFINSTALLATIE zonder argumenten - werkwijze nog niet eerder bewezen' } else { "bewezen werkwijze, argumenten '$arg'" }); app-versie voor: '$nu', buildnummer $nuB < $pkB)..." 'Cyan'
                    $r = Start-ExtraProces -Pad $f.Pad -Argumenten $arg -MaxMinuten 15
                    # v4.4: de app-versie kan na een installatie vertraagd verschijnen (Appx-registratie): tot 2 min elke 10 s meten i.p.v. een enkele meting na 20 s
                    $na = ''; for ($poging = 0; $poging -lt 12; $poging++) { Start-Sleep -Seconds 10; $na = Get-SecHealthAppVersie; if ("$na" -match '^\d+\.(\d+)\.\d+\.\d+$' -and [int]$Matches[1] -ge $pkB) { break } }
                    $naB = 0; if ("$na" -match '^\d+\.(\d+)\.\d+\.\d+$') { $naB = [int]$Matches[1] }
                    $ok = ($naB -ge $pkB)
                    $txt = "Security platform: $(if ($r.Timeout) { "AFGEBROKEN na $($r.Seconden) s" } else { "klaar na $($r.Seconden) s, exitcode $($r.Exit)" }); app-versie na: '$na' (buildnummer $naB, verwacht >= $pkB): $(if ($ok) { 'BEWEZEN (gemeten verandering)' } else { 'NIET bewezen - versie is niet veranderd' })"
                    Voeg-Extra $txt $(if ($ok) { 'Green' } else { 'Yellow' })
                    if ($proef) {
                        # de uitkomst van de proef bewaren (alleen toevoegen) zodat de engineer ziet of deze werkwijze op dit model werkt
                        try { $sd = Get-StatusDirVroeg; if ($sd) { $ed = Join-Path $sd 'extra-test'; if (-not (Test-Path $ed)) { New-Item -ItemType Directory -Path $ed -Force | Out-Null }; Set-Content -Path (Join-Path $ed ("{0}_{1}_proef.txt" -f $Serial, (Get-Date -Format 'yyyyMMdd-HHmm'))) -Value @("serie = $Serial", "pakket = $($si.Versie)", "argumenten = (geen)", "voor = $nu", $txt) -Encoding UTF8 } } catch {}
                    }
                }
            }
        }
    } catch { Voeg-Extra "Security platform: fout (niet fataal): $($_.Exception.Message)" 'Yellow' }

    # --- v4.6 (12 okt 2026, norm 99,9%): Microsoft Defender-platform (KB4052623) en -definities (KB2267602) uit de cache. Bewijs: na de schone Lenovo-run bood Microsoft Update (21:34) nog beide aan (platform 4.18.26080.4, definities 1.459.688.0); de server haalt ze nu elk uur op (scripts\186). Elke stap wordt GEMETEN voor en na (Get-MpComputerStatus); geen verandering = 'NIET bewezen', nooit schijn-succes. De bestanden worden lokaal gekopieerd, gecontroleerd en met CreateProcess gestart (geen ShellExecute-vraag).
    try {
        $dst0 = Get-DefenderStand
        if (-not $dst0.Platform) { Voeg-Extra 'Defender: de stand is niet te lezen (Defender staat uit of een andere antivirus is actief): overgeslagen' 'Yellow' }
        else {
            foreach ($df in @(@{ Kb = 'KB4052623'; Naam = 'Defender-platform'; Soort = 'platform'; MaxMin = 10 }, @{ Kb = 'KB2267602'; Naam = 'Defender-definities'; Soort = 'definities'; MaxMin = 15 })) {
                try {
                    $di = Get-ExtraUpdateInfo $root $df.Kb
                    if (-not $di) { Voeg-Extra "$($df.Naam) ($($df.Kb)): niet in de cache" 'Yellow'; continue }
                    $dfb = @($di.Bestanden | Where-Object { $_.Arch -eq 'x64' }) | Select-Object -First 1
                    if (-not $dfb) { Voeg-Extra "$($df.Naam): geen x64-bestand in de cache" 'Yellow'; continue }
                    $stNu = Get-DefenderStand
                    $huidig = if ($df.Soort -eq 'platform') { $stNu.Platform } else { $stNu.Definities }
                    $vh = $null; $vp = $null; try { $vh = [version]$huidig; $vp = [version]$di.Versie } catch {}
                    if (-not $vh -or -not $vp) { Voeg-Extra "$($df.Naam): versies niet te vergelijken (laptop '$huidig', cache '$($di.Versie)')" 'Yellow'; continue }
                    if ($vh -ge $vp) { Voeg-Extra "$($df.Naam): staat al op $huidig (cache $($di.Versie)) - overgeslagen" 'Green'; if ($df.Soort -eq 'definities') { $Script:DefenderDefTijd = Get-Date }; continue }
                    $dfl = Copy-ExtraNaarLokaal $dfb
                    $dfv = $(if ($dfl) { Test-ExtraBestandVeilig $dfl } else { 'lokaal kopieren mislukt' })
                    if ($dfv) { Voeg-Extra "$($df.Naam): NIET gestart - $dfv" 'Red'; continue }
                    Voeg-Extra "$($df.Naam) $($di.Versie) wordt gestart (voor: $huidig; maximaal $($df.MaxMin) min)..." 'Cyan'
                    $rd = Start-ExtraProces -Pad $dfl.Pad -Argumenten '' -MaxMinuten $df.MaxMin
                    $na = ''; $okD = $false
                    for ($q = 0; $q -lt 12 -and -not $okD; $q++) { Start-Sleep -Seconds 10; $sn = Get-DefenderStand; $na = if ($df.Soort -eq 'platform') { $sn.Platform } else { $sn.Definities }; $vn = $null; try { $vn = [version]$na } catch {}; if ($vn -and $vn -ge $vp) { $okD = $true } }
                    $uitleg1 = "$(if ($rd.Timeout) { "AFGEBROKEN na $($rd.Seconden) s" } else { "klaar na $($rd.Seconden) s, exitcode $($rd.Exit)" }); na: '$na' (verwacht >= $($di.Versie))"
                    if (-not $okD -and $df.Soort -eq 'definities') {
                        # tweede, apart gemeten poging met Defender's eigen opdracht (bron: forumberichten, niet officieel gedocumenteerd; daarom pas als de eerste poging niets veranderde)
                        $mpc = Join-Path $env:ProgramFiles 'Windows Defender\MpCmdRun.exe'
                        if (Test-Path -LiteralPath $mpc) {
                            Voeg-Extra "$($df.Naam): het bestand zelf veranderde niets ($uitleg1); tweede poging met MpCmdRun -SignatureUpdate -Path" 'Yellow'
                            $r2 = Start-ExtraProces -Pad $mpc -Argumenten ('-SignatureUpdate -Path "' + $dfl.Pad + '"') -MaxMinuten 10
                            for ($q = 0; $q -lt 6 -and -not $okD; $q++) { Start-Sleep -Seconds 10; $sn = Get-DefenderStand; $na = $sn.Definities; $vn = $null; try { $vn = [version]$na } catch {}; if ($vn -and $vn -ge $vp) { $okD = $true } }
                            $uitleg1 = "$uitleg1; MpCmdRun: exitcode $($r2.Exit), na: '$na'"
                        }
                    }
                    Voeg-Extra "$($df.Naam) $($di.Versie): $uitleg1 : $(if ($okD) { 'BEWEZEN (gemeten verandering)' } else { 'NIET bewezen - de versie is niet veranderd' })" $(if ($okD) { 'Green' } else { 'Yellow' })
                    if ($okD -and $df.Soort -eq 'definities') { $Script:DefenderDefTijd = Get-Date }
                } catch { Voeg-Extra "$($df.Naam): fout (niet fataal): $($_.Exception.Message)" 'Yellow' }
            }
            $Script:DefenderStand = Get-DefenderStand
            Voeg-Extra "Defender na afloop: platform '$($Script:DefenderStand.Platform)', definities '$($Script:DefenderStand.Definities)'"
        }
    } catch { Voeg-Extra "Defender: fout (niet fataal): $($_.Exception.Message)" 'Yellow' }
}

function Get-OogstBehoefte {
    # v4.5: moet deze laptop nu een oogstvenster doen? Alleen LEZEN (register en online meting op de server). Nodig als: de server erom vraagt (heroogsten), er driver-gaten zijn die de cache niet dekt, het model nieuw is (nog geen meting), of de online meting ouder dan $MaxDagen dagen is (dan kan de verificatiestop niet 'bewezen' zeggen zonder handmatige Wi-Fi).
    param([string]$StatusDir, [string]$Sleutel, [int]$MaxDagen = 3)
    $r = @{ Nodig = $false; Reden = ''; Gaten = 0 }
    try {
        $reg = Join-Path $StatusDir "wu-gaten\register\$Sleutel.tsv"
        $gat = Join-Path $StatusDir "wu-gaten\$Sleutel.txt"
        $flag = Join-Path $StatusDir "wu-oogst\heroogsten\$Sleutel.txt"
        $n = 0
        if (Test-Path -LiteralPath $reg) { foreach ($l in @(Get-Content -LiteralPath $reg -Encoding UTF8 -ErrorAction Stop)) { $p = "$l" -split "`t"; if ($p.Count -ge 5 -and $p[2] -eq 'driver' -and $p[4] -in @('niet-gevonden', 'open')) { $n++ } } }
        $r.Gaten = $n
        $gecontroleerd = $null
        if (Test-Path -LiteralPath $gat) { foreach ($l in @(Get-Content -LiteralPath $gat -Encoding UTF8 -ErrorAction SilentlyContinue)) { if ("$l" -match '^\s*gecontroleerd\s*=\s*(.+)$') { try { $gecontroleerd = [datetime]::Parse($Matches[1].Trim()) } catch {} } } }
        $vers = ($gecontroleerd -and (((Get-Date) - $gecontroleerd).TotalDays -le $MaxDagen))
        if (Test-Path -LiteralPath $flag) { $r.Nodig = $true; $r.Reden = 'de server vraagt om opnieuw te oogsten'; return $r }
        if ($n -gt 0) { $r.Nodig = $true; $r.Reden = "$n driver-gat(en) die de cache niet dekt"; return $r }
        # v4.6 (norm 99,9%): ook de rest van de laatste online meting telt: elke openstaande update die geen herhaalaanbod is (bewijs in wu-gaten\herhaling) en geen Defender-onderdeel (die komen uit de cache) vraagt om een poging in het oogstvenster
        if ($gecontroleerd -and (Test-Path -LiteralPath $gat)) {
            $herh = @{}; $hpp = Join-Path $StatusDir "wu-gaten\herhaling\$Sleutel.tsv"
            if (Test-Path -LiteralPath $hpp) { foreach ($hl in @(Get-Content -LiteralPath $hpp -Encoding UTF8 -ErrorAction SilentlyContinue)) { $hc = "$hl" -split "`t"; if ($hc.Count -ge 1 -and $hc[0] -match '^[0-9a-fA-F\-]{36}$') { $herh[$hc[0].ToLower()] = $true } } }
            $naL = $false; $rest = 0
            foreach ($l in @(Get-Content -LiteralPath $gat -Encoding UTF8 -ErrorAction SilentlyContinue)) {
                if ($naL -and "$l".Trim()) {
                    $kbm = [regex]::Match("$l", 'KB=(\d+)'); $kbk = if ($kbm.Success) { 'KB' + $kbm.Groups[1].Value } else { '' }
                    $idm = [regex]::Match("$l", 'id=([0-9a-fA-F\-]{36})'); $idk = if ($idm.Success) { $idm.Groups[1].Value.ToLower() } else { '' }
                    if ($kbk -in @('KB4052623', 'KB2267602')) { continue }
                    if ($idk -and $herh.ContainsKey($idk)) { continue }
                    $rest++
                } elseif ("$l" -like '--- openstaand*') { $naL = $true }
            }
            if ($rest -gt 0) { $r.Nodig = $true; $r.Reden = "$rest update(s) stonden na de laatste online meting nog open (geen herhaalaanbod, geen Defender)"; return $r }
        }
        # v4.6h (13 okt 2026, run 5 Lenovo: de verificatiestop wilde een mens omdat de server om 18:23 nog iets nieuws in de cache had gezet, terwijl de unit de oogst oversloeg met 'recente online meting 01:14' van een eerdere run): heeft de server NA de laatste online meting van dit model nog iets nieuws opgehaald (status\server-controle\<model>.txt, laatste-nieuw), dan is die meting verouderd en doet deze unit zelf een nieuwe online meting in het oogstvenster. Daarna staat 'gecontroleerd' later dan het nieuws en is het gedekt.
        $cpN = Join-Path $StatusDir "server-controle\$Sleutel.txt"
        if ($gecontroleerd -and (Test-Path -LiteralPath $cpN)) {
            foreach ($cl in @(Get-Content -LiteralPath $cpN -Encoding UTF8 -ErrorAction SilentlyContinue)) {
                if ("$cl" -match '^\s*laatste-nieuw\s*=\s*(.+)$') {
                    $lnN = $null; try { $lnN = [datetime]::Parse($Matches[1].Trim()) } catch {}
                    if ($lnN -and $lnN -gt $gecontroleerd) { $r.Nodig = $true; $r.Reden = "de server haalde na de laatste online meting ($($gecontroleerd.ToString('yyyy-MM-dd HH:mm'))) nog iets nieuws op ($($lnN.ToString('yyyy-MM-dd HH:mm'))): een nieuwe online meting is nodig"; return $r }
                }
            }
        }        if (-not (Test-Path -LiteralPath $reg) -and -not (Test-Path -LiteralPath $gat)) { $r.Nodig = $true; $r.Reden = 'nieuw model: nog geen online meting'; return $r }
        if (-not $vers) { $r.Nodig = $true; $r.Reden = "de online meting voor dit model ontbreekt of is ouder dan $MaxDagen dagen"; return $r }
        $r.Reden = "geen driver-gaten en een recente online meting ($($gecontroleerd.ToString('yyyy-MM-dd HH:mm')))"
    } catch { $r.Nodig = $false; $r.Reden = "behoefte niet te bepalen: $($_.Exception.Message)" }
    return $r
}

function Test-WuHerstartNodig {
    # v4.6: Windows Update markeert een openstaande herstart in het register; een update die dan opnieuw wordt aangeboden is geen herhaal-lus maar wacht op die herstart
    try { return [bool](Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') } catch { return $false }
}

function Get-OogstPogingen {
    # v4.5: aantal oogstpogingen voor dit model in de laatste $Dagen dagen (regel = tijd<TAB>serie<TAB>uitkomst). Begrenst herhalen: een gat dat de oogst niet kan dichten mag niet elke run opnieuw een online venster openen.
    param([string]$Pad, [int]$Dagen = 7)
    $n = 0
    try { if (Test-Path -LiteralPath $Pad) { foreach ($l in @(Get-Content -LiteralPath $Pad -Encoding UTF8 -ErrorAction Stop)) { $c = "$l" -split "`t"; try { if ($c.Count -ge 3 -and "$($c[2])".Trim() -ne 'gestart') { continue }; if (((Get-Date) - [datetime]::Parse($c[0])).TotalDays -le $Dagen) { $n++ } } catch {} } } } catch {}
    return $n
}

function Get-OogstLaatsteUitkomst {
    # v4.31: de laatste regel van het pogingenbestand met een ECHTE uitkomst (niet 'gestart' en niet 'niet gestart'), als 'uitkomst (tijd)'; leeg als er geen is. Alleen voor de melding: zo staat de reden (bv. geen internet) in het bewijslog.
    param([string]$Pad)
    try { if ($Pad -and (Test-Path -LiteralPath $Pad)) { $laatste = ''; foreach ($l in @(Get-Content -LiteralPath $Pad -Encoding UTF8 -ErrorAction Stop)) { $c = "$l" -split "`t"; if ($c.Count -ge 3) { $u = "$($c[2])".Trim(); if ($u -and $u -ne 'gestart' -and $u -ne 'niet gestart') { $laatste = "$u ($(($c[0] -replace '[^\d\-: ]', '').Trim()))" } } }; return $laatste } } catch {}
    return ''
}

function Get-OogstWifiGegevens {
    # v4.5: Wi-Fi-gegevens in het bestaande formaat van wifi-credentials.txt (SSID, wachtwoord, lege regel, volgend netwerk). Bron 1: C:\Windows\Temp\wifi-credentials.txt (stick-flow), bron 2: <servercache>\wifi-credentials.txt. Geen bestand = geen Wi-Fi (het oogstvenster meldt dat zichtbaar). Wachtwoorden worden nooit gelogd.
    param([string]$CacheRoot = '', [string]$LokaalPad = 'C:\EspritICT\wifi-credentials.txt')
    $uit = New-Object System.Collections.ArrayList
    foreach ($p in @($LokaalPad, $(try { if (Get-Command Get-UsbDriveWithCsv -ErrorAction SilentlyContinue) { $uw = Get-UsbDriveWithCsv; if ($uw) { Join-Path $uw 'wifi-credentials.txt' } } } catch {}), $(if ($CacheRoot) { Join-Path $CacheRoot 'wifi-credentials.txt' }))) {
        try {
            if ($p -and (Test-Path -LiteralPath $p)) {
                $blok = @()
                foreach ($regel in (@(Get-Content -LiteralPath $p -ErrorAction Stop) + @(''))) {
                    if ("$regel".Trim() -eq '') { if ($blok.Count -ge 2) { [void]$uit.Add([pscustomobject]@{ Ssid = "$($blok[0])".Trim(); Sleutel = "$($blok[1])".Trim() }) }; $blok = @() }
                    else { $blok += "$regel" }
                }
            }
        } catch {}
        if ($uit.Count -gt 0) { break }
    }
    return @($uit)
}

function Connect-OogstWifi {
    # v4.5: verbindt met het eerste netwerk dat internet geeft (WPA2-PSK, zoals de bestaande Wifi-terugval). Het profiel-XML bevat het wachtwoord leesbaar en wordt DIRECT na het toevoegen verwijderd. Geeft de SSID terug of '' (dan zijn alle profielen weer verwijderd).
    param($Netwerken, [int]$WachtSec = 60)
    foreach ($n in @($Netwerken)) {
        $ssid = "$($n.Ssid)"; $key = "$($n.Sleutel)"
        if (-not $ssid -or -not $key) { continue }
        $xml = '<?xml version="1.0"?><WLANProfile xmlns="http://www.microsoft.com/networking/WLAN/profile/v1"><name>' + [Security.SecurityElement]::Escape($ssid) + '</name><SSIDConfig><SSID><name>' + [Security.SecurityElement]::Escape($ssid) + '</name></SSID></SSIDConfig><connectionType>ESS</connectionType><connectionMode>auto</connectionMode><MSM><security><authEncryption><authentication>WPA2PSK</authentication><encryption>AES</encryption><useOneX>false</useOneX></authEncryption><sharedKey><keyType>passPhrase</keyType><protected>false</protected><keyMaterial>' + [Security.SecurityElement]::Escape($key) + '</keyMaterial></sharedKey></security></MSM></WLANProfile>'
        $pad = Join-Path 'C:\EspritICT' 'oogst-wifi-profiel.xml'
        try {
            [IO.File]::WriteAllText($pad, $xml, (New-Object System.Text.UTF8Encoding($false)))
            $o1 = (& netsh.exe wlan add profile filename="$pad" user=all 2>&1 | Out-String).Trim(); $Script:OogstWifiSsids = @($Script:OogstWifiSsids) + $ssid
        } finally { try { [void](Remove-GeheimeBestanden -Paden @($pad) -GeenNetUse -Stil) } catch { try { [IO.File]::Delete($pad) } catch {} } }
        $o2 = (& netsh.exe wlan connect name="$ssid" 2>&1 | Out-String).Trim()
        Log "  [oogst] Wi-Fi '$ssid': profiel toegevoegd ($(($o1 -split "`n")[0].Trim())); verbinden ($(($o2 -split "`n")[0].Trim()))" -Color Gray
        for ($ronde = 0; $ronde -lt [math]::Ceiling($WachtSec / 3); $ronde++) { Start-Sleep -Seconds 3; try { Update-Heartbeat } catch {}; if (Test-InternetConnectivity) { return $ssid } }   # aantal rondes i.p.v. klok: begrensd en testbaar
        try { [void](Remove-WifiProfielenGeverifieerd -Ssids @($ssid)) } catch {}
    }
    return ''
}

function Remove-WifiProfielenGeverifieerd {
    # v4.23: verwijdert de opgegeven Wi-Fi-netwerken (alleen die WIJ toevoegden) en LEEST TERUG welke er nog staan. Taalonafhankelijk: de namen komen uit de profiel-XML's van Windows, niet uit de (vertaalde) uitvoer van netsh.
    param([string[]]$Ssids = @(), [string]$ProfielMap = 'C:\ProgramData\Microsoft\Wlansvc\Profiles\Interfaces', [int]$MaxPogingen = 3)
    $Ssids = @($Ssids | Where-Object { $_ } | Select-Object -Unique)
    $res = [pscustomobject]@{ Doel = $Ssids; Weg = @(); Resterend = @(); Overig = @(); Fout = '' }
    try {
        $lees = {
            $namen = @()
            if (Test-Path -LiteralPath $ProfielMap) {
                foreach ($f in @(Get-ChildItem -LiteralPath $ProfielMap -Recurse -File -Filter '*.xml' -ErrorAction SilentlyContinue)) {
                    try { $x = [xml](Get-Content -LiteralPath $f.FullName -Raw -ErrorAction Stop); $n = "$($x.WLANProfile.name)"; if ($n) { $namen += $n } } catch {}
                }
            }
            return @($namen | Select-Object -Unique)
        }
        for ($p = 1; $p -le $MaxPogingen; $p++) {
            $nu = @(& $lees)
            $teWissen = if ($p -eq 1) { $Ssids } else { @($Ssids | Where-Object { $nu -contains $_ }) }   # poging 1 verwijdert ALTIJD (ook als het profiel niet leesbaar is); daarna alleen wat er volgens teruglezen nog staat
            if (-not $teWissen.Count) { break }
            foreach ($n in $teWissen) { try { & netsh.exe wlan delete profile name="$n" 2>&1 | Out-Null } catch {} }
        }
        $na = @(& $lees)
        $res.Resterend = @($Ssids | Where-Object { $na -contains $_ })
        $res.Weg = @($Ssids | Where-Object { $na -notcontains $_ })
        $res.Overig = @($na | Where-Object { $Ssids -notcontains $_ })
        if ($res.Resterend.Count) { $res.Fout = "profiel(en) staan na $MaxPogingen poging(en) nog op het toestel: $(@($res.Resterend) -join ', ')" }
    } catch { $res.Fout = $_.Exception.Message }
    return $res
}
$Script:OogstWifiSsids = @()
function Disconnect-OogstWifi {
    # v4.5: maakt de Wi-Fi-verbinding weer los en verwijdert het profiel (de laptop blijft daarna offline, zoals bedoeld)
    param([string]$Ssid)
    if (-not $Ssid) { return }
    try { & netsh.exe wlan disconnect 2>&1 | Out-Null } catch {}
    try { return (Remove-WifiProfielenGeverifieerd -Ssids @($Ssid)) } catch { return [pscustomobject]@{ Doel = @($Ssid); Weg = @(); Resterend = @($Ssid); Overig = @(); Fout = $_.Exception.Message } }
}

function Invoke-WuOogstPhase {
    # v4.5 (12 okt 2026, Roderick: 'het oogsten moet volledig automatisch, ik kan dit niet per laptop handmatig doen'): bewijs: de Extension-drivers (Realtek/Intel/Elevoc) staan NIET in de Microsoft Update Catalog (Microsoft: een driver kan wel via Windows Update komen maar niet in de openbare catalogus staan), de server kan ze dus nooit zelf downloaden; alleen een echte Windows Update-ronde op een laptop van dat model levert ze, en pnputil /export-driver haalt ze dan uit de driver store.
    # Dit venster doet dat zelf, BEGRENSD en alleen als het nodig is (zie Get-OogstBehoefte): (1) internet: al aanwezig, of Wi-Fi uit wifi-credentials.txt; (2) Windows Update online installeren (alleen wat Windows zelf aanbiedt; geen firmware/BIOS, geen feature-update, niets dat om invoer vraagt, max 40); (3) de nieuwe drivers uit de driver store naar de INBOX op de server (wu-oogst.ps1; de server verwerkt die, scripts\188); (4) opnieuw online meten wat er nog openstaat en dat als de in-run-meting wegschrijven (bron 'oogstvenster'); (5) Wi-Fi weer los. Elke stap loggen; nooit fataal; maximaal 2 pogingen per model per 7 dagen.
    $Script:OogstRegels = @()
    function Voeg-Oogst([string]$tekst, [string]$kleur = 'Gray') { Log "[oogst] $tekst" -Color $kleur; $Script:OogstRegels += "[bewijs] oogst: $tekst" }
    $wifiSsid = ''; $uitkomst = 'niet gestart'; $pogPad = ''; $serieO = ''; $sleutelO = ''; $oogstDir = ''
    try {
        if ($State.UpdateOnlyMode) { Voeg-Oogst 'overgeslagen: update-only modus'; return }
        $sd = Get-StatusDirVroeg
        if (-not $sd -or -not (Test-Path -LiteralPath $sd -PathType Container -ErrorAction SilentlyContinue)) { Voeg-Oogst 'overgeslagen: geen server/status bereikbaar (stand-alone flow blijft ongewijzigd)'; return }
        $sleutelO = Get-ModelSleutel; $serieO = "$Serial" -replace '[^A-Za-z0-9_-]', ''
        if (-not $sleutelO -or -not $serieO) { Voeg-Oogst 'overgeslagen: modelsleutel of serienummer onbekend' 'Yellow'; return }
        $oogstDir = Join-Path $sd 'wu-oogst'
        if (Test-Path -LiteralPath (Join-Path $oogstDir 'uit.txt')) { Voeg-Oogst 'overgeslagen: uitgezet door een mens (status\wu-oogst\uit.txt)' 'Yellow'; return }
        $pogPad = Join-Path $oogstDir "pogingen\$sleutelO.txt"
        $b = Get-OogstBehoefte $sd $sleutelO
        if (-not $b.Nodig) { Voeg-Oogst "niet nodig: $($b.Reden)" 'Green'; return }
        $pog = Get-OogstPogingen $pogPad 7   # v4.14: de limiet geldt pas als het venster NODIG is (eerder werd hij gecontroleerd voordat de behoefte bekend was)
        if ($pog -ge 2) { $lu = Get-OogstLaatsteUitkomst $pogPad; Voeg-Oogst "overgeslagen: dit model is al $pog x geprobeerd in 7 dagen (maximum 2) terwijl er wel behoefte is ($($b.Reden))$(if ($lu) { " - laatste uitkomst: $lu" }) - een mens moet kijken waarom de gaten blijven" 'Yellow'; return }
        Voeg-Oogst "oogstvenster nodig: $($b.Reden)" 'Cyan'
        $cacheRoot = Split-Path -Parent $sd
        if (-not (Wait-VeiligeBatterij -Stap 'oogstvenster (Windows Update online)' -MinProcent 30 -MaxWachtMinuten 20)) { Voeg-Oogst 'overgeslagen: batterij te laag en niet aan de lader' 'Yellow'; return }
        try { New-Item -ItemType Directory -Path (Split-Path -Parent $pogPad) -Force -ErrorAction Stop | Out-Null; Add-Content -Path $pogPad -Value ("{0}`t{1}`tgestart" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $serieO) -Encoding UTF8 -ErrorAction Stop } catch { Voeg-Oogst "poging niet vastgelegd: $($_.Exception.Message)" 'Yellow' }
        $uitkomst = 'geen internet'
        if (-not (Test-InternetConnectivity)) {
            $netw = @(Get-OogstWifiGegevens $cacheRoot)
            $nodigMap = Join-Path $oogstDir 'nodig'
            if ($netw.Count -eq 0) {
                Voeg-Oogst 'GEEN internet en geen Wi-Fi-gegevens (wifi-credentials.txt): het oogstvenster is niet mogelijk. De server ziet dat dit model een online meting nodig heeft.' 'Yellow'
                try { New-Item -ItemType Directory -Path $nodigMap -Force -ErrorAction Stop | Out-Null; Set-Content -Path (Join-Path $nodigMap "$sleutelO.txt") -Value @("model = $sleutelO", "serienummer = $serieO", "gemeld = $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')", "reden = $($b.Reden)", "belemmering = geen internet en geen Wi-Fi-gegevens") -Encoding UTF8 -ErrorAction Stop } catch {}
                $uitkomst = 'geen internet en geen wifi-gegevens'; return
            }
            Voeg-Oogst "geen internet: $($netw.Count) Wi-Fi-netwerk(en) proberen (maximaal 60 s per netwerk)..."
            $wifiSsid = Connect-OogstWifi $netw 60
            if (-not $wifiSsid) { Voeg-Oogst 'Wi-Fi verbinden mislukt (geen internet): het oogstvenster is niet mogelijk' 'Yellow'; $uitkomst = 'wifi mislukt'; return }
            Voeg-Oogst "Wi-Fi verbonden met '$wifiSsid'" 'Green'
        } else { Voeg-Oogst 'internet is al aanwezig (geen Wi-Fi nodig)' 'Green' }
        try { Send-ServerStatus -Fase 'OOGSTVENSTER: Windows Update online (begrensd)' } catch {}
        # --- Windows Update online: zoeken en installeren (alleen wat Windows zelf aanbiedt) ---
        $sessie = New-Object -ComObject Microsoft.Update.Session
        $zoek = $sessie.CreateUpdateSearcher()
        $res = $zoek.Search('IsInstalled=0 and IsHidden=0')
        $aangeboden = @($res.Updates)
        $kand = @()
        foreach ($u in $aangeboden) {
            $tt = "$($u.Title)"
            if (Test-ExcludedUpdate -Title $tt) { Voeg-Oogst "niet geinstalleerd (uitgesloten door de toolset): $tt"; continue }
            # v4.21-begin
            if ($tt -match 'Firmware|BIOS|UEFI') {
                $bsF = Get-BatterijStatus
                if (-not $bsF -or -not $bsF.AanLader -or $bsF.Percent -lt 50) { Voeg-Oogst "niet geinstalleerd (firmware: alleen aan de lader en met minstens 50% batterij; nu $(if ($bsF) { "$($bsF.Percent)%, lader=$($bsF.AanLader)" } else { 'geen batterijgegevens' })): $tt" 'Yellow'; continue }
                $biosVoorF = ''; try { $biosVoorF = "$((Get-CimInstance Win32_BIOS -ErrorAction Stop).SMBIOSBIOSVersion)" } catch {}
                Voeg-Oogst "FIRMWARE wordt geinstalleerd onder de batterijregels (lader aan, $($bsF.Percent)%): $tt ; BIOS voor: '$biosVoorF' (de versie na afloop staat in [bewijs] BIOS na de herstart)" 'Cyan'
            }
            # v4.21-einde
            $vraagt = $false; try { if ($u.InstallationBehavior.CanRequestUserInput) { $vraagt = $true } } catch {}
            # v4.6d (12 okt 2026, run 2 PW0FC5BB): drivers (Type 2) met CanRequestUserInput werden overgeslagen, waardoor de Intel-oogst en de herhaalaanbod-poging niet plaatsvonden; Invoke-UpdateBatches accepteert de EULA zelf, dus drivers doen mee. Andere soorten met invoer blijven overgeslagen.
            if ($vraagt -and $u.Type -ne 2) { Voeg-Oogst "niet geinstalleerd (vraagt om invoer): $tt"; continue }
            $kand += $u
        }
        if ($kand.Count -gt 40) { Voeg-Oogst "meer dan 40 updates aangeboden ($($kand.Count)): alleen de eerste 40 nu (volgende run de rest)" 'Yellow'; $kand = @($kand | Select-Object -First 40) }
        Voeg-Oogst "online aangeboden: $($aangeboden.Count); nu te installeren: $($kand.Count)"
        $geinstalleerd = @(); $tInstall = $null
        if ($kand.Count -gt 0) {
            $bt = Invoke-UpdateBatches -Session $sessie -UpdateList $kand -BatchSize 10
            $tInstall = Get-Date
            foreach ($s in @($bt.Installed)) { Voeg-Oogst "geinstalleerd: $s" 'Green'; $geinstalleerd += "$s" }
            foreach ($f in @($bt.Failed)) { Voeg-Oogst "niet gelukt: $($f.Title)" 'Yellow' }
        }
        # --- oogsten: de nieuw geinstalleerde DRIVERS uit de driver store naar de inbox op de server ---
        $drvTitels = @()
        foreach ($u in $kand) { if ($u.Type -eq 2) { $t0 = "$($u.Title)"; if (@($geinstalleerd | Where-Object { $_ -like "*$t0" }).Count -gt 0) { $drvTitels += $t0 } } }
        $uitkomst = 'online gedaan, geen drivers geinstalleerd'
        if ($drvTitels.Count -gt 0) {
            $wuo = Join-Path $cacheRoot 'toolset\wu-oogst.ps1'
            if (-not (Test-Path -LiteralPath $wuo)) { Voeg-Oogst "wu-oogst.ps1 staat niet op de server ($wuo): niet geoogst" 'Yellow'; $uitkomst = 'wu-oogst ontbreekt op de server' }
            else {
                $lokDir = Join-Path 'C:\EspritICT' 'extra-updates'
                New-Item -ItemType Directory -Path $lokDir -Force -ErrorAction SilentlyContinue | Out-Null
                & robocopy (Split-Path -Parent $wuo) $lokDir 'wu-oogst.ps1' /R:2 /W:2 /NFL /NDL /NJH /NJS /NP | Out-Null
                $lokO = Join-Path $lokDir 'wu-oogst.ps1'
                $titelsPad = Join-Path 'C:\EspritICT' 'oogst-titels.txt'
                [IO.File]::WriteAllLines($titelsPad, [string[]]$drvTitels)
                $psExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
                $argO = '-NoProfile -ExecutionPolicy Bypass -File "' + $lokO + '" -StatusDir "' + $sd + '" -Sleutel ' + $sleutelO + ' -TitelsBestand "' + $titelsPad + '"'
                Voeg-Oogst "oogsten: $($drvTitels.Count) nieuwe driver(s) uit de driver store naar de inbox op de server (max 10 min)..." 'Cyan'
                $ro = Start-ExtraProces -Pad $psExe -Argumenten $argO -MaxMinuten 10
                $oogstOk = (-not $ro.Timeout) -and ($ro.Exit -eq 0)
                Voeg-Oogst "oogst: $(if ($ro.Timeout) { "AFGEBROKEN na $($ro.Seconden) s" } else { "klaar na $($ro.Seconden) s, exitcode $($ro.Exit)" }); de samenvatting staat op de server in status\wu-oogst\$serieO.txt" $(if ($oogstOk) { 'Green' } else { 'Yellow' })
                try { [IO.File]::Delete($titelsPad) } catch {}
                $uitkomst = $(if ($oogstOk) { "geoogst: $($drvTitels.Count) driver(s)" } else { 'oogst niet helemaal gelukt' })
            }
        } else { Voeg-Oogst 'geen driver-updates geinstalleerd: niets te oogsten' }
        # --- opnieuw online meten wat er nog openstaat = de in-run-meting voor de verificatie ---
        $na = Get-WuOnlineAanbod -TimeoutSec 240
        if ($na.Status -eq 'ok' -and @($na.Regels | Where-Object { "$_" -match '^FOUT:' }).Count -eq 0) {
            $modelTxt = ''; try { $modelTxt = "$((Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).Model)" } catch {}
            $gOk = Write-WuGaten -StatusDir $sd -Sleutel $sleutelO -Serie $serieO -Model $modelTxt -Bron 'oogstvenster' -Regels @($na.Regels)
            Voeg-Oogst "online meting NA de installatie: nog $(@($na.Regels).Count) update(s) open; naar de server geschreven: $gOk" $(if (@($na.Regels).Count -eq 0) { 'Green' } else { 'Yellow' })
            foreach ($rg in @($na.Regels)) { Voeg-Oogst "  nog open: $rg" }
            # v4.6 herhaalaanbod (norm 99,9%): wat NU nog openstaat maar in dit venster zojuist als GELUKT is geinstalleerd = 1 poging gedaan en opnieuw aangeboden = afgerond. Bewijs voor scripts\180 in status\wu-gaten\herhaling\<model>.tsv. Staat er een herstart open, dan wacht de update daarop en is het GEEN herhaal-lus: dan niets vastleggen (blijft open).
            if ($tInstall -and $geinstalleerd.Count -gt 0) {
                $herstartOpen = Test-WuHerstartNodig
                foreach ($rg in @($na.Regels)) {
                    $idm = [regex]::Match("$rg", 'id=([0-9a-fA-F\-]{36})'); if (-not $idm.Success) { continue }
                    $idr = $idm.Groups[1].Value.ToLower(); $titelR = (("$rg" -split ' \| ')[0]).Trim()
                    if (@($geinstalleerd | Where-Object { $_ -like "*$titelR" }).Count -eq 0) { continue }
                    if ($herstartOpen) { Voeg-Oogst "geinstalleerd en opnieuw aangeboden, maar er staat een herstart open: GEEN herhaalaanbod vastgelegd, blijft open (na de herstart opnieuw meten): $titelR" 'Yellow'; continue }
                    try {
                        $hm = Join-Path $sd 'wu-gaten\herhaling'; New-Item -ItemType Directory -Path $hm -Force -ErrorAction Stop | Out-Null; $hf = Join-Path $hm "$sleutelO.tsv"
                        $bestH = @(); if (Test-Path -LiteralPath $hf) { $bestH = @(Get-Content -LiteralPath $hf -Encoding UTF8 -ErrorAction SilentlyContinue) }
                        if (@($bestH | Where-Object { "$_" -like "$idr*" }).Count -eq 0) { Add-Content -Path $hf -Value ("{0}`t{1}`t{2}`t{3}`toogstvenster" -f $idr, $titelR, $tInstall.ToString('yyyy-MM-dd HH:mm:ss'), $serieO) -Encoding UTF8 -ErrorAction Stop }
                        Voeg-Oogst "herhaalaanbod: $titelR - om $($tInstall.ToString('HH:mm')) als GELUKT geinstalleerd, om $((Get-Date).ToString('HH:mm')) opnieuw aangeboden = 1 poging gedaan, afgerond volgens de norm" 'Cyan'
                    } catch { Voeg-Oogst "herhaalaanbod niet vastgelegd: $($_.Exception.Message)" 'Yellow' }
                }
            }
            try { $hf = Join-Path $oogstDir "heroogsten\$sleutelO.txt"; if (Test-Path -LiteralPath $hf) { [IO.File]::Delete($hf) } } catch {}
        } else { Voeg-Oogst "online meting NA de installatie mislukt ($($na.Status)): de verificatiestop vraagt dan zelf om internet" 'Yellow' }
    } catch { Voeg-Oogst "fout (niet fataal): $($_.Exception.Message)" 'Yellow'; $uitkomst = 'fout' }
    finally {
        if ($wifiSsid) { $wifiRes = Disconnect-OogstWifi $wifiSsid; try { Voeg-Oogst "Wi-Fi-profiel '$wifiSsid' verwijderd en teruggelezen: nog aanwezig: $(if (@($wifiRes.Resterend).Count) { @($wifiRes.Resterend) -join ', ' } else { 'geen (teruggelezen)' })" $(if (@($wifiRes.Resterend).Count) { 'Red' } else { 'Green' }) } catch {}; $nog = $false; try { $nog = Test-InternetConnectivity } catch {}; Voeg-Oogst "Wi-Fi weer losgemaakt; internet nu $(if ($nog) { 'NOG AAN - controleer dit' } else { 'UIT (zoals bedoeld)' })" $(if ($nog) { 'Yellow' } else { 'Green' }) }
        try { if ($pogPad -and (Test-Path -LiteralPath $pogPad)) { Add-Content -Path $pogPad -Value ("{0}`t{1}`t{2}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $serieO, $uitkomst) -Encoding UTF8 -ErrorAction SilentlyContinue } } catch {}
    }
}

function Get-LiveSchermAan {
    # 12 okt 2026 (Roderick: 'ik heb liever geen live, ik wil alleen het blauwe script zien'): het losse live-venster (live.ps1) staat standaard UIT. Het was bedoeld om te kunnen meekijken; dat doet nu het dashboard op de server. Aanzetten kan met een bestand live-aan.txt in C:\Windows\Temp, op de USB-stick (hoofdmap) of in de servercache (hoofdmap).
    param([string[]]$Kandidaten = @())
    if ($Kandidaten.Count -eq 0) {
        $Kandidaten = @('C:\EspritICT\live-aan.txt')
        try { foreach ($l in (Get-UsbCandidates)) { $Kandidaten += "$($l):\live-aan.txt" } } catch {}
        try { if ($Config.ServerCachePath) { $Kandidaten += (Join-Path $Config.ServerCachePath 'live-aan.txt') } } catch {}
    }
    foreach ($k in $Kandidaten) { try { if ($k -and (Test-Path -LiteralPath $k -ErrorAction SilentlyContinue)) { return $true } } catch {} }
    return $false
}
function Update-Heartbeat {
    try {
        Set-Content -Path "C:\EspritICT\audit-heartbeat.txt" -Value (Get-Date -Format 'yyyy-MM-dd HH:mm:ss') -ErrorAction SilentlyContinue
    } catch {}
    try { Send-ServerStatus } catch {}
    # v3.172, op verzoek van Roderick (10 augustus 2026, live waargenomen: scherm viel
    # meerdere keren uit tijdens EEN doorlopende run, ondanks Set-ScreenAlwaysOn die bij
    # elke script-start al draait). Set-ScreenAlwaysOn wijzigt SCHEME_CURRENT - het
    # ACTIEVE energieschema op het moment van aanroepen. Als tussentijds (zonder reboot)
    # een ander schema actief wordt - bv. doordat een OEM-stroombeheer-driver tijdens de
    # driverinstallatie een eigen schema aanmaakt/activeert, wat in dezelfde runs
    # daadwerkelijk gebeurt (Lenovo/Intel-stroombeheer-drivers) - blijven onze eerdere
    # wijzigingen op het OUDE, nu inactieve schema staan, en valt het scherm terug op
    # Windows' eigen standaard-timeout. Nog niet 100% bevestigd (geen testomgeving om
    # een schema-wissel te forceren), maar wel de meest concrete, onderbouwde verklaring
    # gevonden. Fix: i.p.v. eenmalig per script-start, nu ELKE 3 minuten opnieuw
    # toepassen via deze al overal aanwezige Update-Heartbeat-aanroep (netwerk-wacht,
    # WSUS-wacht, driverinstallatie-wacht - precies de lange stiltes) - zelfgenezend
    # binnen een paar minuten, ongeacht de exacte oorzaak van een schema-wissel.
    try {
        $nu = Get-Date
        # v3.191 (18 aug 2026, op verzoek van Roderick: "scherm blijft niet
        # aanstaan... cruciaal want ik wil niet elke keer checken"): interval
        # verkort van 3 naar 1 minuut - zelfde onderliggende vermoeden als
        # het v3.172-changelog hierboven (een OEM-stroombeheer-driver of
        # -service kan tussentijds het actieve energieschema wijzigen), maar
        # vandaag zagen we op dezelfde toestellen ook herhaaldelijk RPC-/
        # service-instabiliteit (Task Scheduler, EventLog) - als powercfg
        # daar soms ook door faalt, herstelt een kortere cyclus dat sneller.
        if (-not $Script:LaatsteScreenAlwaysOnToepassing -or ($nu - $Script:LaatsteScreenAlwaysOnToepassing).TotalMinutes -ge 1) {
            Set-ScreenAlwaysOn
            $Script:LaatsteScreenAlwaysOnToepassing = $nu
        }
    } catch {}
}

# ----------------------------------------------------------------
# 8. SCHERM AANBLIJVEN
# ----------------------------------------------------------------
function Set-ScreenAlwaysOn {
    # v3.191 (18 aug 2026, op verzoek van Roderick: "scherm blijft niet
    # aanstaan, is cruciaal"): tot nu toe gaven alle powercfg-aanroepen hier
    # hun fouten stil weg (2>$null) - als deze aanroep om wat voor reden dan
    # ook faalt (bv. door dezelfde RPC-/service-instabiliteit die vandaag ook
    # Task Scheduler/EventLog raakte), zag niemand dat terug in het log. Nu
    # zichtbaar gemaakt voor de belangrijkste instelling (monitor-timeout-ac,
    # bepaalt rechtstreeks of het scherm uitgaat) - de rest blijft ongewijzigd
    # stil, dat zijn minder kritieke/zichtbare instellingen.
    $monTimeoutErr = powercfg /change monitor-timeout-ac 0 2>&1
    if ($LASTEXITCODE -ne 0) {
        Log "  [LET OP] Scherm-aanblijven instellen (monitor-timeout-ac) gaf een fout: $monTimeoutErr" -Color Yellow
    }
    powercfg /change monitor-timeout-dc 0   2>$null
    powercfg /change standby-timeout-ac 0   2>$null
    powercfg /change standby-timeout-dc 0   2>$null
    powercfg /change hibernate-timeout-ac 0 2>$null
    powercfg /change hibernate-timeout-dc 0 2>$null
    try {
        Set-ItemProperty "HKCU:\Control Panel\Desktop" -Name "ScreenSaveActive"    -Value "0" -Force
        Set-ItemProperty "HKCU:\Control Panel\Desktop" -Name "ScreenSaverIsSecure" -Value "0" -Force
    } catch {}

    # Laptop dichtklapproble = niets doen (niet slapen, niet sluiten)
    # zodat het script doorloopt als de laptop dichtklapt of stroom wegvalt en terugkomt
    try {
        $pwrKey = "HKLM:\SYSTEM\CurrentControlSet\Control\Power\User\PowerSchemes"
        # LidCloseAction: 0 = niets, 1 = slaapstand, 2 = sluimerstand, 3 = afsluiten
        powercfg /setacvalueindex SCHEME_CURRENT SUB_BUTTONS LIDACTION 0 2>$null
        powercfg /setdcvalueindex SCHEME_CURRENT SUB_BUTTONS LIDACTION 0 2>$null
        powercfg /setactive SCHEME_CURRENT 2>$null
    } catch {}

    # Voorkom hybride slaapstand en fast-startup (kunnen resume verstoren)
    try {
        powercfg /hibernate off 2>$null
    } catch {}
}
function Set-ScreenNormal {
    powercfg /change monitor-timeout-ac 10 2>$null
    powercfg /change monitor-timeout-dc 5  2>$null
    powercfg /change standby-timeout-ac 30 2>$null
    powercfg /change standby-timeout-dc 15 2>$null
    # Lid-close actie terugzetten naar slaapstand (1)
    try {
        powercfg /setacvalueindex SCHEME_CURRENT SUB_BUTTONS LIDACTION 1 2>$null
        powercfg /setdcvalueindex SCHEME_CURRENT SUB_BUTTONS LIDACTION 1 2>$null
        powercfg /setactive SCHEME_CURRENT 2>$null
    } catch {}
    # Sluimerstand weer aan
    try { powercfg /hibernate on 2>$null } catch {}
}
Set-ScreenAlwaysOn

