# ----------------------------------------------------------------
# 10. STATE  -  bewaart voortgang zodat script na reboot hervat
# ----------------------------------------------------------------
function Get-State {
    if (Test-Path $Config.StateFile) {
        try { return (Get-Content $Config.StateFile -Raw | ConvertFrom-Json) } catch {}
    }
    return [PSCustomObject]@{
        Phase                = "INTAKE"
        Ordernummer          = ""
        Klant                = ""
        Engineer             = ""
        TotalFailed          = 0
        FailedUpdates        = @()
        InstalledUpdates     = @()
        GhostUpdates         = @()
        ReenteredAuditModeWarning = $false
        Win11EligibilityReasons = @()
        StartOsBuild         = $null
        StartDisplayVersion  = $null
        RunStartedAt         = $null
        SoftwareDistributionStartSize = $null
        WinUpdateDone        = $false
        OemDone              = $false
        StoreUpdateDone      = $false
        SoftwareUpdates      = "Nee"
        SoftwareUpdateDone   = $false
        FeatureUpdateDone    = $false
        FeatureUpdatePreBuild        = $null
        FeatureUpdateTargetAttempted = $null
        FeatureUpdateAttempts = 0
        FeatureUpdateGaveUp   = $false
        MediaUpgradeAttempts  = 0
        Win11EligibilityChecked = $false
        Win11Eligible           = $null
        RebootCount          = 0
        SysprepFailCount     = 0
        SysprepRetryFastPath = $false
        IgnorePendingUpdates = $false
        StoreUpdates         = "Nee"
        WachtOpToetsVoorSysprep = $false
        ModeChosen           = $false
        UpdateOnlyMode       = $false
        CumulativeSecurityRebootAttempts = 0
        CacheKbInstallAttempted = $false
        WsusOfflineAttempts  = 0
        ServerWachtGedaan    = $false   # v3.260: wachten-op-server al gehad in deze run (nooit twee keer)
        WsusOfflineKlaar     = $false   # v3.252: WSUS Offline succesvol afgerond (exitcode 0) - niet bij elke herstart opnieuw
        WuFoutLaatste        = ""       # v3.252: laatste WU-foutcode die een herstart veroorzaakte (zelfde fout 2x = niet nog eens herstarten)
        WuFoutAantal         = 0
        CbsHerstartPogingen  = 0   # v3.270: herstarts voor lopende update-afronding (max 2 per run)
        OemHerstartGedaan    = $false   # v3.261: herstart na driver/firmware-installatie al gehad in deze run
        OemAttempts          = 0
        BitLockerSuspendedByTool = $false
        WifiPersist          = "Nee"
        SoftwareInstallList  = ""
        SoftwareInstallDone  = $false
        BrandingLockscreen   = "Nee"
        BrandingWallpaper    = "Nee"
        BrandingBootlogo     = "Nee"
        BrandingDone         = $false
    }
}
function Save-State($s) {
    # Retry ingebouwd: als een ander proces het bestand hÃ©Ã©l even vasthoudt
    # (Defender-scan, of een overlappende autostart-trigger), gewoon opnieuw
    # proberen i.p.v. een rode "bestand in gebruik"-fout op het scherm te tonen.
    for ($poging = 1; $poging -le 5; $poging++) {
        try {
            $s | ConvertTo-Json | Set-Content $Config.StateFile -ErrorAction Stop
            return
        } catch {
            if ($poging -lt 5) { Start-Sleep -Milliseconds 300 }
        }
    }
}

$State = Get-State

# v3.251 (2 oktober 2026, LIVE GEVONDEN op een Surface Laptop 4, 033135623657): na een GESLAAGDE Sysprep (/shutdown, tagbestand
# aangemaakt) was Sysprep soms zo snel klaar dat de opruiming NA de aanroep (state-bestand + scriptkopie wissen) niet meer
# draaide; bij de eerstvolgende opstart begon het script dan opnieuw (teller 9, 10, 11) tot de lus-beveiliging ingreep.
# Vangnet: is Sysprep_succeeded.tag NIEUWER dan het state-bestand, dan is er na de laatste state-opslag een Sysprep geslaagd =
# dit is de eerste start NA Sysprep -> alleen opruimen (autostart, state, scriptkopie) en stoppen. Tijdens een gewone
# hervatting is het state-bestand altijd nieuwer dan het tagbestand (er wordt voortdurend opgeslagen), dus geen valse treffers.
try {
    $tagPad = "C:\Windows\System32\Sysprep\Sysprep_succeeded.tag"
    if ((Test-Path $Config.StateFile) -and (Test-Path $tagPad) -and (-not $State.UpdateOnlyMode)) {
        if ((Get-Item $tagPad).LastWriteTime -gt (Get-Item $Config.StateFile).LastWriteTime.AddSeconds(5)) {
            Log "POST-SYSPREP: Sysprep_succeeded.tag is nieuwer dan het state-bestand - deze start volgt op een GESLAAGDE Sysprep. Alleen opruimen, niets meer uitvoeren." -Color Green
            try { Set-ItemProperty "HKLM:\SYSTEM\Setup" -Name "SetupType" -Value 0 -Type DWord -Force } catch {}
            try { Set-ItemProperty "HKLM:\SYSTEM\Setup" -Name "CmdLine" -Value "" -Force } catch {}
            try { Set-ItemProperty "HKLM:\SYSTEM\Setup" -Name "AuditInProgress" -Value 0 -Type DWord -Force } catch {}
            foreach ($rk in "Run", "RunOnce") {
                try { Remove-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\$rk" -Name $Config.TaskName -ErrorAction SilentlyContinue } catch {}
                try { Remove-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\$rk" -Name "$($Config.TaskName)Live" -ErrorAction SilentlyContinue } catch {}
                try { Remove-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\$rk" -Name "AuditLive" -ErrorAction SilentlyContinue } catch {}
            }
            try { Unregister-ScheduledTask -TaskName $Config.TaskName -Confirm:$false -ErrorAction SilentlyContinue } catch {}
            try { Remove-Item "C:\EspritICT\audit-sysprep-started.flag" -Force -ErrorAction SilentlyContinue } catch {}
            try { Remove-Item "C:\EspritICT\audit-heartbeat.txt" -Force -ErrorAction SilentlyContinue } catch {}
            try { Remove-Item $Config.StateFile -Force -ErrorAction SilentlyContinue } catch {}
            try { Remove-Item "C:\EspritICT\live.ps1", "C:\EspritICT\live.cmd" -Force -ErrorAction SilentlyContinue } catch {}
            Log "POST-SYSPREP: opgeruimd - dit toestel is klaar voor de klant (OOBE). Script stopt." -Color Green
            try { Remove-Item $Config.LocalScript -Force -ErrorAction SilentlyContinue } catch {}
            exit 0
        }
    }
} catch {}

# v3.256 (4 oktober 2026, LIVE GEVONDEN op Surface 033135623657): na een geslaagde Sysprep (run 5, v3.255) draaide ~4 min later, tijdens de OOBE (tijdelijk account defaultuser0), het script
# OPNIEUW (lege intake, "Update-only", nieuwe AtStartup-taak + BootNext) op een toestel dat naar de klant gaat. Het vangnet hierboven werkt niet als het state-bestand al gewist is (dat gebeurt
# direct na de Sysprep-aanroep). Dit tweede vangnet is onafhankelijk van state: Sysprep_succeeded.tag bestaat EN we zitten NIET in Audit Mode EN we zitten in OOBE (HKLM\SYSTEM\Setup\OOBEInProgress=1)
# of er is een defaultuser0-sessie -> niets uitvoeren, autostarts opruimen, stoppen. De logregel noemt ook welk proces het script startte (om de echte starter te vinden).
try {
    $tagPad2 = "C:\Windows\System32\Sysprep\Sysprep_succeeded.tag"
    if (Test-Path $tagPad2) {
        $setupKey = Get-ItemProperty "HKLM:\SYSTEM\Setup" -ErrorAction SilentlyContinue
        $inAudit  = [bool]($setupKey -and (([int]$setupKey.AuditInProgress -eq 1) -or ([int]$setupKey.SetupType -eq 7)))
        $inOobe   = [bool]($setupKey -and ([int]$setupKey.OOBEInProgress -eq 1))
        $consoleUser = ""; try { $consoleUser = "$((Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).UserName)" } catch {}
        $defUser0 = ($consoleUser -match 'defaultuser0')
        if ((-not $inAudit) -and ($inOobe -or $defUser0)) {
            $ouder = ""; try { $pp = (Get-CimInstance Win32_Process -Filter "ProcessId=$PID" -ErrorAction Stop).ParentProcessId; $po = Get-CimInstance Win32_Process -Filter "ProcessId=$pp" -ErrorAction Stop; $ouder = "$($po.Name) (pid $pp): $($po.CommandLine)" } catch { $ouder = "onbekend ($_)" }
            Log "OOBE-BESCHERMING: Sysprep_succeeded.tag aanwezig, geen Audit Mode, OOBEInProgress=$inOobe, console-gebruiker='$consoleUser' - dit toestel is al klaar voor de klant; script doet NIETS en stopt. Gestart door: $ouder" -Color Yellow
            foreach ($rk in "Run", "RunOnce") { foreach ($nm in $Config.TaskName, "$($Config.TaskName)Live", "AuditLive") { try { Remove-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\$rk" -Name $nm -ErrorAction SilentlyContinue } catch {} } }
            foreach ($tn in $Config.TaskName, "$($Config.TaskName)LiveInteractive") { try { Unregister-ScheduledTask -TaskName $tn -Confirm:$false -ErrorAction SilentlyContinue } catch {} }
            try { [System.IO.File]::Delete($Config.StateFile) } catch {}
            exit 0
        }
    }
} catch {}

# Zorg dat alle properties bestaan (backwards compatibility)
$defaults = @{
    Phase="INTAKE"; Ordernummer=""; Klant=""; Engineer=""
    TotalFailed=0; FailedUpdates=@(); InstalledUpdates=@(); GhostUpdates=@(); ReenteredAuditModeWarning=$false
    Win11EligibilityReasons=@(); StartOsBuild=$null; StartDisplayVersion=$null
    RunStartedAt=$null; SoftwareDistributionStartSize=$null
    WinUpdateDone=$false; OemDone=$false
